window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0193", [{"word":"socialist","ipa_uk":"/ˈsəʊʃəlɪst/","ipa_us":"/ˈsoʊʃəlɪst/","definition_zh":"社会主义的；主张生产资料由社会共同拥有的；社会主义者","definition_en":"relating to a system in which the means of production are owned or controlled by the community as a whole, or a person who supports such a system","core_image":"一把工厂钥匙从私人手里交到全体居民推选的委员会手里，锁换了，开门的人也从一个人变成了一群人","scene":"工业城的工人把矿场与铁路收归公有，交给居民选出的委员会统一调度。A socialist programme handed the town's mines and railways to a board elected by the residents.","sceneCN":"这里 socialist 指「主张生产资料归社会共同所有的」（第 1 个义项：与社会主义经济制度相关）；句意为一项社会主义方案把城里的矿场与铁路交给居民选出的委员会管理。图中可辨识物件：矿井井架、铁轨、选票箱、公社会议桌。","pos":[{"tag":"adj.","zh":"社会主义的；主张社会共同拥有生产资料的"},{"tag":"n.","zh":"社会主义者；社会主义政党的成员"}],"collocations":[{"phrase":"socialist party","zh":"社会主义政党"},{"phrase":"socialist state","zh":"社会主义国家"},{"phrase":"socialist revolution","zh":"社会主义革命"},{"phrase":"socialist market economy","zh":"社会主义市场经济"},{"phrase":"socialist realism","zh":"社会主义现实主义"},{"phrase":"socialist ideas","zh":"社会主义思想"}],"forms":[{"label":"复数（名词）","form":"socialists"},{"label":"比较级（形容词）","form":"more socialist"},{"label":"最高级（形容词）","form":"most socialist"},{"label":"名词（制度）","form":"socialism"}],"derivatives":[{"word":"socialism","pos":"n.","zh":"社会主义；社会主义制度"},{"word":"socialistic","pos":"adj.","zh":"带有社会主义色彩的；倾向社会主义的"},{"word":"socialistically","pos":"adv.","zh":"以社会主义方式地"},{"word":"socialise","pos":"v.","zh":"使社会化；使归社会所有"}],"senses":[{"no":"01","title":"Of a collectively owned economy","titleCN":"与生产资料公有的经济制度相关","definition":"relating to an economic system in which the means of production are owned or controlled by the community rather than by private individuals","definitionCN":"与生产资料由社会共同拥有或控制、而非由私人拥有的经济制度相关","example":"A socialist programme handed the town's mines and railways to a board elected by the residents.","exampleCN":"一项社会主义方案把城里的矿场与铁路交给居民选出的委员会管理。","why":"The word is built on social, from Latin socius 'companion'; the earliest political use named people who wanted production treated as a shared possession rather than a private one.","whyCN":"这个词由 social 构成，而 social 出自拉丁 socius「同伴」；最早的政治用法指那些主张生产应作为共同财产而非私人财产的人。"},{"no":"02","title":"Of a party that seeks collective ownership","titleCN":"属于以推行公有制为纲领的政党","definition":"belonging to or run by a political party whose aim is public or collective ownership of key industries","definitionCN":"属于或由以关键产业公有为目标的政党所执掌的","example":"The socialist bloc held the majority of seats after the election.","exampleCN":"选举之后，社会主义阵营占据了多数席位。","why":"Once a set of ideas had supporters, it needed an organization; the adjective then attached itself to the parties those supporters formed.","whyCN":"一套想法有了支持者，就需要组织；这个形容词于是附着到支持者所建的政党上。"},{"no":"03","title":"Holding socialist views","titleCN":"持有社会主义主张的（用于描述人）","definition":"holding or expressing the view that major resources should be shared rather than privately held","definitionCN":"持有或表达「主要资源应共享而不应由私人占有」这一主张的","example":"Her socialist tutor argued that clean water should never be sold for profit.","exampleCN":"她那持社会主义主张的导师认为，清洁水源绝不该被拿来营利。","why":"The adjective moves easily from a system to the people who advocate it, because in English a supporter is often described by the adjective of the cause.","whyCN":"这个形容词很容易从制度移到主张者身上，因为英语里常直接用事业本身的形容词来描写支持者。"},{"no":"04","title":"A supporter of socialism","titleCN":"社会主义者（名词）","definition":"a person who believes that the main means of production should be owned or controlled collectively","definitionCN":"相信主要生产资料应由集体拥有或控制的人","example":"As a young socialist, he spent his evenings printing leaflets for the union.","exampleCN":"年轻时他是个社会主义者，晚上都在为工会印传单。","why":"The noun keeps the person and drops the system: what remains is simply the adherent, which is the everyday use of the word today.","whyCN":"名词义保留人、舍弃制度：剩下的只是追随者，这正是今天最常见的用法。"},{"no":"05","title":"Run publicly rather than for profit","titleCN":"由公共财政供给、不以营利为目的的（用于制度安排）","definition":"describing a service or institution funded and run by the public sector rather than by private owners","definitionCN":"描述由公共部门出资并运营、而非由私人拥有的服务或机构","example":"The country's socialist health service treats patients without charging them at the door.","exampleCN":"该国的社会主义医疗服务在门口不向病人收费。","why":"If ownership belongs to everybody, then the service that ownership supports is described as socialist even when the state, not a cooperative, runs it.","whyCN":"既然所有权属于所有人，那么这种所有权支撑的服务就会被称作社会主义的，即使运营者是国家而非合作社。"},{"no":"06","title":"The stage after capitalism","titleCN":"马克思主义理论中位于资本主义之后、共产主义之前的阶段","definition":"in Marxist theory, the transitional stage in which the working class holds state power before full communism","definitionCN":"马克思主义理论中，工人阶级掌握国家权力、尚未进入完全共产主义的过渡阶段","example":"In the Marxist scheme, socialist transition was expected to follow the collapse of private industry.","exampleCN":"在马克思的框架里，社会主义过渡被预期会紧随私有工业的崩溃而来。","why":"Marxist writers fixed the term to a timetable: socialism is the first stage, communism the second, so the adjective gained a technical slot in the theory of history.","whyCN":"马克思主义作家把这个词固定到一张时间表上：社会主义是第一阶段，共产主义是第二阶段，于是这个形容词在历史理论里获得了一个技术性位置。"},{"no":"07","title":"Sharing things in daily practice","titleCN":"日常生活中共享资源、不计较私有的（形容词用法）","definition":"describing an arrangement in which people pool money, tools or chores instead of each keeping a private share","definitionCN":"描述人们把钱、工具或家务集中共用、而非各自保留一份的安排","example":"The flatmates ran a socialist kitchen: one shopping list, one pot, one bill.","exampleCN":"室友们实行社会主义式的厨房：一张采购单、一口锅、一张账单。","why":"The political idea of shared ownership is small enough to fit a household, so the adjective is used half-jokingly for any pooled arrangement.","whyCN":"共同所有这一政治观念小到可以装进一个家庭，于是这个形容词被半开玩笑地用于任何凑份子的安排。"},{"no":"08","title":"A member of a socialist party","titleCN":"社会主义政党的成员（名词，组织义）","definition":"an enrolled member or official of a party that carries the word in its name","definitionCN":"在名称中带有该词的政党里注册的成员或干部","example":"Delegates from every socialist in the district met to choose a candidate.","exampleCN":"全区每一位社会主义政党成员都派代表来选候选人。","why":"Party names froze the adjective into a label, and a label produces members: the noun then means the card-carrying person, not merely the believer.","whyCN":"党名把这个形容词冻结成一个标签，而标签会产生成员：名词于是指持证的人，而不只是相信的人。"},{"no":"09","title":"Of state-approved art","titleCN":"国家认可的现实主义艺术风格的（用于文艺）","definition":"relating to the officially favoured realistic style in art and literature of certain state systems","definitionCN":"与某些国家体制下官方推崇的现实主义文艺风格相关的","example":"The novelist was praised for socialist realism, then quietly stopped being published.","exampleCN":"这位小说家先因社会主义现实主义受到赞扬，后来悄悄不再被出版。","why":"Art policy borrowed the political adjective to name a style that was supposed to serve collective goals, so the word ended up describing paint as well as ownership.","whyCN":"文艺政策借用了这个政治形容词来命名一种被要求服务集体目标的风格，于是这个词最终既描述所有制，也描述画笔。"}],"etymology":{"intro":{"en":"Socialist goes back to Latin socius 'companion, ally' through socialis and the noun suffix -ist. The political sense was coined in the early nineteenth century, when writers needed a name for supporters of collective ownership.","cn":"socialist 经 socialis 上溯到拉丁 socius「同伴、盟友」，末尾是表示「人」的后缀；政治义在十九世纪前期被造出，用来称呼主张共同所有权的人。"},"items":[{"era":"LATIN SOCIUS","en":"Socius meant a companion or an ally, and sociare 'to join together' came from it. The root picture is people bound to one another, not a state above them.","cn":"socius 意为同伴或盟友，动词 sociare「联合」由它而来。词根给出的画面是彼此联结的人，而不是高踞其上的一种体制。"},{"era":"LATIN SOCIALIS","en":"Socialis meant 'of companions, of an alliance' and passed through French social into English, where social first meant 'belonging to a community'.","cn":"socialis 意为「同伴的、同盟的」，经法语 social 进入英语，social 最初指「属于共同体的」。"},{"era":"SUFFIX -IST","en":"The agent suffix -ist, from Greek -istēs through French, marks a person who practises, follows or advocates something, which is exactly what the early users wanted to name.","cn":"表示人的后缀经法语来自希腊语，标记从事、追随或主张某事的人，这正是早期使用者想要命名的对象。"},{"era":"EARLY NINETEENTH CENTURY","en":"Socialist appears in English in the 1820s and 1830s, first for followers of early cooperative thinkers and then for anyone who wanted key industries owned in common.","cn":"socialist 在十九世纪二三十年代出现于英语，最初指早期合作派思想家的追随者，随后指任何主张关键产业共同所有的人。"},{"era":"MARXIST NARROWING","en":"Marxist writers later fixed socialism to the stage between capitalism and communism, and the adjective followed that timetable in political theory while the noun stayed broad in ordinary speech.","cn":"马克思主义作家后来把社会主义固定为资本主义与共产主义之间的阶段，形容词在政治理论中跟随这张时间表，而名词在日常语言里仍保持宽泛。"},{"era":"APPROXIMATE FIRST DATES","en":"The earliest English citation is not precisely fixed: the 1820s date is approximate, and claims of an earlier appearance in radical pamphlets are unverified.","cn":"英语中最早的书证没有精确年代：十九世纪二十年代只是约数；至于更早出现在激进小册子中的说法，尚未得到证实。"}]},"similar":{"note":{"en":"The first group shares the Latin root socius and is easily mixed up; the second group names neighbouring political or economic positions.","cn":"第一组共享拉丁词根 socius，极易混淆；第二组是相邻的政治与经济立场。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"social","ipa":"/ˈsəʊʃl/","tag":"same root","definition":"The base adjective meaning 'of a community or of companionship'; it says nothing about ownership.","definitionCN":"基础形容词，指「共同体的、交际的」，并不涉及所有权。"},{"word":"socialism","ipa":"/ˈsəʊʃəlɪzəm/","tag":"same family","definition":"The system or doctrine itself, formed with the noun suffix -ism; the person takes -ist instead.","definitionCN":"制度或学说本身，用表示主义的名词后缀构成；指人时改用另一个后缀。"},{"word":"socialise","ipa":"/ˈsəʊʃəlaɪz/","tag":"same family","definition":"To bring something under public ownership, or to mix with others; the second sense has nothing to do with politics.","definitionCN":"指收归公有，也指与人交往；后一义与政治无关。"},{"word":"sociable","ipa":"/səʊˈsiːəbl/","tag":"same root","definition":"From the same socius but meaning friendly and easy to talk to, not collective.","definitionCN":"同出 socius，却指友善、好相处，与集体所有无关。"},{"word":"society","ipa":"/səˈsaɪəti/","tag":"same root","definition":"The body of people itself, from societas; it names the group, not a doctrine about it.","definitionCN":"指人群本身，出自 societas；它命名群体，而非关于群体的学说。"}]},{"heading":"NEAR MEANING","entries":[{"word":"communist","ipa":"/ˈkjuːmjuːnɪst/","tag":"party neighbour","definition":"Built on communis 'shared' rather than socius, and in Marxist usage it names the later stage; the two labels sit next to each other but on different roots.","definitionCN":"由 communis「共同的」构成，而非 socius；在马克思主义用法中指更晚的阶段；两个标签相邻，却不同根。"},{"word":"liberal","ipa":"/ˈlɪbərəl/","tag":"opposing position","definition":"Favouring individual rights and private ownership, which is the usual contrast in party politics.","definitionCN":"偏向个人权利与私有制，是政党政治中常见的对照立场。"},{"word":"conservative","ipa":"/kənˈsɜːvətɪv/","tag":"opposing position","definition":"Favouring existing institutions and slow change; in economic debate it usually defends private ownership.","definitionCN":"偏向现存制度与缓慢变革；在经济辩论中通常维护私有制。"},{"word":"reformist","ipa":"/rɪˈfɔːmɪst/","tag":"neighbouring method","definition":"One who wants change through gradual legal reform rather than revolution, a label that cuts across the socialist camp.","definitionCN":"主张通过渐进合法改革而非革命来实现变革的人，这一标签横穿社会主义阵营内部。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin root, the real word family and real fixed phrases.","cn":"正常联想使用真实的拉丁词根、真实的同族词与真实的固定搭配。"},"normal":[{"en":"Socius is Latin for companion, so socialist began as the word for people who treat property as a shared companion's business.","cn":"socius 是拉丁语「同伴」，socialist 起初指把财产当作同伴共同事务的人。"},{"en":"The family runs social, society, socialism, socialist, socialistic and socialise.","cn":"同族词有 social、society、socialism、socialist、socialistic 与 socialise。"},{"en":"Fixed phrases mark the political sense: socialist party, socialist state, socialist market economy.","cn":"固定搭配标出政治义：社会主义政党、社会主义国家、社会主义市场经济。"},{"en":"The suffix -ist names a person, so a socialist is first of all somebody, not something.","cn":"表示人的后缀用来指人，所以 socialist 首先指某个人，而不是某样东西。"},{"en":"Art history adds socialist realism, which shows how far the adjective travelled from ownership to style.","cn":"艺术史里还有社会主义现实主义，可见这个形容词从所有制一路走到了风格。"}],"abstract":[{"en":"Picture a ring of keys passed hand to hand around a table until nobody remembers who first held them.","cn":"想象一串钥匙在桌边逐手传递，传到后来没人记得最初握在谁手里。"},{"en":"Picture a field where every household owns one furrow and no household owns the field.","cn":"想象一片田，每家有一垄，却没有一家拥有整片田。"},{"en":"Picture a lecture hall where the same slogan is chalked on every blackboard in a different hand.","cn":"想象一间讲堂，每块黑板上都用不同笔迹写着同一句口号。"}]},"examples":[{"en":"The constitution describes the country as a socialist state.","cn":"宪法把这个国家描述为社会主义国家。"},{"en":"Her grandfather joined the socialist movement as a printer in 1905.","cn":"她的祖父在一九零五年作为印刷工加入了社会主义运动。"},{"en":"Critics called the housing plan socialist because rents were capped by law.","cn":"批评者称这项住房计划是社会主义的，因为租金由法律设了上限。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「social（社会的）+ ist（人）」——主张社会共同拥有产业的人 → 社会主义者","word":"socialist"},"root":"拉丁 socius「同伴、盟友」→ socialis「同伴的、同盟的」→ 法语 social → 英语 social；加表示人的后缀构成 socialist「社会主义者、社会主义的」。","sensesIntro":{"en":"Nine senses follow one transfer of a key: an economy is held in common, the holders form a party, a person carries the label, a public service inherits it, theory gives it a stage, a household jokes with it, and an art policy turns it into a style.","cn":"九个义项围绕一次钥匙的移交展开：经济归共同所有，所有者结成政党，个人带上这个标签，公共服务继承它，理论给它一个阶段，家庭拿它开玩笑，文艺政策把它变成一种风格。"},"semanticMap":{"core":{"en":"CORE IMAGE: one key handed from a single owner to a committee chosen by everyone at the table.","cn":"核心意象：一把钥匙从唯一的持有者手里，交到桌边所有人推选的委员会手里。"},"chain":["SHARED OWNERSHIP","PARTY OF HOLDERS","THE PERSON","PUBLIC SERVICE","HISTORICAL STAGE","ART STYLE"],"branches":[{"senses":"01 · 05","en":"COMMON PURSE: whether a mine or a clinic, what is shared is the thing itself, and the bill is paid in common.","cn":"共同的钱袋：无论矿场还是诊所，被共享的都是事物本身，账单也由大家来付。"},{"senses":"02 · 08","en":"THE ORGANISED BODY: supporters become a party, and the party's name turns believers into card-carrying members.","cn":"组织起来的群体：支持者结成政党，党名又把相信的人变成持证的成员。"},{"senses":"03 · 04","en":"THE SINGLE HOLDER: the adjective describes one person's view, and the noun names that person.","cn":"单个持有者：形容词描述一个人的主张，名词就指这个人。"},{"senses":"06","en":"THE TIMETABLE: political theory files the word into a slot between two other stages.","cn":"时间表：政治理论把这个词归档到另两个阶段之间的格子里。"},{"senses":"07 · 09","en":"EVERYDAY AND ARTISTIC ECHOES: a shared kitchen and an approved painting style both borrow the political word for something smaller or narrower.","cn":"日常与艺术的回声：合用的厨房与被批准的画风，都借用这个政治词去指更小或更窄的东西。"}]},"affixes":{"intro":{"en":"Socialist is a Latin root plus a person-forming suffix, and the same root supports a large English family.","cn":"socialist 是一个拉丁词根加一个指人后缀，同一词根还支撑起一个庞大的英语词族。"},"latinIntro":{"en":"Latin socius 'companion' gives social, society, sociable and sociable; the suffix -ist comes from Greek through French and names the person.","cn":"拉丁 socius「同伴」衍生 social、society、sociable 等词；指人后缀经法语来自希腊语。"},"items":[{"word":"soci-","structure":"socius (Latin noun, 'companion, ally')","meaning":"companion; ally","meaningCN":"同伴；盟友","example":"The root supplies the picture of people bound together.","exampleCN":"这个词根提供「人彼此联结」的画面。"},{"word":"-al","structure":"Latin adjective ending -alis","meaning":"relating to","meaningCN":"与……相关的","example":"It turns the noun of companionship into an adjective.","exampleCN":"它把表示同伴的名词变成形容词。"},{"word":"social","structure":"soci- plus -al","meaning":"of a community","meaningCN":"共同体的；社会的","example":"The adjective is older than the political doctrine.","exampleCN":"这个形容词比政治学说更古老。"},{"word":"-ism","structure":"Greek -ismos through French","meaning":"doctrine, system","meaningCN":"学说；制度","example":"It names the system as a whole.","exampleCN":"它命名整套制度。"},{"word":"socialism","structure":"social plus -ism","meaning":"collective ownership as a system","meaningCN":"社会主义制度","example":"The noun names what the adjective describes.","exampleCN":"名词命名形容词所描述的制度。"},{"word":"-ist","structure":"Greek -istēs through French","meaning":"person who follows or practises","meaningCN":"从事或主张……的人","example":"It names the adherent rather than the system.","exampleCN":"它指追随者，而不是制度。"},{"word":"socialist","structure":"socialism plus -ist","meaning":"a supporter; of that system","meaningCN":"社会主义者；社会主义的","example":"The same form serves as noun and adjective.","exampleCN":"同一词形兼作名词与形容词。"},{"word":"-istic","structure":"-ist plus -ic","meaning":"having the character of","meaningCN":"具有……性质的","example":"It builds the descriptive adjective.","exampleCN":"它构成描述性的形容词。"},{"word":"socialistic","structure":"socialist plus -istic","meaning":"leaning toward socialism","meaningCN":"带有社会主义色彩的","example":"The suffix softens the claim into a tendency.","exampleCN":"后缀把断言软化为一种倾向。"},{"word":"socialise","structure":"social plus -ise","meaning":"to make collective; to mix socially","meaningCN":"使公有；与人交往","example":"The verb splits into a political and a social sense.","exampleCN":"这个动词分出政治义与交际义。"}],"latinEntries":[{"word":"socius","structure":"socius, socii (m., second declension)","meaning":"companion, ally","meaningCN":"同伴；盟友"},{"word":"socialis","structure":"socialis, sociale (adj., third declension)","meaning":"of companions, allied","meaningCN":"同伴的；同盟的"},{"word":"societas","structure":"societas, societatis (f., third declension)","meaning":"association, partnership","meaningCN":"联合；合伙"},{"word":"sociare","structure":"sociare, sociavi, sociatum (verb, first conjugation)","meaning":"to join, unite","meaningCN":"联合；结合"}],"derivatives":[{"word":"socialism","pos":"n.","zh":"社会主义；社会主义制度"},{"word":"socialistic","pos":"adj.","zh":"带有社会主义色彩的"},{"word":"socialistically","pos":"adv.","zh":"以社会主义方式地"},{"word":"socialise","pos":"v.","zh":"使社会化；使归社会所有"}]}},{"word":"communism","ipa_uk":"/ˈkɒmjunɪzəm/","ipa_us":"/ˈkɑːmjunɪzəm/","definition_zh":"共产主义；共产主义制度；（主张财产公有的）公社式共同生活","definition_en":"a political and economic doctrine that abolishes private ownership of the main means of production and aims at a classless society, or a system based on it","core_image":"粮仓的门被卸下，原本各家各户的锁换成一扇谁都能推开的门，粮堆上只留一张共同清点的木牌","scene":"冷战年代的课堂上，老师把两种制度分写在黑板两侧，让学生逐条比较。The teacher wrote communism on the left of the blackboard and market capitalism on the right.","sceneCN":"这里 communism 指主张主要生产资料公有、最终消灭阶级的学说与制度（第 1 个义项：共产主义学说）；句意为老师把共产主义写在黑板左边、把市场资本主义写在右边。图中可辨识物件：黑板、粉笔、两列对照条目、讲台。","pos":[{"tag":"n.","zh":"共产主义（学说与制度）；公社式的共同生活"}],"collocations":[{"phrase":"the collapse of communism","zh":"共产主义的崩溃"},{"phrase":"the rise of communism","zh":"共产主义的兴起"},{"phrase":"scientific communism","zh":"科学共产主义"},{"phrase":"primitive communism","zh":"原始共产主义"},{"phrase":"anti-communism","zh":"反共产主义"},{"phrase":"Marxist communism","zh":"马克思主义的共产主义"}],"forms":[{"label":"单数（不可数）","form":"communism"},{"label":"复数（指多种理论主张，少见）","form":"communisms"},{"label":"名词（人）","form":"communist"},{"label":"形容词","form":"communist"},{"label":"形容词（学说色彩）","form":"communistic"}],"derivatives":[{"word":"communist","pos":"n./adj.","zh":"共产主义者 / 共产主义的"},{"word":"communistic","pos":"adj.","zh":"共产主义式的；带共产主义色彩的"},{"word":"communise","pos":"v.","zh":"使公有化；使共产化"},{"word":"anti-communism","pos":"n.","zh":"反共产主义"}],"senses":[{"no":"01","title":"The doctrine of common ownership","titleCN":"主张主要生产资料公有、消灭阶级的学说","definition":"the political and economic doctrine that private ownership of the main means of production should be abolished in favour of common ownership","definitionCN":"主张废除主要生产资料的私有制、改行共同所有制的政治经济学说","example":"The teacher wrote communism on the left of the blackboard and market capitalism on the right.","exampleCN":"老师把共产主义写在黑板左边，把市场资本主义写在右边。","why":"The word joins communis 'shared' to the doctrine suffix -ism, so it names a belief about what ought to be shared before it names anything that exists.","whyCN":"这个词把 communis「共同的」与表示学说的后缀连在一起，因此它先命名一种关于「什么该共享」的信念，然后才命名现实存在的东西。"},{"no":"02","title":"The higher stage of history","titleCN":"历史理论中位于社会主义之后的更高阶段","definition":"in Marxist theory, the higher phase of social development in which classes and the state have withered away","definitionCN":"马克思主义理论中阶级与国家已消亡的社会发展更高阶段","example":"In the textbook diagram, communism came after a long transitional stage labelled socialism.","exampleCN":"在教科书的图示里，共产主义排在一个被称为社会主义的漫长过渡阶段之后。","why":"Theory needed two names for two stages, and the more radical one was given to the later stage, where even the transitional state disappears.","whyCN":"理论需要两个名字对应两个阶段，更彻底的那一个被分配给更晚的阶段，连过渡性的国家也在此消失。"},{"no":"03","title":"The movement that pursues it","titleCN":"以建立共产主义为目标的运动与政党力量","definition":"the organized movement and parties working toward that doctrine, taken as a political force","definitionCN":"作为政治力量、为实现该学说而组织起来的运动与政党","example":"Historians trace the spread of communism through trade unions and student circles.","exampleCN":"历史学者追踪共产主义如何经由工会与学生圈子扩散。","why":"A doctrine with followers turns into a movement, so the same noun covers the idea and the network that carries it.","whyCN":"一种有追随者的学说会变成一场运动，于是同一个名词既指想法，也指承载它的网络。"},{"no":"04","title":"The system of a state","titleCN":"以该学说立国的国家制度","definition":"the political and economic system of a state organized along those lines, especially in the twentieth century","definitionCN":"按这套路线组织起来的国家制度，尤指二十世纪的情形","example":"The museum's east wing is devoted to daily life under communism.","exampleCN":"博物馆东翼专门展出共产主义制度下的日常生活。","why":"Once a movement takes power, the doctrine becomes an administration, and the noun shifts from belief to government.","whyCN":"一旦运动取得政权，学说就变成一套行政，名词也从信念转向政府。"},{"no":"05","title":"Shared goods in a religious community","titleCN":"宗教团体内部的财产共有生活","definition":"a way of living in which a religious community holds all goods in common and distributes them by need","definitionCN":"宗教团体把全部财物共同持有、按需分配的生活方式","example":"Early monastic rules described a communism of tools and food rather than of industry.","exampleCN":"早期的修道规章描述的是工具与食物的共有，而不是工业的共有。","why":"The word was applied to any pooling of goods long before factories existed, so the religious sense is one of the oldest layers in the noun.","whyCN":"早在工厂出现之前，这个词就被用于任何财物集中的安排，因此宗教义是这个名词最古老的层次之一。"},{"no":"06","title":"Primitive communism in anthropology","titleCN":"人类学中早期族群共同占有资源的阶段","definition":"a stage in some anthropological schemes in which a small band held land and game collectively","definitionCN":"某些人类学框架中，小型群体共同占有土地与猎物的阶段","example":"Field notes from the expedition were read as evidence of primitive communism.","exampleCN":"考察队的田野笔记被解读为原始共产主义的证据。","why":"Anthropologists borrowed the word for societies with no state and no private title, which pushed the term far back in time.","whyCN":"人类学家把这个词借来描述既无国家也无私有产权凭证的社会，从而把这个词推到了极早的年代。"},{"no":"07","title":"Any pooled arrangement, jokingly","titleCN":"日常戏称的「共用」「凑份子」","definition":"a joking use for any household or office arrangement in which everything is pooled","definitionCN":"戏称家庭或办公室里一切共用、凑份子的安排","example":"With one bank account and one bicycle, the couple called their flat pure communism.","exampleCN":"一对夫妻只有一个银行账户和一辆自行车，便戏称自家是纯粹的共产主义。","why":"Everyday speech borrows grand political nouns for small domestic facts, because the contrast is what makes the joke.","whyCN":"日常语言常借宏大的政治名词来说细小的家事，因为反差本身就是笑点。"},{"no":"08","title":"A label in cold-war rhetoric","titleCN":"冷战话语中作为阵营标签的用法","definition":"the name used in cold-war rhetoric to label an opposing bloc, its parties and its sympathisers","definitionCN":"冷战话语中用来标记对立阵营、其政党与同情者的名称","example":"The phrase 'the threat of communism' filled the newspaper's editorials for a decade.","exampleCN":"「共产主义的威胁」这一说法在该报的社论里连用了十年。","why":"A noun used as an accusation stops describing a theory and starts marking an enemy, which is how the word acquired its rhetorical weight.","whyCN":"当名词被用作指控时，它就不再描述一种理论，而开始标记一个敌人；这个词的分量正是这样得来的。"}],"etymology":{"intro":{"en":"Communism joins Latin communis 'shared, common' to the doctrine suffix -ism. The modern political sense was coined in French around 1840 and entered English soon after; the older sense of shared goods in a religious community goes back much further.","cn":"communism 把拉丁 communis「共同的、公用的」与表示学说的后缀连在一起；现代政治义约在一八四零年前后由法语造出，随即进入英语；宗教团体财物共有的旧义则早得多。"},"items":[{"era":"LATIN COMMUNIS","en":"Communis meant 'shared by several, common'. It is generally thought to be com- 'together' plus a root related to munus 'service, duty', so the original picture is duties shared among several people.","cn":"communis 意为「由数人共用、公共的」。一般认为它由表示「共同」的前缀加一个与 munus「义务、职责」相关的词根构成，因此原初画面是数人分担职责。"},{"era":"UNCERTAIN DEEPER FORM","en":"Source uncertain (pre-Latin formation): the exact shape of the element behind munus is unsettled, and the forms offered for it are reconstructions rather than attested words.","cn":"来源不确定（拉丁语之前的构形）：munus 背后那个成分的确切形态没有定论，为它给出的形式都是重构形式，并非有书证的实际词形。"},{"era":"FRENCH COMMUNISME","en":"French writers coined communisme around 1840 for the doctrine that property should be held in common; the suffix -isme marked a system of ideas, not a single act.","cn":"法语作者约在一八四零年造出 communisme，指财产应共同持有的学说；后缀标记的是一套观念体系，而非单个动作。"},{"era":"ENGLISH ENTRY","en":"English communism appears in the 1840s and was fixed to Marxist usage after 1848, when the manifesto gave the word a programmatic definition.","cn":"英语 communism 在一八四零年代出现，一八四八年之后被固定到马克思主义用法上，因为宣言给了这个词一个纲领性定义。"},{"era":"OLDER RELIGIOUS SENSE","en":"Long before the political coinage, English used the same idea for religious communities that held goods in common, a pattern described in early church accounts.","cn":"在政治造词之前很久，英语就用同一观念描述财物共有的宗教团体，早期教会文献中已有这种模式。"},{"era":"TWENTIETH-CENTURY WEIGHT","en":"In the cold war the noun was applied to whole states and blocs, and its sense widened from a theory to a form of government and a geopolitical label.","cn":"冷战期间这个名词被用于整个国家与阵营，词义从一种理论扩展到一种政府形态与一个地缘政治标签。"}]},"similar":{"note":{"en":"The first group shares the Latin word for 'shared' and is constantly confused; the second group names rival doctrines and neighbouring ideas.","cn":"第一组共享那个表示「共同的」的拉丁词，常被混淆；第二组是对立学说与相邻观念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"communist","ipa":"/ˈkɒmjunɪst/","tag":"same family","definition":"The person or the adjective; it names a holder of the belief, while communism names the belief itself.","definitionCN":"指人或形容词；它命名信念的持有者，而 communism 命名信念本身。"},{"word":"communal","ipa":"/kəˈmjuːnl/","tag":"same root","definition":"Meaning shared by a group, usually a small one such as a household or village; no political doctrine is implied.","definitionCN":"指由一群人共用，通常是小群体如家庭或村庄，不含政治学说。"},{"word":"commune","ipa":"/ˈkɒmjuːn/","tag":"same root, different noun","definition":"A small community sharing property and work, or a local government unit; it is a place or a body, not a theory.","definitionCN":"指共享财产与劳动的小型共同体，或地方行政单位；它是场所或机构，不是理论。"},{"word":"community","ipa":"/kəˈmjuːnəti/","tag":"same root","definition":"A group of people living or acting together; the word describes the group, never the ownership rules.","definitionCN":"指共同生活或行动的一群人；它描述群体，而不描述所有权规则。"},{"word":"common","ipa":"/ˈkɒmən/","tag":"same root","definition":"The everyday adjective for what is shared or ordinary, and the oldest member of the family in English.","definitionCN":"指共用或普通的日常形容词，是这个词族在英语里最古老的成员。"}]},{"heading":"NEAR MEANING","entries":[{"word":"socialism","ipa":"/ˈsəʊʃəlɪzəm/","tag":"stage before","definition":"Built on socius 'companion', it names the transitional stage in which the state still exists; communism is the later, classless stage.","definitionCN":"由 socius「同伴」构成，指国家仍存在的过渡阶段；共产主义是更晚的无阶级阶段。"},{"word":"collectivism","ipa":"/kəˈlektɪvɪzəm/","tag":"near meaning","definition":"The broader principle that a group rather than an individual should own or decide; it can describe farms, studios or whole economies.","definitionCN":"更宽的原则：由群体而非个人拥有或决定；可用于农场、工作室或整个经济。"},{"word":"Marxism","ipa":"/ˈmɑːksɪzəm/","tag":"parent theory","definition":"The analytical framework that predicted the stages; communism is one stage within it, not the whole framework.","definitionCN":"预测各阶段的分析框架；共产主义是其中某个阶段，而非整套框架。"},{"word":"capitalism","ipa":"/ˈkæpɪtəlɪzəm/","tag":"opposing system","definition":"The system of private ownership and market exchange against which the doctrine defined itself.","definitionCN":"私有制与市场交换的制度，这套学说是相对它来定义自身的。"},{"word":"social democracy","ipa":"/ˌsəʊʃl dɪˈmɒkrəsi/","tag":"reformist neighbour","definition":"A movement seeking public services and redistribution through elections, without abolishing private ownership.","definitionCN":"主张通过选举实现公共服务与再分配、但不废除私有制的运动。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin root, the real word family and real fixed phrases.","cn":"正常联想使用真实的拉丁词根、真实的同族词与真实的固定搭配。"},"normal":[{"en":"Communis is Latin for shared, so communism is the doctrine of the shared thing.","cn":"communis 是拉丁语「共同的」，communism 就是关于「共同持有」的学说。"},{"en":"The family runs common, community, communal, commune, communism and communist.","cn":"同族词有 common、community、communal、commune、communism 与 communist。"},{"en":"Fixed phrases mark the historical sense: the collapse of communism, primitive communism, anti-communism.","cn":"固定搭配标出历史义：共产主义的崩溃、原始共产主义、反共产主义。"},{"en":"The suffix -ism names a doctrine, so communism is an idea before it is a government.","cn":"表示学说的后缀命名一种主义，所以共产主义先是一个观念，然后才是一种政府。"},{"en":"The stage sense pairs it with socialism, which sits one step earlier in the same theory.","cn":"阶段义把它与社会主义配对，后者在同一理论里早一步。"}],"abstract":[{"en":"Picture a granary whose separate padlocks are all replaced by one door anyone may push open.","cn":"想象一座粮仓，各家各户的挂锁全被换成一扇谁都能推开的门。"},{"en":"Picture a ledger with no owner column at all, only a list of needs on the left.","cn":"想象一本账，根本没有所有者一栏，左边只列着需求。"},{"en":"Picture two blackboards facing each other, each sure the other's handwriting is wrong.","cn":"想象两块相对的黑板，各自都确信对面的字迹是错的。"}]},"examples":[{"en":"The lecture traced communism from a pamphlet idea to a state system.","cn":"这场讲座追溯了共产主义如何从小册子里的想法变成国家制度。"},{"en":"Some religious orders practised a communism of food and tools.","cn":"一些修会实行食物与工具的共有。"},{"en":"The two blocs used the word as a weapon rather than a description.","cn":"两个阵营把这个词当作武器，而不是当作描述。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「commun（共同）+ ism（主义）」——主张财产共同持有的主义 → 共产主义","word":"communism"},"root":"拉丁 communis「共同的、公用的」，由表示「共同」的前缀加一个与 munus「义务、职责」相关的词根构成（更深构形存疑）→ 法语 communisme → 英语 communism。","sensesIntro":{"en":"Eight senses follow one granary door: the doctrine opens it, history gives it a later stage, a movement carries it, a state runs it, a monastery shares its tools, anthropology pushes it far back, a household jokes with it, and a cold-war editorial turns it into a label.","cn":"八个义项围绕一扇粮仓的门：学说把门打开，历史给它一个更晚的阶段，运动把它抬走，国家把它运转起来，修道院共享工具，人类学把它推到远古，家庭拿它开玩笑，冷战社论把它变成一个标签。"},"semanticMap":{"core":{"en":"CORE IMAGE: a shared granary with one door and no owner's column in the ledger.","cn":"核心意象：一座共用的粮仓，只有一扇门，账本里没有「所有者」这一栏。"},"chain":["SHARED STORE","DOCTRINE OF THE SHARED","A LATER STAGE","ORGANISED FORCE","STATE IN PRACTICE","COMMON LIFE"],"branches":[{"senses":"01 · 03","en":"IDEA AND NETWORK: the doctrine and the movement that carries it are one noun seen twice.","cn":"想法与网络：学说与承载它的运动，是同一个名词的两次显形。"},{"senses":"02","en":"THE FAR STAGE: theory schedules the word later than socialism, where even the state is gone.","cn":"更远的阶段：理论把这个词排在社会主义之后，那里连国家也消失了。"},{"senses":"04 · 08","en":"POWER AND ACCUSATION: a doctrine becomes a government, and an enemy label.","cn":"权力与指控：学说变成一种政府，也变成一个敌人标签。"},{"senses":"05 · 06","en":"SMALL AND ANCIENT COMMUNITIES: a monastery's tools and a band's hunting ground are the same sharing at other scales.","cn":"小而古老的共同体：修道院的工具与部落的猎场，是同一件事的另一种尺度。"},{"senses":"07","en":"THE DOMESTIC JOKE: one bicycle and one bank account borrow the grand noun for a flat.","cn":"家中的玩笑：一辆自行车与一个账户，借用了这个宏大名词来形容一套住房。"}]},"affixes":{"intro":{"en":"Communism is a Latin adjective of sharing plus a doctrine suffix; both parts recur across English.","cn":"communism 由一个表示「共用」的拉丁形容词加一个表示学说的后缀构成，两部分在英语里反复出现。"},"latinIntro":{"en":"Latin communis gives common, community, communal and commune; the suffix -ism, from Greek through French, names systems of thought.","cn":"拉丁 communis 衍生 common、community、communal 与 commune；表示学说的后缀经法语来自希腊语。"},"items":[{"word":"commun-","structure":"communis (Latin adjective, 'shared, common')","meaning":"shared by several","meaningCN":"由数人共用","example":"The root carries the picture of a common store.","exampleCN":"这个词根带着「共用储备」的画面。"},{"word":"-is","structure":"Latin adjective ending -is","meaning":"of the kind","meaningCN":"属于该类","example":"It marks the adjective of sharing.","exampleCN":"它标出表示共用的形容词。"},{"word":"common","structure":"communis through Old French comun","meaning":"shared; ordinary","meaningCN":"共用的；普通的","example":"The oldest English member of the family.","exampleCN":"这个词族在英语里最古老的成员。"},{"word":"community","structure":"common plus -ity","meaning":"a body of people together","meaningCN":"共同体；社区","example":"The suffix turns sharing into a group.","exampleCN":"后缀把「共用」变成一群人。"},{"word":"communal","structure":"community plus -al","meaning":"of a group's shared use","meaningCN":"群体共用的","example":"It describes the arrangement, not the doctrine.","exampleCN":"它描述安排，而非学说。"},{"word":"-ism","structure":"Greek -ismos through French","meaning":"system of belief","meaningCN":"学说；主义","example":"It names doctrines as wholes.","exampleCN":"它把学说作为整体来命名。"},{"word":"communism","structure":"commun- plus -ism","meaning":"the doctrine of common ownership","meaningCN":"共产主义","example":"The noun names the belief and later the system.","exampleCN":"名词指信念，后来也指制度。"},{"word":"communist","structure":"communism plus -ist","meaning":"adherent; of the doctrine","meaningCN":"共产主义者；共产主义的","example":"The person and the adjective share one form.","exampleCN":"人与形容词共用同一词形。"},{"word":"-istic","structure":"-ist plus -ic","meaning":"having the character of","meaningCN":"具有……性质的","example":"It builds the descriptive adjective.","exampleCN":"它构成描述性形容词。"},{"word":"communise","structure":"communal plus -ise","meaning":"to make common","meaningCN":"使公有化","example":"The verb names the act of transferring ownership.","exampleCN":"这个动词命名转移所有权的动作。"}],"latinEntries":[{"word":"communis","structure":"communis, communis (adj., third declension)","meaning":"common, shared","meaningCN":"共同的；公用的"},{"word":"communitas","structure":"communitas, communitatis (f., third declension)","meaning":"community, fellowship","meaningCN":"共同体；团契"},{"word":"munus","structure":"munus, muneris (n., third declension)","meaning":"duty, service, gift","meaningCN":"义务；职责；礼物"},{"word":"communio","structure":"communio, communionis (f., third declension)","meaning":"sharing, fellowship","meaningCN":"共享；共融"}],"derivatives":[{"word":"communist","pos":"n./adj.","zh":"共产主义者；共产主义的"},{"word":"communistic","pos":"adj.","zh":"共产主义式的"},{"word":"communise","pos":"v.","zh":"使公有化"},{"word":"anti-communism","pos":"n.","zh":"反共产主义"}]}},{"word":"communist","ipa_uk":"/ˈkɒmjunɪst/","ipa_us":"/ˈkɑːmjunɪst/","definition_zh":"共产主义的；共产党的；共产主义者；共产党成员","definition_en":"relating to communism or to a party that follows it, or a person who believes in or belongs to such a party","core_image":"一张党证从桌这边推过去，桌那边的人抬手接下，此后他的签名就与整排集体签名写在同一页","scene":"工会大厅里，新来的工人拿着入会表，在党派一栏停住笔。At the union hall the new worker paused over the box marked communist on the enrolment form.","sceneCN":"这里 communist 指「与共产主义政党相关的」（第 1 个义项：共产主义的、共产党的）；句意为这名新工人在入会表的党派栏上停笔犹豫。图中可辨识物件：入会表、笔、工会横幅、登记桌。","pos":[{"tag":"adj.","zh":"共产主义的；共产党执政的；共产主义政党的"},{"tag":"n.","zh":"共产主义者；共产党员"}],"collocations":[{"phrase":"the Communist Party","zh":"共产党"},{"phrase":"communist regime","zh":"共产主义政权"},{"phrase":"communist countries","zh":"共产主义国家"},{"phrase":"a lifelong communist","zh":"终身的共产主义者"},{"phrase":"communist propaganda","zh":"共产主义宣传"},{"phrase":"former communist","zh":"前共产党人"}],"forms":[{"label":"复数（名词）","form":"communists"},{"label":"比较级（形容词）","form":"more communist"},{"label":"最高级（形容词）","form":"most communist"},{"label":"名词（学说）","form":"communism"},{"label":"形容词（学说色彩）","form":"communistic"}],"derivatives":[{"word":"communism","pos":"n.","zh":"共产主义"},{"word":"communistic","pos":"adj.","zh":"共产主义式的"},{"word":"anti-communist","pos":"adj./n.","zh":"反共产主义的 / 反共分子"},{"word":"post-communist","pos":"adj.","zh":"后共产主义时期的"}],"senses":[{"no":"01","title":"Of communism as a doctrine","titleCN":"与共产主义学说或制度相关的","definition":"relating to communism as a doctrine, or to the system it describes","definitionCN":"与共产主义学说或其描述的制度相关","example":"At the union hall the new worker paused over the box marked communist on the enrolment form.","exampleCN":"在工会大厅，这名新工人在入会表的党派栏上停笔犹豫。","why":"The suffix -ist forms both the person and the adjective of a cause, so communist describes the doctrine's world before it names anyone in it.","whyCN":"指人后缀同时构成某事业的人与形容词，因此 communist 先描述这套学说的世界，然后才指其中的人。"},{"no":"02","title":"A member of a party","titleCN":"共产党成员；党员","definition":"an enrolled member of a party that governs or seeks to govern under that doctrine","definitionCN":"在该学说下执政或谋求执政的政党中的注册成员","example":"Every communist in the branch was asked to attend the district meeting.","exampleCN":"支部里每位党员都被要求参加区里的会议。","why":"A party needs a word for its members, and the person suffix supplies it, so membership rather than belief becomes the everyday reading.","whyCN":"政党需要给成员一个称呼，指人后缀正好提供，于是日常理解落在「党员」而非「信徒」上。"},{"no":"03","title":"A believer without a card","titleCN":"信奉共产主义但未必入党的人","definition":"a person who holds the belief without formal membership in any party","definitionCN":"持有这套信念、但并未在任何政党正式注册的人","example":"Her professor was a communist who never joined an organisation.","exampleCN":"她的教授是个共产主义者，却从未加入任何组织。","why":"Belief and membership can come apart, so the noun keeps a wider sense for the convinced reader who stays outside the structure.","whyCN":"信念与党籍可以分离，因此这个名词保留了更宽的一义，指认同这套学说却留在组织之外的人。"},{"no":"04","title":"Of a state run by such a party","titleCN":"由共产党执政的（用于国家或政权）","definition":"describing a state, government or legal order controlled by a party of that doctrine","definitionCN":"描述由奉行该学说的政党控制的国体、政府或法律秩序","example":"The communist government nationalised the ports within its first year.","exampleCN":"该共产主义政府在执政第一年就把港口收归国有。","why":"Once the party holds the state, the adjective attaches to institutions rather than to people, and it starts describing law and administration.","whyCN":"一旦政党掌握国家，这个形容词就附着到机构而非人身上，开始描述法律与行政。"},{"no":"05","title":"Of art and culture under such a state","titleCN":"该制度下官方文艺与宣传的","definition":"relating to the officially approved art, media and public imagery of such a state","definitionCN":"与该制度下官方认可的艺术、媒体与公共图像相关的","example":"The archive keeps communist posters from the nineteen-fifties alongside private letters.","exampleCN":"档案馆把五十年代的共产主义宣传画与私人信件放在一起保存。","why":"Culture policy produced a recognisable visual language, and English borrowed the political adjective to name it.","whyCN":"文化政策产生了一套可辨识的视觉语言，英语便借这个政治形容词来命名它。"},{"no":"06","title":"A revolutionary label, nineteen-seventeen onwards","titleCN":"二十世纪革命阵营中作为身份标签的用法","definition":"the name adopted by revolutionary movements and their supporters in the twentieth century","definitionCN":"二十世纪革命运动及其支持者采用的自我称呼","example":"His grandfather fought as a communist in the Spanish civil war.","exampleCN":"他的祖父曾作为共产主义者参加西班牙内战。","why":"Movements that took power under the name made it a badge of identity, so the noun could mean a fighter in a cause, not only a voter or a member.","whyCN":"以这个名字取得政权的运动使它成为身份徽章，名词于是也能指为事业而战的人，而不只是投票者或党员。"},{"no":"07","title":"A pooled arrangement, loosely","titleCN":"日常戏称「什么都共用」的","definition":"a joking or loose use for someone who shares everything instead of keeping a private share","definitionCN":"戏称或宽泛用法，指把一切都拿出来共用、不保留私份的人","example":"The flatmate who labels every shelf 'ours' calls himself a communist of the kitchen.","exampleCN":"那位把每个架子都标成「我们的」的室友，自称厨房里的共产主义者。","why":"The noun of a grand collective idea shrinks easily to a household scale, and the exaggeration is the point of the joke.","whyCN":"宏大的集体观念很容易缩到家庭尺度，而这种夸张正是玩笑的要点。"},{"no":"08","title":"An accusation in cold-war speech","titleCN":"冷战话语中作为指控标签的用法","definition":"the name used as an accusation against anyone suspected of left-wing sympathy","definitionCN":"冷战话语中用来指控任何被怀疑同情左翼的人的名称","example":"The committee ruined careers by calling a harmless clerk a communist.","exampleCN":"委员会把一个无害的职员称作共产主义者，就此毁掉了他的前程。","why":"A noun that names an enemy stops meaning a doctrine and starts meaning a suspicion, which is why the label had such force in that period.","whyCN":"当名词被用来指认敌人时，它就不再表示一种学说，而表示一种嫌疑；这个标签在那个年代之所以有力量，原因正在于此。"}],"etymology":{"intro":{"en":"Communist is communism plus the person suffix -ist. French communiste appeared around 1840, and English took the word in the same decade, first for supporters of the doctrine and then for party members.","cn":"communist 由 communism 加指人后缀构成。法语 communiste 约在一八四零年出现，英语在同一世代借入，先指学说的支持者，后指政党成员。"},"items":[{"era":"LATIN COMMUNIS","en":"Communis meant 'shared, common', generally thought to be com- 'together' plus a root tied to munus 'duty, service'; the picture is a duty or a store held by several people at once.","cn":"communis 意为「共同的、公用的」，一般认为由表示「共同」的前缀加一个与 munus「义务、职责」相关的词根构成；画面是数人共担一责或共守一库。"},{"era":"SUFFIX -IST","en":"The agent suffix -ist, from Greek through French, marks the person who follows or practices something, and it also builds the matching adjective in many pairs.","cn":"指人后缀经法语来自希腊语，标记追随或从事某事的人；在许多成对词里，它同时构成相应的形容词。"},{"era":"FRENCH COMMUNISTE","en":"French communiste was coined around 1840 alongside communisme, naming a supporter of common ownership before any party existed to join.","cn":"法语 communiste 与 communisme 约在同一时期造出，指共同所有制的支持者，那时还没有任何政党可供加入。"},{"era":"ENGLISH 1840S","en":"English adopted communist in the eighteen-forties; early uses describe writers and circles rather than card-carrying members.","cn":"英语在一八四零年代吸收 communist；早期用例描述的是作者与圈子，而不是持证党员。"},{"era":"PARTY SENSE","en":"After parties carrying the name took power in the twentieth century, the noun shifted toward enrolled membership and the adjective toward state institutions.","cn":"二十世纪以该名号执政的政党取得政权之后，名词偏向注册成员，形容词偏向国家机构。"},{"era":"APPROXIMATE DATES","en":"The first English citation is not precisely dated: the eighteen-forties figure is approximate, and earlier appearances in translation are unverified.","cn":"英语最早书证没有精确年代：一八四零年代只是约数；更早出现在译本中的说法尚未得到证实。"}]},"similar":{"note":{"en":"The first group shares the Latin root and is easy to confuse at a glance; the second group names related political identities.","cn":"第一组共享拉丁词根，一眼看去容易混淆；第二组是相关的政治身份。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"communism","ipa":"/ˈkɒmjunɪzəm/","tag":"same family","definition":"The doctrine or system; it never names a person and never serves as an adjective.","definitionCN":"学说或制度；它从不指人，也不作形容词。"},{"word":"communal","ipa":"/kəˈmjuːnl/","tag":"same root, different sense","definition":"Shared within a small group such as a household; the word carries no party and no state.","definitionCN":"在小群体如家庭内共用；这个词不含政党，也不含国家。"},{"word":"commune","ipa":"/ˈkɒmjuːn/","tag":"same root, different noun","definition":"A community sharing work and property, or a unit of local government; it is a body or a place.","definitionCN":"共享劳动与财产的共同体，或地方行政单位；它是机构或场所。"},{"word":"community","ipa":"/kəˈmjuːnəti/","tag":"same root","definition":"Any group living or acting together, from a village to an online forum.","definitionCN":"任何共同生活或行动的群体，从村庄到网络论坛。"},{"word":"communique","ipa":"/ˌkɒmjuːnɪˈkeɪ/","tag":"look-alike only","definition":"An official statement issued after talks, from French communiqué; despite the shared opening it has nothing to do with ownership.","definitionCN":"会谈后发布的官方公报，出自法语；尽管开头相同，它与所有权无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"socialist","ipa":"/ˈsəʊʃəlɪst/","tag":"earlier stage","definition":"The neighbouring label for the transitional stage; a socialist may or may not call himself a communist.","definitionCN":"指过渡阶段的相邻标签；一个社会主义者未必自称共产主义者。"},{"word":"Marxist","ipa":"/ˈmɑːksɪst/","tag":"theoretical label","definition":"A follower of the analytical framework, which is compatible with several political positions and is not identical with party membership.","definitionCN":"该分析框架的追随者，可与多种政治立场相容，并不等同于党籍。"},{"word":"leftist","ipa":"/ˈleftɪst/","tag":"broader label","definition":"A wide term for anyone on the political left, of which communist is one specific and more militant case.","definitionCN":"对政治左翼的宽泛称呼，共产主义者是其中更具体、更激烈的一种。"},{"word":"comrade","ipa":"/ˈkɒmreɪd/","tag":"address term","definition":"The form of address used inside such parties; it names a fellow member in speech, not a doctrine.","definitionCN":"此类政党内部使用的称呼；它在言语中指同志，而非学说。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real root, the real family and real fixed phrases.","cn":"正常联想使用真实的词根、真实的同族词与真实固定搭配。"},"normal":[{"en":"Communis is Latin for shared, and -ist marks the person, so a communist is literally a person of the shared thing.","cn":"communis 是拉丁语「共同的」，指人后缀标记人，communist 字面上就是「共同之事的人」。"},{"en":"The family runs common, community, communism, communist, communistic and communise.","cn":"同族词有 common、community、communism、communist、communistic 与 communise。"},{"en":"Fixed phrases mark the political sense: the Communist Party, communist regime, former communist.","cn":"固定搭配标出政治义：共产党、共产主义政权、前共产党人。"},{"en":"The capital letter in Communist Party is a naming convention, not a different word.","cn":"「共产党」里的大写是命名惯例，并不表示另一个词。"},{"en":"Cold-war usage turned the noun into an accusation, which is why it appears in compounds such as anti-communist.","cn":"冷战用法把这个名词变成指控，因此它出现在「反共」这类复合词里。"}],"abstract":[{"en":"Picture a card slid across a table and a hand receiving it without looking up.","cn":"想象一张证件从桌子这头推过去，那头的手没抬头就接下了。"},{"en":"Picture a row of signatures on one page, each the same length, none larger.","cn":"想象一页上并排的签名，每个都一样长，没有哪个更大。"},{"en":"Picture a stamp pressed on a poster until the ink covers the original drawing.","cn":"想象一枚印章反复盖在海报上，直到油墨盖住了原来的画。"}]},"examples":[{"en":"The communist bloc dissolved within two years.","cn":"共产主义阵营在两年之内解体。"},{"en":"He remained a communist after the party lost its majority.","cn":"政党失去多数席位后，他仍是共产主义者。"},{"en":"The exhibition gathered communist murals from three decades.","cn":"这次展览汇集了三十年间共产主义题材的壁画。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「commun（共同）+ ist（人）」——信奉财产共同的人 → 共产主义者","word":"communist"},"root":"拉丁 communis「共同的、公用的」→ 法语 communisme、communiste → 英语 communism、communist；末尾是表示人的后缀。","sensesIntro":{"en":"Eight senses follow one card: it is issued to a believer, kept by a member, shown by a government, printed on a poster, worn as a badge in a war, borrowed for a kitchen joke, and finally used as a slur.","cn":"八个义项围绕一张证件：它发给信徒，由党员保管，由政府出示，印在海报上，在战争中当作徽章佩戴，被借去开厨房的玩笑，最后被用作辱骂。"},"semanticMap":{"core":{"en":"CORE IMAGE: one membership card passed across a table, its holder now one signature in a long row.","cn":"核心意象：一张证件从桌上传过去，持证者从此只是长排签名中的一个。"},"chain":["THE CARD","THE BELIEF BEHIND IT","THE PARTY","THE STATE","THE PICTURE","THE WEAPON"],"branches":[{"senses":"01 · 03","en":"DOCTRINE AND BELIEF: the adjective names the world, the noun names someone convinced by it, whether or not a card exists.","cn":"学说与信念：形容词命名那个世界，名词命名被它说服的人，无论有没有证件。"},{"senses":"02 · 06","en":"THE CARD AND THE BADGE: enrolled membership and wartime identity are the same word at two temperatures.","cn":"证件与徽章：注册党籍与战地身份，是同一个词在两种温度下。"},{"senses":"04 · 05","en":"INSTITUTIONS AND IMAGES: a government and its approved posters are the doctrine in stone and ink.","cn":"机构与图像：一个政府与它批准的海报，是这套学说在石头与油墨中的形态。"},{"senses":"07","en":"THE SMALL JOKE: one shelf marked 'ours' borrows the grand noun.","cn":"小小的玩笑：一排标成「我们的」的架子，借用了这个宏大名词。"},{"senses":"08","en":"THE ACCUSATION: the same word, aimed at a person, becomes a charge.","cn":"指控：同一个词对准某个人时，就变成了罪名。"}]},"affixes":{"intro":{"en":"Communist is a Latin root of sharing plus a person suffix, and both halves build many English words.","cn":"communist 是一个表示「共用」的拉丁词根加一个指人后缀，两半都构成许多英语词。"},"latinIntro":{"en":"Latin communis supplies common, community and communal; the suffix -ist supplies pairs such as artist, scientist and socialist.","cn":"拉丁 communis 提供 common、community 与 communal；指人后缀提供 artist、scientist、socialist 这类成对词。"},"items":[{"word":"commun-","structure":"communis (Latin adjective, 'shared')","meaning":"shared by several","meaningCN":"数人共用","example":"The root supplies the common store.","exampleCN":"词根提供「共用储备」的画面。"},{"word":"-is","structure":"Latin adjective ending","meaning":"of the kind","meaningCN":"属于该类","example":"It completes the adjective of sharing.","exampleCN":"它补全表示共用的形容词。"},{"word":"common","structure":"communis through Old French","meaning":"shared; ordinary","meaningCN":"共用的；普通的","example":"The oldest English relative.","exampleCN":"英语里最古老的亲属词。"},{"word":"community","structure":"common plus -ity","meaning":"group holding things together","meaningCN":"共同体","example":"It turns sharing into a body of people.","exampleCN":"它把「共用」变成一群人。"},{"word":"-ism","structure":"Greek -ismos through French","meaning":"doctrine","meaningCN":"学说","example":"It names the system of belief.","exampleCN":"它命名信念体系。"},{"word":"communism","structure":"commun- plus -ism","meaning":"doctrine of common ownership","meaningCN":"共产主义","example":"The doctrine behind the person.","exampleCN":"人背后的学说。"},{"word":"-ist","structure":"Greek -istēs through French","meaning":"person who follows","meaningCN":"追随者","example":"It names the holder of the belief.","exampleCN":"它命名信念的持有者。"},{"word":"communist","structure":"communism plus -ist","meaning":"adherent; of the doctrine","meaningCN":"共产主义者；共产主义的","example":"One form, two jobs.","exampleCN":"一个词形，两种职能。"},{"word":"-istic","structure":"-ist plus -ic","meaning":"having the character of","meaningCN":"具有……性质的","example":"It builds a descriptive adjective.","exampleCN":"它构成描述性形容词。"},{"word":"anti-","structure":"Greek anti- 'against'","meaning":"opposed to","meaningCN":"反对","example":"Used in anti-communist for the opposing camp.","exampleCN":"在「反共」中指对立阵营。"}],"latinEntries":[{"word":"communis","structure":"communis, communis (adj., third declension)","meaning":"common, shared","meaningCN":"共同的"},{"word":"communitas","structure":"communitas, communitatis (f., third declension)","meaning":"community","meaningCN":"共同体"},{"word":"munus","structure":"munus, muneris (n., third declension)","meaning":"duty, service","meaningCN":"义务；职责"},{"word":"communio","structure":"communio, communionis (f., third declension)","meaning":"fellowship, sharing","meaningCN":"共享；共融"}],"derivatives":[{"word":"communism","pos":"n.","zh":"共产主义"},{"word":"communistic","pos":"adj.","zh":"共产主义式的"},{"word":"anti-communist","pos":"adj./n.","zh":"反共产主义的；反共分子"},{"word":"post-communist","pos":"adj.","zh":"后共产主义时期的"}]}},{"word":"federalism","ipa_uk":"/ˈfedərəlɪzəm/","ipa_us":"/ˈfedərəlɪzəm/","definition_zh":"联邦制；联邦主义；中央与地方分权的原则；（组织内部的）分权体制","definition_en":"a system of government in which power is divided between a central authority and constituent units, or the principle or movement that advocates such a division","core_image":"一张地图被两种颜色的铅笔画过，同一条河的上游与下游各有自己的税则，中央只在交界处盖章","scene":"十几个代表围着一张大地图，用两种颜色标出中央与各州各自可以征税的范围。On the map the delegates drew two colours to show what federalism left to each level of government.","sceneCN":"这里 federalism 指中央与地方分权的政府体制（第 1 个义项：联邦制的权力划分）；句意为代表们用两种颜色在大地图上标出联邦制留给中央与各州各自的权限。图中可辨识物件：大地图、双色铅笔、州界线、盖章处。","pos":[{"tag":"n.","zh":"联邦制；联邦主义；分权原则；（组织内的）分权安排"}],"collocations":[{"phrase":"fiscal federalism","zh":"财政联邦主义"},{"phrase":"dual federalism","zh":"二元联邦主义"},{"phrase":"cooperative federalism","zh":"合作联邦主义"},{"phrase":"the federalism debate","zh":"关于联邦制的争论"},{"phrase":"European federalism","zh":"欧洲联邦主义"},{"phrase":"a strong tradition of federalism","zh":"深厚的联邦制传统"}],"forms":[{"label":"单数（不可数）","form":"federalism"},{"label":"复数（指多种联邦制安排）","form":"federalisms"},{"label":"形容词","form":"federal"},{"label":"名词（主张者）","form":"federalist"},{"label":"动词","form":"federalise"},{"label":"名词（联合体）","form":"federation"}],"derivatives":[{"word":"federal","pos":"adj.","zh":"联邦的；联邦制的"},{"word":"federalist","pos":"n./adj.","zh":"联邦主义者 / 联邦主义的"},{"word":"federalise","pos":"v.","zh":"使结成联邦；使归联邦管辖"},{"word":"federalisation","pos":"n.","zh":"联邦化"},{"word":"confederalism","pos":"n.","zh":"邦联主义（各单位保留更大主权）"}],"senses":[{"no":"01","title":"Power split between centre and units","titleCN":"中央与成员单位分权的政府体制","definition":"a system in which a central government and regional governments each hold powers that the other cannot simply take away","definitionCN":"一种中央政府对地区政府各自握有对方不能随意剥夺的权力的制度","example":"On the map the delegates drew two colours to show what federalism left to each level of government.","exampleCN":"代表们用两种颜色在大地图上标出联邦制留给中央与各州各自的权限。","why":"The word is built on foedus 'treaty': units that once stood apart bind themselves by an agreement that each side keeps, so power is shared by contract rather than granted from above.","whyCN":"这个词建立在 foedus「盟约」之上：原本分立的单位以一份各方都保留的约定结合，因此权力是按契约共享，而非由上而下授予。"},{"no":"02","title":"The principle, not the machine","titleCN":"作为政治原则的联邦主义","definition":"the doctrine that governing power should be divided among levels rather than concentrated in one","definitionCN":"主张治理权力应在多个层级间划分、而非集中于一处的主张","example":"Her essay defended federalism as a check on any single capital.","exampleCN":"她的文章把联邦主义辩护为对任何单一权力中心的制约。","why":"A working arrangement can also be argued for as a value, and in that shift the noun stops describing an institution and starts describing a belief.","whyCN":"一套运作安排也可以被当作价值来论证；在这一转手里，名词不再描述制度，而开始描述信念。"},{"no":"03","title":"A movement seeking union","titleCN":"谋求结成联邦的政治运动","definition":"a movement that works to bring separate states or nations into a single federal union","definitionCN":"致力于把分立的国家或民族结合为一个联邦联盟的运动","example":"Post-war federalism pushed for a directly elected European assembly.","exampleCN":"战后的联邦主义推动了直选欧洲议会的出现。","why":"If a treaty can bind units, then someone will want to extend the treaty to new units, and the noun becomes the name of that campaign.","whyCN":"既然盟约能约束各单位，就会有人想把盟约扩展到新的单位，名词于是成为那场运动的名字。"},{"no":"04","title":"The early American party line","titleCN":"美国早期联邦党人主张的用法（专名义）","definition":"the programme of the late eighteenth-century American party that wanted a stronger central government","definitionCN":"十八世纪末美国那个主张强化中央政府的政党所持的纲领","example":"Textbooks use federalism for the programme that funded a national bank and a standing fleet.","exampleCN":"教科书用联邦主义指那套为国家银行与常备舰队提供资金的纲领。","why":"A party took the adjective as its name, and its programme inherited the noun, so one capitalised use points to a specific historical camp.","whyCN":"一个政党把这个形容词当作党名，其纲领便继承了名词，因此有一个大写用法指向特定的历史阵营。"},{"no":"05","title":"Power sharing inside an organisation","titleCN":"组织内部的分权安排","definition":"the division of authority between a central body and regional branches of a union, party or church","definitionCN":"工会、政党或教会中中央机构与地区分支之间的权限划分","example":"The union's federalism gave each branch the right to set its own strike ballot.","exampleCN":"这个工会的联邦制让每个分支都有权自行决定是否投票罢工。","why":"The pattern of divided authority is easy to copy into any large body, so the noun travels from states to offices without changing shape.","whyCN":"分权的模式很容易被复制到任何大型组织，于是这个名词从国家移到办公室而形状不变。"},{"no":"06","title":"Fiscal federalism","titleCN":"财政职能在各级政府间的划分","definition":"the arrangement by which taxing and spending duties are allocated among levels of government","definitionCN":"税收与支出职责在各级政府之间分配的制度安排","example":"Economists study fiscal federalism to see which level should pay for schools.","exampleCN":"经济学家研究财政联邦主义，以判断应由哪一级政府为学校出资。","why":"Money follows the same line as law: if each level keeps its own revenue, it can act without asking the centre for every sum.","whyCN":"钱跟着同一条线走：每一级保留自己的收入，就能不经中央逐笔拨款而行动。"},{"no":"07","title":"A doctrine of limited central power","titleCN":"宪法解释中限制中央权力的主张","definition":"a reading of a constitution that reserves broad powers to the states and reads central powers narrowly","definitionCN":"一种把广泛权力保留给各州、对中央权力作狭窄解释的宪法读法","example":"The court's federalism argument blocked the federal agency from regulating local water.","exampleCN":"法院依联邦主义的主张，禁止联邦机构监管地方水域。","why":"If the split is written into a constitution, judges must decide where the line falls, and the noun becomes an argument about how to read that line.","whyCN":"既然分权写进了宪法，法官就必须判定界线在哪里，名词于是变成一场关于如何读这条线的论证。"},{"no":"08","title":"A design choice in comparative politics","titleCN":"比较政治中的一种制度设计选择","definition":"one of the institutional models a divided or multi-ethnic state may adopt, alongside unitary and confederal arrangements","definitionCN":"分裂社会或多民族国家可选的一种制度模型，与单一制和邦联制并列","example":"Comparing federalism with unitary rule shows how many veto points each design creates.","exampleCN":"把联邦制与单一制相比，可以看出每种设计产生多少个否决点。","why":"Once the arrangement is treated as a choice rather than a fact, the noun can be listed beside rival designs and weighed by their effects.","whyCN":"一旦这套安排被当作可选而非既定，名词就能与竞争设计并列，并按效果被衡量。"}],"etymology":{"intro":{"en":"Federalism is federal plus -ism; federal goes back through French to Latin foedus 'treaty, league'. The political noun was coined in the late eighteenth century, when American writers needed a name for divided sovereignty.","cn":"federalism 由 federal 加表示学说的后缀构成；federal 经法语上溯到拉丁 foedus「盟约、同盟」。这个政治名词在十八世纪后期被造出，当时美国作者需要一个名字来称呼被分割的主权。"},"items":[{"era":"LATIN FOEDUS","en":"Foedus, genitive foederis, meant a treaty, league or covenant. The word names the bond itself, which is why federal arrangements are described as contractual rather than hierarchical.","cn":"foedus（属格 foederis）意为盟约、同盟、约定。这个词命名的是纽带本身，因此联邦安排被描述为契约式而非层级式。"},{"era":"ROOT OF TRUST","en":"It is generally thought that foedus shares a root with fides 'faith, trust', from a reconstructed element meaning 'to trust'; the shared root is a reasoned reconstruction, not a recorded form.","cn":"一般认为 foedus 与 fides「信义、信任」共享一个词根，该词根出自一个表示「信任」的重构成分；这一共享词根属有理据的重构，并非有记录的词形。"},{"era":"FRENCH FÉDÉRAL","en":"French fédéral and the earlier Latin-derived foederalis carried the sense 'of a league' into early modern usage, still close to treaty and alliance.","cn":"法语 fédéral 以及更早由拉丁派生的 foederalis 把「同盟的」这一义带入近代早期用法，仍贴近盟约与结盟。"},{"era":"AMERICAN COINAGE","en":"Federalism appears in English political writing in the seventeen-eighties and nineties, naming the division of sovereignty between a national government and the states.","cn":"federalism 在十八世纪八九十年代的英语政治写作中出现，指国家政府与各州之间对主权的划分。"},{"era":"PARTY LABEL","en":"American writers also used it, often capitalised, for the programme of the party that favoured a stronger centre, which is how one proper-noun sense arose.","cn":"美国作者也用它（常大写）指那个偏向强化中央的政党的纲领，专名的一义即由此而来。"},{"era":"APPROXIMATE DATES","en":"The earliest citation is not precisely dated: the seventeen-eighties figure is approximate, and earlier isolated uses in translation remain unverified.","cn":"最早书证没有精确年代：十八世纪八十年代只是约数；更早散见于译本中的用例尚未得到证实。"}]},"similar":{"note":{"en":"The first group is built on the same treaty word and is often mixed up; the second group names other ways of distributing authority.","cn":"第一组同出那个表示盟约的词，常被混淆；第二组是其他分配权力的方式。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"federal","ipa":"/ˈfedərəl/","tag":"same family","definition":"The adjective describing anything belonging to a union of states, or to the central level of one.","definitionCN":"形容词，描述属于州联合体的事物，或属于其中央层级的事物。"},{"word":"federation","ipa":"/ˌfedəˈreɪʃn/","tag":"same root, different noun","definition":"The union itself as an entity, such as a national federation of clubs; federalism is the principle behind it.","definitionCN":"指联合体这个实体，如全国性俱乐部联合会；联邦主义是其背后的原则。"},{"word":"federalist","ipa":"/ˈfedərəlɪst/","tag":"same family","definition":"A supporter of the arrangement, or the adjective describing such a position.","definitionCN":"指这种安排的支持者，或描述该立场的形容词。"},{"word":"confederation","ipa":"/kənˌfedəˈreɪʃn/","tag":"near root, stronger units","definition":"A looser union in which the units keep most sovereignty and the centre depends on their consent.","definitionCN":"更松散的联合，各单位保留大部分主权，中央依赖它们的同意。"},{"word":"foedus","ipa":"/ˈfɔɪdəs/","tag":"Latin source","definition":"The Latin noun for treaty or league; it is the source of the whole English group.","definitionCN":"拉丁语中表示盟约或同盟的名词，是整个英语词组的来源。"}]},{"heading":"NEAR MEANING","entries":[{"word":"devolution","ipa":"/ˌdiːvəˈluːʃn/","tag":"transfer, not division","definition":"The handing of specified powers from a central parliament to regional bodies that remain subordinate.","definitionCN":"中央议会把特定权力交给仍处于从属地位的地区机构。"},{"word":"decentralisation","ipa":"/ˌdiːsentrəlaɪˈzeɪʃn/","tag":"administrative spread","definition":"Moving offices and decisions away from a capital without giving regions constitutional protection.","definitionCN":"把机构与决策从首都外移，但不给地区宪法层面的保障。"},{"word":"unitary state","ipa":"/ˈjuːnɪtəri steɪt/","tag":"the contrasting model","definition":"A state in which one parliament holds final authority and regions act only as its agents.","definitionCN":"由一个议会掌握最终权威、地区仅作为其代理人的国家。"},{"word":"autonomy","ipa":"/ɔːˈtɒnəmi/","tag":"self-rule","definition":"The right of a group to govern its own affairs within limits set elsewhere.","definitionCN":"在外部设定的限度内自行管理事务的权利。"},{"word":"centralism","ipa":"/ˈsentrəlɪzəm/","tag":"the opposite principle","definition":"The doctrine that decisions should be made in one place and applied uniformly.","definitionCN":"主张决策应在一处作出并统一施行的主张。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin treaty word, the real family and real fixed phrases.","cn":"正常联想使用真实的拉丁「盟约」词、真实的同族词与真实固定搭配。"},"normal":[{"en":"Foedus is Latin for treaty, so federalism is government by a kept agreement.","cn":"foedus 是拉丁语「盟约」，所以联邦制就是靠一份被各方共同遵守的约定来治理。"},{"en":"The family runs federal, federalism, federalist, federalise, federalisation and federation.","cn":"同族词有 federal、federalism、federalist、federalise、federalisation 与 federation。"},{"en":"Fixed phrases mark the technical senses: fiscal federalism, dual federalism, cooperative federalism.","cn":"固定搭配标出技术义：财政联邦主义、二元联邦主义、合作联邦主义。"},{"en":"The same root gives fides, faith or trust, which is why a treaty and a pledge sound alike in Latin.","cn":"同一词根还给出 fides「信义」，所以在拉丁语里盟约与誓言听起来相近。"},{"en":"One capital letter changes the reference: Federalism with a capital names a historical party line.","cn":"一个大写字母就换了所指：大写的联邦主义指历史上的一个党派纲领。"}],"abstract":[{"en":"Picture a map inked in two colours, neither able to erase the other.","cn":"想象一张被两种颜色画过的地图，哪一种都擦不掉另一种。"},{"en":"Picture a rope bridge whose planks are owned by the villages at either end, not by the river.","cn":"想象一座绳桥，桥板归两端村子所有，而不归河流所有。"},{"en":"Picture two keys to one door, cut differently, so neither side can open it alone.","cn":"想象一扇门有两把齿形不同的钥匙，任何一方都无法独自打开。"}]},"examples":[{"en":"The constitution's federalism is visible in its list of state powers.","cn":"宪法中的联邦制体现在它所列的州权清单上。"},{"en":"Fiscal federalism explains why schools depend on local taxes.","cn":"财政联邦主义解释了学校为何依赖地方税收。"},{"en":"Supporters argued that federalism protects minorities from distant majorities.","cn":"支持者认为联邦制能保护少数群体不受远方多数的支配。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「federal（联邦的）+ ism（主义）」——主张中央与地方分权的制度 → 联邦制","word":"federalism"},"root":"拉丁 foedus（属格 foederis）「盟约、同盟」，一般认为与 fides「信义」共享一个表示「信任」的重构词根 → 法语 fédéral → 英语 federal → federalism。","sensesIntro":{"en":"Eight senses follow one line drawn on a map: the line divides power, becomes a principle, then a campaign, then a party programme, then a rule inside a union, a budget rule, a judicial reading, and finally a model on a shelf of designs.","cn":"八个义项围绕地图上画的一条线：这条线分割权力，随后成为原则、运动、党派纲领、工会内部的章程、预算规则、司法读法，最后成为设计清单上的一种模型。"},"semanticMap":{"core":{"en":"CORE IMAGE: one line on a map, drawn by two hands, that neither side may rub out.","cn":"核心意象：地图上一条由两只手共同画的线，任何一方都擦不掉。"},"chain":["THE LINE ON THE MAP","POWER DIVIDED","A PRINCIPLE","A CAMPAIGN","INSIDE ORGANISATIONS","MONEY AND LAW"],"branches":[{"senses":"01 · 08","en":"STRUCTURE AND MODEL: a working arrangement and a design choice are the same line seen in a country or on a shelf.","cn":"制度与模型：运作中的安排与清单上的设计，是同一条线出现在一个国家或一个架子上。"},{"senses":"02","en":"THE ARGUMENT: once the line is defended as a value, the noun stops describing and starts advocating.","cn":"论证：一旦这条线被当作价值来辩护，名词就不再描述，而开始主张。"},{"senses":"03 · 04","en":"TWO CAMPAIGNS: a movement extending the treaty outward, and a party defending a stronger centre inward.","cn":"两场运动：一场向外扩展盟约，一场向内维护更强的中央。"},{"senses":"05","en":"THE OFFICE COPY: states are replaced by branches, and the same line is drawn inside a union.","cn":"办公室的复本：国家换成分支，同一条线被画在工会内部。"},{"senses":"06 · 07","en":"MONEY AND LAW: budgets and judicial readings are the line turned into arithmetic and into interpretation.","cn":"钱与法：预算与司法读法，是这条线变成算术与解释的两副面孔。"}]},"affixes":{"intro":{"en":"Federalism rests on a Latin treaty noun that also builds federal, federation and confederation, plus a doctrine suffix.","cn":"联邦主义依赖一个拉丁语「盟约」名词，它同时构成 federal、federation 与 confederation，末尾再加表示学说的后缀。"},"latinIntro":{"en":"Latin foedus, genitive foederis, gives foederalis and through French federal; the same root is behind fides 'faith'.","cn":"拉丁 foedus（属格 foederis）给出 foederalis，再经法语成为 federal；同一词根还在 fides「信义」背后。"},"items":[{"word":"foed-","structure":"foedus (Latin noun, 'treaty, league')","meaning":"treaty; league","meaningCN":"盟约；同盟","example":"The root names the bond, not the ruler.","exampleCN":"这个词根命名纽带，而非统治者。"},{"word":"-al","structure":"Latin adjective ending -alis","meaning":"relating to","meaningCN":"与……相关的","example":"It turns the treaty noun into an adjective.","exampleCN":"它把盟约名词变成形容词。"},{"word":"federal","structure":"foed- plus -al through French","meaning":"of a league of states","meaningCN":"联邦的","example":"The adjective describes the union and its centre.","exampleCN":"形容词描述联合体及其中央。"},{"word":"-ism","structure":"Greek -ismos through French","meaning":"doctrine; system","meaningCN":"学说；制度","example":"It names the principle as a whole.","exampleCN":"它把原则作为整体来命名。"},{"word":"federalism","structure":"federal plus -ism","meaning":"the divided-power system","meaningCN":"联邦制","example":"The noun can mean the machine or the belief.","exampleCN":"名词既可指机器，也可指信念。"},{"word":"-ist","structure":"Greek -istēs through French","meaning":"person who supports","meaningCN":"支持者","example":"It names the advocate.","exampleCN":"它命名主张者。"},{"word":"federalist","structure":"federal plus -ist","meaning":"supporter; of that line","meaningCN":"联邦主义者；联邦主义的","example":"One form serves person and adjective.","exampleCN":"一个词形兼指人与形容词。"},{"word":"-ise","structure":"French -iser / Latin -izare","meaning":"to make","meaningCN":"使成为","example":"It forms the verb of conversion.","exampleCN":"它构成表示转变的动词。"},{"word":"federalise","structure":"federal plus -ise","meaning":"to bring under a federation","meaningCN":"使结成联邦","example":"The verb names the act of drawing the line.","exampleCN":"动词命名画这条线的动作。"},{"word":"con-","structure":"Latin com- 'together'","meaning":"together","meaningCN":"共同","example":"It marks the looser union in confederation.","exampleCN":"它在「邦联」中标出更松的结合。"}],"latinEntries":[{"word":"foedus","structure":"foedus, foederis (n., third declension)","meaning":"treaty, league, covenant","meaningCN":"盟约；同盟；约定"},{"word":"foederalis","structure":"foederalis, foederale (adj., third declension)","meaning":"of a treaty or league","meaningCN":"盟约的；同盟的"},{"word":"fides","structure":"fides, fidei (f., fifth declension)","meaning":"faith, trust, promise","meaningCN":"信义；信任；诺言"},{"word":"foederare","structure":"foederare, foederavi, foederatum (verb, first conjugation)","meaning":"to ally, to league together","meaningCN":"结盟；联合"}],"derivatives":[{"word":"federal","pos":"adj.","zh":"联邦的；联邦制的"},{"word":"federalist","pos":"n./adj.","zh":"联邦主义者；联邦主义的"},{"word":"federalise","pos":"v.","zh":"使结成联邦"},{"word":"federalisation","pos":"n.","zh":"联邦化"},{"word":"confederalism","pos":"n.","zh":"邦联主义"}]}},{"word":"legally","ipa_uk":"/ˈliːɡəli/","ipa_us":"/ˈliːɡəli/","definition_zh":"合法地；依照法律地；从法律角度；（因符合法定条件而）在法律上","definition_en":"in a way that is allowed or required by law, or as judged from the point of view of the law","core_image":"市政厅窗口的印章落在纸角上，纸还是那张纸，盖章前后它能做的事却完全不同","scene":"小店店主先在市政厅窗口盖章，才敢把新招牌挂到门楣上。Only after the clerk stamped the form could the shop legally hang its sign above the doorway.","sceneCN":"这里 legally 指「依照法律、不违法的」（第 1 个义项：以合法方式）；句意为只有在市政厅窗口盖章之后，店主才能合法地把招牌挂上门楣。图中可辨识物件：印章、表单、窗口柜台、木招牌。","pos":[{"tag":"adv.","zh":"合法地；依法地；从法律角度；在法律上"}],"collocations":[{"phrase":"legally binding","zh":"具有法律约束力的"},{"phrase":"legally responsible","zh":"负有法律责任的"},{"phrase":"legally required","zh":"法律要求的"},{"phrase":"legally entitled","zh":"依法有权享有的"},{"phrase":"legally obtained evidence","zh":"合法取得的证据"},{"phrase":"legally married","zh":"法律上已婚的"}],"forms":[{"label":"形容词","form":"legal"},{"label":"名词（合法性）","form":"legality"},{"label":"比较级","form":"more legally"},{"label":"最高级","form":"most legally"},{"label":"动词","form":"legalise"}],"derivatives":[{"word":"legal","pos":"adj.","zh":"法律的；合法的"},{"word":"legality","pos":"n.","zh":"合法性；法律上的有效性"},{"word":"legalise","pos":"v.","zh":"使合法化"},{"word":"legalisation","pos":"n.","zh":"合法化"},{"word":"illegal","pos":"adj.","zh":"非法的"}],"senses":[{"no":"01","title":"In a way the law allows","titleCN":"以法律所允许的方式","definition":"in a manner that is permitted by the law and not forbidden by it","definitionCN":"以法律允许、未被法律禁止的方式","example":"Only after the clerk stamped the form could the shop legally hang its sign above the doorway.","exampleCN":"只有在市政厅窗口盖章之后，店主才能合法地把招牌挂上门楣。","why":"Legal is the adjective of lex 'law', and the adverb -ly says the action matches that standard: what is done legally falls inside the permitted line.","whyCN":"legal 是 lex「法律」的形容词，副词词尾表示动作符合这一标准：合法地做的事落在许可线之内。"},{"no":"02","title":"As the law requires","titleCN":"按法律规定，依法","definition":"in the way that a statute or regulation demands, whether or not one agrees with it","definitionCN":"按法令或规章所要求的方式，无论个人是否赞同","example":"The landlord must legally give ninety days' notice before raising the rent.","exampleCN":"房东涨租之前必须依法提前九十天通知。","why":"The same adverb covers permission and obligation, because a statute both permits and compels; the direction of the duty is read from context.","whyCN":"同一个副词既覆盖许可也覆盖义务，因为法令既授权也强制；义务的方向靠上下文判断。"},{"no":"03","title":"Judged from the law's point of view","titleCN":"从法律角度判断","definition":"when assessed by the rules of law rather than by morality, custom or common sense","definitionCN":"以法律规则而非道德、习俗或常识来评估","example":"Legally the contract is sound, though everyone agrees it was unfair.","exampleCN":"从法律上看这份合同没有问题，尽管大家都认为它并不公平。","why":"Adverbs of viewpoint mark the frame being used, so legally at the head of a clause means 'in the legal frame, whatever other frames say'.","whyCN":"表示视角的副词标出所用的框架，因此位于句首的 legally 意为「在法律框架内，不论其他框架怎么说」。"},{"no":"04","title":"With binding legal effect","titleCN":"具有法律效力地","definition":"so as to create rights and duties that a court would enforce","definitionCN":"以至于产生法院会执行的的权利与义务","example":"Once notarised, the promise was legally binding on both families.","exampleCN":"一经公证，这项承诺对两家都具有法律约束力。","why":"A document becomes real in law when the required form is completed, and the adverb names that completed state rather than the intention behind it.","whyCN":"文件在形式上完成法定手续后，才在法律上生效；副词命名的是完成状态，而非背后的意图。"},{"no":"05","title":"By lawful procedure","titleCN":"通过合法程序或手段","definition":"through procedures and means that the law permits, especially in obtaining evidence or taking action","definitionCN":"通过法律允许的程序与手段，尤指取得证据或采取行动","example":"The evidence was legally obtained, so the court admitted it.","exampleCN":"证据是合法取得的，因此法院予以采纳。","why":"Procedure is where legality is tested in practice: a right result reached by a forbidden route is not legally reached.","whyCN":"程序是合法性的实际检验处：用被禁止的途径得到的正确结果，在法律上不算取得。"},{"no":"06","title":"Meeting a statutory definition","titleCN":"符合法定定义地（按法定标准）","definition":"according to a threshold or definition written into a statute, as with age or disability","definitionCN":"按照写进法令的界限或定义，如年龄或残疾认定","example":"He is legally blind, though he still reads with a magnifier.","exampleCN":"他在法律上属于失明，尽管他仍用放大镜读书。","why":"Statutes define words for their own purposes, so legally can mean 'by the official definition' even when ordinary usage would say otherwise.","whyCN":"法令会为自己的目的给词下定义，因此 legally 可以表示「按官方定义」，即使日常说法并非如此。"},{"no":"07","title":"Recognised in legal status","titleCN":"在法律上获得承认的（身份、关系）","definition":"in the status that the law recognises, as with a marriage or a registered charity","definitionCN":"以法律所承认的身份，如婚姻或注册慈善机构","example":"They were legally married in a registry office, with two witnesses.","exampleCN":"他们在登记处依法结婚，只有两位见证人。","why":"Status is conferred by registration, and the adverb separates the legal fact from any ceremony or private understanding.","whyCN":"身份由登记赋予，副词把法律事实与任何仪式或私下理解区分开来。"},{"no":"08","title":"Qualified through legal training","titleCN":"具备法律专业资格地","definition":"by reason of professional legal training or qualification","definitionCN":"凭借法律专业训练或执业资格","example":"She is legally trained but now writes about court reform.","exampleCN":"她受过法律专业训练，如今撰写有关法院改革的文章。","why":"The adverb attaches to training as well as to acts, because a qualification is itself something the law recognises.","whyCN":"这个副词也能附着于训练，因为资格本身就是法律所承认的东西。"}],"etymology":{"intro":{"en":"Legally is legal plus the adverb ending -ly. Legal comes from Latin legalis 'of the law', from lex 'law'; the deeper origin of lex itself is disputed.","cn":"legally 由 legal 加副词词尾构成。legal 来自拉丁 legalis「法律的」，出自 lex「法律」；而 lex 本身的更深来源存在争议。"},"items":[{"era":"LATIN LEX","en":"Lex, genitive legis, meant a statute or a binding rule. It named the enacted rule, not the abstract idea of justice, which Latin kept for ius.","cn":"lex（属格 legis）意为法令或有约束力的规则。它命名的是被制定的规则，而不是抽象的正义观念，后者在拉丁语中由 ius 承担。"},{"era":"UNCERTAIN ROOT","en":"Source uncertain (root of lex): lex is often connected with legere 'to read, to gather', but that link is a hypothesis; others derive it from a root meaning 'to lay down'. No single origin is established.","cn":"来源不确定（lex 的词根）：常有人把 lex 与 legere「读、收集」联系起来，但那只是假说；也有人把它追溯到表示「放置、立下」的词根。尚无单一结论。"},{"era":"LATIN LEGALIS","en":"Legalis 'of the law, lawful' was formed on the stem of lex and passed through French into English as legal in the medieval period.","cn":"legalis「法律的、合法的」由 lex 的词干构成，经法语在中世纪进入英语，成为 legal。"},{"era":"ADVERB -LY","en":"The English adverb ending -ly, from Old English -lice, turns the adjective into a word describing how an act is done or from what angle it is judged.","cn":"英语的副词词尾源自古英语相应的词尾形式，把形容词变成描述「如何做」或「从哪个角度判断」的词。"},{"era":"LEGAL PROFESSION","en":"As law became a profession, legally extended to training and qualification, not only to acts permitted by statute.","cn":"随着法律成为一门职业，legally 从「法令允许的行为」扩展到训练与资格。"},{"era":"APPROXIMATE DATES","en":"The first dates for the adverb are approximate: legal is attested from the medieval period, while legally settles into its modern senses in the early modern centuries.","cn":"这个副词的最早年代为约数：legal 在中世纪已有书证，legally 则在近代早期逐渐定型为今天的各义。"}]},"similar":{"note":{"en":"The first group shares the Latin law word and differs only in shade; the second group names other kinds of conformity to rule.","cn":"第一组共享那个拉丁「法律」词，差别只在分寸；第二组是对规则的其他种类的符合。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"legal","ipa":"/ˈliːɡl/","tag":"same family","definition":"The adjective: permitted by law, or belonging to law as a field.","definitionCN":"形容词：法律允许的，或属于法律领域的。"},{"word":"legality","ipa":"/liˈɡæləti/","tag":"same family","definition":"The quality of being lawful, or the question of whether something satisfies the law.","definitionCN":"合乎法律的性质，或某事物是否满足法律要求的问题。"},{"word":"legalise","ipa":"/ˈliːɡəlaɪz/","tag":"same family","definition":"To change the law so that something previously forbidden becomes permitted.","definitionCN":"修改法律，使原先被禁止的事变为允许。"},{"word":"illegal","ipa":"/ɪˈliːɡl/","tag":"same family, opposite","definition":"Forbidden by law; the negative prefix reverses the permission without changing the root.","definitionCN":"法律所禁止的；否定前缀把许可翻转为禁止，词根不变。"},{"word":"legislative","ipa":"/ˈleɡɪslətɪv/","tag":"same root, different branch","definition":"Concerned with making statutes, from lex plus latum 'carried'; it describes the making, not the obeying.","definitionCN":"与制定法令有关，由 lex 加「携带」的过去分词构成；它描述制定，而非遵守。"}]},{"heading":"NEAR MEANING","entries":[{"word":"lawfully","ipa":"/ˈlɔːfəli/","tag":"same idea, plainer word","definition":"In a way allowed by law, using the everyday noun law rather than the Latin one.","definitionCN":"以法律允许的方式，用的是日常的 law 而非拉丁词。"},{"word":"constitutionally","ipa":"/ˌkɒnstɪˈtjuːʃənəli/","tag":"higher frame","definition":"In accordance with the constitution, which outranks an ordinary statute.","definitionCN":"依宪法而行，效力高于普通法令。"},{"word":"statutorily","ipa":"/stəˈtjuːtərəli/","tag":"technical register","definition":"By the terms of a particular statute, used mostly in official and legal writing.","definitionCN":"按某部具体法令的条款，多用于官方与法律文书。"},{"word":"validly","ipa":"/ˈvælɪdli/","tag":"effect, not permission","definition":"So as to have legal effect; a valid act may still be illegal if the wrong person performed it.","definitionCN":"以至于具有法律效力；有效的行为若由无权者作出，仍可能违法。"},{"word":"rightfully","ipa":"/ˈraɪtfli/","tag":"moral claim","definition":"By a just or rightful claim, which may or may not coincide with the statute book.","definitionCN":"凭正当权利，可能与成文法令一致，也可能不一致。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin law word, the real family and real fixed phrases.","cn":"正常联想使用真实的拉丁「法律」词、真实的同族词与真实固定搭配。"},"normal":[{"en":"Lex is Latin for law, and -ly turns the adjective into the manner: in the manner of the law.","cn":"lex 是拉丁语「法律」，副词词尾把形容词变成方式：以法律的方式。"},{"en":"The family runs legal, legally, legality, legalise, legalisation and illegal.","cn":"同族词有 legal、legally、legality、legalise、legalisation 与 illegal。"},{"en":"Fixed phrases mark the binding sense: legally binding, legally required, legally entitled.","cn":"固定搭配标出约束力义：具有法律约束力、法律要求、依法有权。"},{"en":"Latin kept ius for justice and lex for the statute, a split English later lost.","cn":"拉丁语用 ius 表正义、用 lex 表法令，这一区分后来的英语丢掉了。"},{"en":"A stamp on a form is the everyday picture of something becoming legally true.","cn":"在表格上盖章，就是「某事在法律上成真」的日常画面。"}],"abstract":[{"en":"Picture a door that opens only when a seal is pressed onto the paper beside it.","cn":"想象一扇门，只有把印章压在旁边的纸上，门才会开。"},{"en":"Picture two identical letters, one inside the envelope and one still on the desk, differing only by a date stamp.","cn":"想象两封一模一样的信，一封进了信封，一封还在桌上，只差一个日期戳。"},{"en":"Picture a ruler laid on a table to decide which of two nearly equal lengths counts.","cn":"想象桌上放着一把尺，用来判定两个几乎一样长的东西哪个算数。"}]},"examples":[{"en":"The company acted legally by publishing the audit in full.","cn":"该公司完整公布审计报告，行为合法。"},{"en":"Legally, the land belongs to the trust, not to the family.","cn":"从法律上看，这块地属于信托基金，而不属于这个家庭。"},{"en":"Anyone legally resident for five years may apply for citizenship.","cn":"任何合法居住满五年的人都可以申请入籍。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「legal（合法的）+ ly（地）」——以合法的方式 → 合法地","word":"legally"},"root":"拉丁 lex（属格 legis）「法令、规则」（更深词根存疑）→ legalis「法律的」→ 法语 → 英语 legal；加副词词尾构成 legally。","sensesIntro":{"en":"Eight senses follow one stamp: the stamp permits an act, compels a notice, fixes the frame of judgment, gives a document force, certifies a procedure, meets a statutory threshold, confers a status and finally recognises a qualification.","cn":"八个义项围绕一枚印章：印章许可一个行为、强制一项通知、设定判断的框架、赋予文件效力、认证一道程序、达到法定界限、授予一种身份，最后承认一项资格。"},"semanticMap":{"core":{"en":"CORE IMAGE: one seal pressed on paper, after which the same paper can do entirely different things.","cn":"核心意象：一枚印章压在纸上，同一张纸从此能做完全不同的事。"},"chain":["PERMITTED","REQUIRED","THE LEGAL FRAME","IN FORCE","BY PROCEDURE","STATUS AND QUALIFICATION"],"branches":[{"senses":"01 · 02","en":"TWO DIRECTIONS OF THE SEAL: what the statute allows and what it demands are the same line read outward and inward.","cn":"印章的两个方向：法令允许什么与要求什么，是同一条线向外读与向内读。"},{"senses":"03","en":"THE FRAME: the adverb can step outside any particular rule and simply say which lens is being used.","cn":"框架：副词可以退到任何具体规则之外，只说明正在使用哪一副镜头。"},{"senses":"04 · 05","en":"FORCE AND ROUTE: a document with the seal, and evidence gathered the right way, are power plus the path that earned it.","cn":"效力与路径：盖了章的文件与按规矩取得的证据，是力量加上挣得它的那条路径。"},{"senses":"06 · 07","en":"DEFINITION AND STATUS: a threshold in a statute and a registration in a register both make a legal fact.","cn":"定义与身份：法令里的界限与登记册上的一笔，都在制造一项法律事实。"},{"senses":"08","en":"THE QUALIFIED PERSON: training itself becomes something the law recognises.","cn":"有资格的人：训练本身也成为法律所承认的东西。"}]},"affixes":{"intro":{"en":"Legally is a Latin law root, an adjective ending and an English adverb ending stacked in order.","cn":"legally 是把拉丁「法律」词根、形容词词尾与英语副词词尾依次叠加的结果。"},"latinIntro":{"en":"Latin lex, genitive legis, gives legal, legality, legislate and legitimate; the English -ly ending marks manner or viewpoint.","cn":"拉丁 lex（属格 legis）衍生 legal、legality、legislate 与 legitimate；英语的副词词尾标记方式或视角。"},"items":[{"word":"leg-","structure":"lex, legis (Latin noun, 'law, statute')","meaning":"law; statute","meaningCN":"法律；法令","example":"The root names the enacted rule.","exampleCN":"这个词根命名被制定的规则。"},{"word":"-al","structure":"Latin adjective ending -alis","meaning":"relating to","meaningCN":"与……相关的","example":"It forms the adjective of law.","exampleCN":"它构成表示法律的形容词。"},{"word":"legal","structure":"leg- plus -al through French","meaning":"of the law; permitted","meaningCN":"法律的；合法的","example":"The adjective holds both senses at once.","exampleCN":"这个形容词同时承载两义。"},{"word":"-ity","structure":"Latin -itas through French","meaning":"quality of","meaningCN":"……的性质","example":"It forms the noun of being lawful.","exampleCN":"它构成「合乎法律」这一性质的名词。"},{"word":"legality","structure":"legal plus -ity","meaning":"lawfulness","meaningCN":"合法性","example":"The abstract noun of the standard.","exampleCN":"这一标准的抽象名词。"},{"word":"-ise","structure":"French -iser / Latin -izare","meaning":"to make","meaningCN":"使成为","example":"It forms the verb of change.","exampleCN":"它构成表示改变的动词。"},{"word":"legalise","structure":"legal plus -ise","meaning":"to make lawful","meaningCN":"使合法化","example":"The verb names the change in the statute book.","exampleCN":"动词命名法令文本上的改变。"},{"word":"-ly","structure":"Old English -lice","meaning":"in the manner of","meaningCN":"以……方式","example":"It turns the adjective into an adverb.","exampleCN":"它把形容词变成副词。"},{"word":"legally","structure":"legal plus -ly","meaning":"in a lawful manner","meaningCN":"合法地","example":"The adverb carries permission, obligation and viewpoint.","exampleCN":"这个副词兼具许可、义务与视角。"},{"word":"il-","structure":"Latin in- before l","meaning":"not","meaningCN":"不","example":"It negates the adjective in illegal.","exampleCN":"它在「非法的」中否定形容词。"}],"latinEntries":[{"word":"lex","structure":"lex, legis (f., third declension)","meaning":"law, statute, rule","meaningCN":"法律；法令；规则"},{"word":"legalis","structure":"legalis, legale (adj., third declension)","meaning":"of the law, lawful","meaningCN":"法律的；合法的"},{"word":"legitimus","structure":"legitimus, legitima, legitimum (adj.)","meaning":"lawful, legitimate","meaningCN":"合法的；正当的"},{"word":"legislator","structure":"legislator, legislatoris (m., third declension)","meaning":"lawgiver","meaningCN":"立法者"}],"derivatives":[{"word":"legal","pos":"adj.","zh":"法律的；合法的"},{"word":"legality","pos":"n.","zh":"合法性"},{"word":"legalise","pos":"v.","zh":"使合法化"},{"word":"legalisation","pos":"n.","zh":"合法化"},{"word":"illegal","pos":"adj.","zh":"非法的"}]}},{"word":"legality","ipa_uk":"/liˈɡæləti/","ipa_us":"/liˈɡæləti/","definition_zh":"合法性；合乎法律的性质；（某一行为或决定的）法律效力","definition_en":"the quality or state of being allowed by law, or the question of whether an act, order or body conforms to legal rules","core_image":"一叠文件摊在桌上，红笔沿条文一路打勾，勾到一半停住，那一行就是站不住脚的地方","scene":"委员会整个上午都在追问那条紧急命令究竟站不站得住脚。The committee spent the morning questioning the legality of the emergency order.","sceneCN":"这里 legality 指「某项命令是否符合法律、是否具有法律依据」（第 2 个义项：对具体法令的符合性）；句意为委员会用整个上午追问那条紧急命令的合法性。图中可辨识物件：成叠文件、红笔、条文页眉、问号标记。","pos":[{"tag":"n.","zh":"合法性；合乎法律；法律效力（可数时指具体的合法性问题）"}],"collocations":[{"phrase":"the legality of the order","zh":"该命令的合法性"},{"phrase":"question the legality of","zh":"质疑……的合法性"},{"phrase":"legality and legitimacy","zh":"合法性与正当性"},{"phrase":"dispute the legality","zh":"对合法性提出争议"},{"phrase":"legality review","zh":"合法性审查"},{"phrase":"doubtful legality","zh":"可疑的合法性"}],"forms":[{"label":"复数（多指具体问题）","form":"legalities"},{"label":"形容词","form":"legal"},{"label":"副词","form":"legally"},{"label":"动词","form":"legalise"},{"label":"名词（非法状态）","form":"illegality"}],"derivatives":[{"word":"legal","pos":"adj.","zh":"法律的；合法的"},{"word":"legally","pos":"adv.","zh":"合法地"},{"word":"illegality","pos":"n.","zh":"非法性；违法行为"},{"word":"legalise","pos":"v.","zh":"使合法化"},{"word":"legalistic","pos":"adj.","zh":"拘泥法律条文的"}],"senses":[{"no":"01","title":"Lawfulness in general","titleCN":"合乎法律这一性质本身","definition":"the quality of being in accordance with law, considered as a general property","definitionCN":"与法律相符这一性质，作为一般属性来看","example":"The court's ruling turned on the legality of the search, not on the facts.","exampleCN":"法院的裁决取决于搜查是否合法，而不是事实本身。","why":"Formed from legalis 'of the law' plus the quality suffix -itas, the noun names the property itself, the way brightness names the property of being bright.","whyCN":"这个名词由 legalis「法律的」加表示性质的后缀构成，命名的是性质本身，正如 brightness 命名「亮」这一性质。"},{"no":"02","title":"Conformity with a particular rule","titleCN":"对某一具体法令或命令的符合","definition":"the fact of conforming, or failing to conform, to a specific statute, order or procedure","definitionCN":"符合或不符合某一具体法令、命令或程序的事实","example":"The committee spent the morning questioning the legality of the emergency order.","exampleCN":"委员会整个上午都在追问那条紧急命令的合法性。","why":"Once a rule exists, the interesting question is whether this act matches it, so the noun shifts from a general property to a testable fit.","whyCN":"一旦存在一条规则，真正的问题就是「这个行为是否与它相符」，名词于是从一般属性变为可检验的符合性。"},{"no":"03","title":"Validity of an official act","titleCN":"官方行为或决定在程序上的有效性","definition":"the validity of an official decision when measured against the powers that were granted to make it","definitionCN":"把官方决定对照其被授予的权限来衡量时，该决定是否有效","example":"Lawyers disputed the legality of a ruling issued after the deadline.","exampleCN":"律师们对一份在期限之后作出的裁决是否合法提出争议。","why":"An official may act wrongly in two ways, by doing what is forbidden and by acting beyond the power given; legality covers both.","whyCN":"官员可以在两处出错：做被禁止的事，或越过被授予的权力；合法性同时覆盖这两者。"},{"no":"04","title":"Legal standing of a body","titleCN":"某一机构在法律上的地位","definition":"the recognised legal existence or status of an organisation, party or government","definitionCN":"某一组织、政党或政府被法律承认的存在或地位","example":"Observers asked about the legality of the provisional council.","exampleCN":"观察人士询问该临时委员会在法律上是否成立。","why":"A body can exist in fact and still lack legal existence, so the noun is used for the gap between being there and being recognised.","whyCN":"一个机构可以在事实上存在却缺乏法律上的存在，名词因此被用来指「存在于那里」与「被承认」之间的缝隙。"},{"no":"05","title":"Respect for the legal order","titleCN":"作为价值的守法原则","definition":"the principle that public power should be exercised through law and that everyone, including officials, is bound by it","definitionCN":"主张公共权力应经由法律行使、包括官员在内人人受其约束的原则","example":"The report treats legality as a guarantee against arbitrary rule.","exampleCN":"这份报告把守法原则视为抵御任意统治的保障。","why":"The abstract noun can be turned into a value, and then it means not the fit of one act but the commitment to keep measuring acts at all.","whyCN":"抽象名词可以转成一个价值，此时它指的不是某一行为的符合，而是坚持对所有行为加以衡量的承诺。"},{"no":"06","title":"The question courts review","titleCN":"法院审查时所称的合法性问题","definition":"the issue a court decides when it reviews whether an authority stayed inside its legal powers","definitionCN":"法院在审查某一机关是否停留在其法定权限内时所判定的争点","example":"Judicial review separates questions of legality from questions of merit.","exampleCN":"司法审查把合法性问题与是非优劣的问题分开。","why":"Judges are not asked whether a decision was wise, only whether it was legally possible, and that narrow question takes the noun.","whyCN":"法官不被问决定是否明智，只被问在法律上是否可能，这个狭窄的问题便承接了这个名词。"},{"no":"07","title":"Lawfulness under international rules","titleCN":"依国际法规则判断的合法性","definition":"the conformity of a state's action to treaties, customary rules or a charter","definitionCN":"国家行为对条约、习惯规则或宪章的符合","example":"Debate over the legality of the intervention split the assembly.","exampleCN":"关于这次干预是否合法的争论让大会分裂。","why":"There is no world statute book, so legality at that level means fit with agreements and accepted practice rather than with one parliament's act.","whyCN":"世界上没有统一的法令全书，因此这一层面的合法性指与协议和公认惯例相符，而非与某一议会的法案相符。"},{"no":"08","title":"Legality as distinct from legitimacy","titleCN":"与「正当性」相区分的合法性","definition":"formal conformity to law, considered separately from whether the law or the act is morally accepted","definitionCN":"对法律形式上的符合，与法律或行为是否在道德上被接受分开来看","example":"A policy can satisfy legality and still lack legitimacy among the people it affects.","exampleCN":"一项政策可以在形式上合法，却在受影响的人群中缺乏正当性。","why":"Political theory needed two words because a ruler may obey every statute and still be rejected, and that gap is exactly what this contrast marks.","whyCN":"政治理论需要两个词，因为统治者可能条条守法却仍被拒斥，这一落差正是该对照所标记的。"}],"etymology":{"intro":{"en":"Legality comes from medieval Latin legalitas, formed on legalis 'of the law', which rests on lex 'law'. English took it through French in the late medieval period.","cn":"legality 来自中世纪拉丁 legalitas，由 legalis「法律的」构成，而后者出自 lex「法律」。英语在中世纪后期经法语借入。"},"items":[{"era":"LATIN LEX","en":"Lex, genitive legis, named an enacted statute rather than justice in the abstract; ius covered the wider idea of right.","cn":"lex（属格 legis）命名被制定的法令，而非抽象的正义；更宽的权利观念由 ius 承担。"},{"era":"UNCERTAIN ROOT","en":"Source uncertain (root of lex): a link with legere 'to read, gather' is often proposed but not demonstrated, and a derivation from a root meaning 'to lay down' is also argued.","cn":"来源不确定（lex 的词根）：与 legere「读、收集」的联系常被提出，但未获证明；也有从表示「立下、放置」的词根派生之说。"},{"era":"MEDIEVAL LEGALITAS","en":"Legalitas was used in medieval Latin for the quality of being lawful, especially of an act or a person's status under canon and civil law.","cn":"legalitas 在中世纪拉丁语中指合乎法律的性质，尤用于教会法与市民法下的行为或身份。"},{"era":"FRENCH AND ENGLISH","en":"The noun reached English through French in the late medieval period, first in the sense of lawfulness in general.","cn":"这个名词在中世纪后期经法语进入英语，最初指一般的守法性。"},{"era":"CONSTITUTIONAL ERA","en":"With written constitutions and judicial review, legality became a testable question about official powers rather than a description of a person.","cn":"随着成文宪法与司法审查的出现，合法性从对人的描述变成关于官方权限的可检验问题。"},{"era":"APPROXIMATE DATES","en":"The earliest English citation is approximate: the medieval borrowing is well attested, but the modern review sense is dated only roughly to the constitutional period.","cn":"英语最早书证为约数：中世纪借入一事有充分书证，而现代的审查义只能粗略定在立宪时期。"}]},"similar":{"note":{"en":"The first group is the same Latin family and is the commonest source of error; the second group names neighbouring standards that are often confused with legality.","cn":"第一组是同出拉丁词族的词，也是最常见的出错来源；第二组是常与合法性混淆的相邻标准。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"legal","ipa":"/ˈliːɡl/","tag":"same family","definition":"The adjective: allowed by law, or belonging to the field of law.","definitionCN":"形容词：法律允许的，或属于法律领域的。"},{"word":"legally","ipa":"/ˈliːɡəli/","tag":"same family","definition":"The adverb: in a lawful manner, or judged from the law's angle.","definitionCN":"副词：以合法方式，或从法律角度判断。"},{"word":"illegality","ipa":"/ˌɪləˈɡæləti/","tag":"same family, opposite","definition":"The same property negated; it can also name a specific unlawful act.","definitionCN":"同一性质的否定形式；也可指具体的违法行为。"},{"word":"legalise","ipa":"/ˈliːɡəlaɪz/","tag":"same family","definition":"The verb of removing a prohibition, which changes the statute rather than proving conformity to it.","definitionCN":"解除禁令的动词，改变的是法令，而非证明符合法令。"},{"word":"legislative","ipa":"/ˈleɡɪslətɪv/","tag":"same root, other branch","definition":"About making statutes, from lex plus latum 'carried'; it describes the source of rules, not their observance.","definitionCN":"关于制定法令，由 lex 加「携带」的过去分词构成；它描述规则的来源，而非遵守。"}]},{"heading":"NEAR MEANING","entries":[{"word":"legitimacy","ipa":"/lɪˈdʒɪtɪməsi/","tag":"the classic contrast","definition":"Acceptance by those governed, resting on consent, tradition or fairness; an act can be lawful and still lack it.","definitionCN":"被治理者的接受，建立在同意、传统或公平之上；一个行为可以合法却仍缺乏它。"},{"word":"validity","ipa":"/vəˈlɪdəti/","tag":"technical effect","definition":"Whether an act produces its intended legal effect, which may fail for procedural reasons even when the power existed.","definitionCN":"行为是否产生预期法律效果；即使权限存在，也可能因程序问题而失效。"},{"word":"lawfulness","ipa":"/ˈlɔːflnəs/","tag":"plain doublet","definition":"The everyday synonym, built on the native noun law rather than the Latin one.","definitionCN":"日常同义词，由本族词 law 而非拉丁词构成。"},{"word":"constitutionality","ipa":"/ˌkɒnstɪˌtjuːʃəˈnæləti/","tag":"higher test","definition":"Conformity to the constitution specifically, a narrower and stronger standard than ordinary legality.","definitionCN":"特指对宪法的符合，比一般的合法性更窄也更强。"},{"word":"propriety","ipa":"/prəˈpraɪəti/","tag":"social standard","definition":"Correctness by social or professional norms, which law does not enforce.","definitionCN":"依社会或职业规范的正确性，法律并不强制执行。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin law word, the real family and real fixed phrases.","cn":"正常联想使用真实的拉丁「法律」词、真实的同族词与真实固定搭配。"},"normal":[{"en":"Lex is Latin for statute, and the quality suffix turns it into the property of conforming, so legality is the fit between act and rule.","cn":"lex 是拉丁语「法令」，表性质的后缀把词变成「符合」这一属性，因此合法性就是行为与规则之间的贴合。"},{"en":"The family runs legal, legally, legality, illegal, illegality and legalise.","cn":"同族词有 legal、legally、legality、illegal、illegality 与 legalise。"},{"en":"Fixed phrases mark the tested sense: question the legality of, legality review, legality and legitimacy.","cn":"固定搭配标出被检验的义：质疑……的合法性、合法性审查、合法性与正当性。"},{"en":"Latin kept ius for right and lex for statute, which is why English legality never means justice.","cn":"拉丁语用 ius 表权利、用 lex 表法令，因此英语的合法性从不等于正义。"},{"en":"The pair legality and legitimacy is the standard way to say 'allowed' versus 'accepted'.","cn":"合法性与正当性这一对，是区分「被允许」与「被接受」的标准说法。"}],"abstract":[{"en":"Picture a red pen ticking down a list of clauses and stopping at one line.","cn":"想象一支红笔沿条款清单一路打勾，到某一行停住。"},{"en":"Picture a building with a legal address but no key that any court would hand over.","cn":"想象一栋有法定地址、却拿不到任何法院会交付的钥匙的楼。"},{"en":"Picture two identical stamps, one on a treaty and one on a parking ticket.","cn":"想象两枚一模一样的印章，一枚盖在条约上，一枚盖在停车罚单上。"}]},"examples":[{"en":"The auditors raised doubts about the legality of the transfer.","cn":"审计人员对这笔转账的合法性提出了疑问。"},{"en":"Legality is not the same as popularity.","cn":"合法并不等于受欢迎。"},{"en":"The charter sets out the legality of using force in self-defence.","cn":"宪章规定了在自卫中使用武力的合法性。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「legal（合法的）+ ity（性质）」——合乎法律的这种性质 → 合法性","word":"legality"},"root":"拉丁 lex（属格 legis）「法令」（更深词根存疑）→ legalis「法律的」→ 中世纪拉丁 legalitas「合乎法律的性质」→ 法语 → 英语 legality。","sensesIntro":{"en":"Eight senses follow one red tick: it marks a property, tests a specific order, checks an official's power, asks whether a body exists in law, becomes a civic value, narrows into a judicial question, crosses into international rules, and finally splits from legitimacy.","cn":"八个义项围绕一道红勾：它标出一种性质，检验一条具体命令，核对官员的权限，追问机构在法律上是否存在，升为公民价值，收窄为司法问题，跨入国际规则，最后与正当性分开。"},"semanticMap":{"core":{"en":"CORE IMAGE: a red pen running down a page of clauses, stopping where the fit breaks.","cn":"核心意象：一支红笔沿满页条款向下走，在贴合断掉的地方停住。"},"chain":["THE PROPERTY","FIT TO ONE RULE","FIT OF AN OFFICIAL ACT","EXISTENCE IN LAW","A CIVIC VALUE","JUDICIAL AND INTERNATIONAL FIT"],"branches":[{"senses":"01 · 02","en":"PROPERTY AND TEST: the abstract quality and the concrete fit are the same measurement at two levels of generality.","cn":"性质与检验：抽象性质与具体符合，是同一次衡量在两个概括层次上。"},{"senses":"03 · 04","en":"POWER AND EXISTENCE: an act beyond granted power, and a body without legal existence, are two ways of failing the same test.","cn":"权限与存在：越权作出的行为与法律上不存在的机构，是同一种检验的两种失败。"},{"senses":"05","en":"THE VALUE: the noun can stop measuring single acts and become a commitment to keep measuring.","cn":"价值：名词可以不再衡量单个行为，而成为一种坚持衡量的承诺。"},{"senses":"06 · 07","en":"TWO COURTS: a domestic judge asks whether the power existed; international law asks whether the state kept its agreements.","cn":"两座法庭：国内法官问权限是否存在，国际法问国家是否守约。"},{"senses":"08","en":"THE SPLIT: legality measures the fit, legitimacy measures the acceptance, and the pair exists because the two can diverge.","cn":"分裂：合法性衡量贴合，正当性衡量接受；这一对之所以存在，正因为两者可以背离。"}]},"affixes":{"intro":{"en":"Legality is a Latin law root plus a quality suffix, with the adjective ending still visible inside it.","cn":"legality 是一个拉丁「法律」词根加表性质的后缀，形容词词尾仍留在词内。"},"latinIntro":{"en":"Latin lex, genitive legis, gives legalis, legalitas and legislator; the same root is behind legitimate, though through a different stem.","cn":"拉丁 lex（属格 legis）衍生 legalis、legalitas 与 legislator；同一词根也在 legitimate 背后，但经另一词干。"},"items":[{"word":"leg-","structure":"lex, legis (Latin noun, 'law')","meaning":"law; statute","meaningCN":"法律；法令","example":"The root names the enacted rule.","exampleCN":"这个词根命名被制定的规则。"},{"word":"-al","structure":"Latin adjective ending -alis","meaning":"relating to","meaningCN":"与……相关的","example":"It forms the adjective of law.","exampleCN":"它构成表示法律的形容词。"},{"word":"legal","structure":"leg- plus -al","meaning":"of the law","meaningCN":"法律的","example":"The base adjective of the whole family.","exampleCN":"整个词族的基础形容词。"},{"word":"-ity","structure":"Latin -itas through French","meaning":"quality of","meaningCN":"……的性质","example":"It turns the adjective into a property noun.","exampleCN":"它把形容词变成表性质的名词。"},{"word":"legality","structure":"legal plus -ity","meaning":"lawfulness","meaningCN":"合法性","example":"The noun names the fit, not the rule.","exampleCN":"名词命名贴合，而非规则。"},{"word":"il-","structure":"Latin in- before l","meaning":"not","meaningCN":"不","example":"It negates the property.","exampleCN":"它否定这一性质。"},{"word":"illegality","structure":"il- plus legality","meaning":"unlawfulness","meaningCN":"非法性","example":"The opposite property, also used for one unlawful act.","exampleCN":"相反的性质，也可指一桩违法行为。"},{"word":"-ise","structure":"French -iser","meaning":"to make","meaningCN":"使成为","example":"It forms the verb of changing the statute.","exampleCN":"它构成修改法令的动词。"},{"word":"legalise","structure":"legal plus -ise","meaning":"to make lawful","meaningCN":"使合法化","example":"The verb changes the rule, not the fit.","exampleCN":"动词改变规则，而非贴合。"},{"word":"legis-","structure":"lex plus a stem in -s","meaning":"law as a combining form","meaningCN":"法律的（组合形式）","example":"It appears in legislate and legislator.","exampleCN":"它出现在「立法」与「立法者」中。"}],"latinEntries":[{"word":"lex","structure":"lex, legis (f., third declension)","meaning":"law, statute","meaningCN":"法律；法令"},{"word":"legalis","structure":"legalis, legale (adj., third declension)","meaning":"of the law","meaningCN":"法律的"},{"word":"legalitas","structure":"legalitas, legalitatis (f., third declension)","meaning":"lawfulness","meaningCN":"合法性"},{"word":"legislator","structure":"legislator, legislatoris (m., third declension)","meaning":"lawgiver","meaningCN":"立法者"}],"derivatives":[{"word":"legal","pos":"adj.","zh":"法律的；合法的"},{"word":"legally","pos":"adv.","zh":"合法地"},{"word":"illegality","pos":"n.","zh":"非法性；违法行为"},{"word":"legalise","pos":"v.","zh":"使合法化"},{"word":"legalistic","pos":"adj.","zh":"拘泥法律条文的"}]}},{"word":"illegal","ipa_uk":"/ɪˈliːɡl/","ipa_us":"/ɪˈliːɡl/","definition_zh":"非法的；违法的；法律禁止的；（规则或格式上）不允许的","definition_en":"forbidden by law or by an official rule, and therefore not permitted to be done, held or used","core_image":"仓库大门上贴了封条，叉车停在门口，操纵杆上的手缩了回去","scene":"稽查员把仓库贴上封条，因为里面那批货不允许存放。The inspector sealed the warehouse because the goods inside were illegal to store.","sceneCN":"这里 illegal 指「法律禁止持有或存放的」（第 1 个义项：被法律禁止的）；句意为稽查员封上仓库，因为里面的货物在法律上不允许存放。图中可辨识物件：封条、叉车、卷帘门、货箱。","pos":[{"tag":"adj.","zh":"非法的；违法的；规章不允许的"},{"tag":"n.","zh":"（新闻用语）无合法居留身份者"}],"collocations":[{"phrase":"illegal activity","zh":"违法活动"},{"phrase":"illegal goods","zh":"违禁货物"},{"phrase":"it is illegal to","zh":"做……是违法的"},{"phrase":"illegal immigrants","zh":"非法移民"},{"phrase":"declare something illegal","zh":"宣布某事非法"},{"phrase":"an illegal move","zh":"违规的一步"}],"forms":[{"label":"比较级","form":"more illegal"},{"label":"最高级","form":"most illegal"},{"label":"名词","form":"illegality"},{"label":"副词","form":"illegally"},{"label":"复数（名词）","form":"illegals"}],"derivatives":[{"word":"illegality","pos":"n.","zh":"非法性；违法行为"},{"word":"illegally","pos":"adv.","zh":"非法地"},{"word":"legal","pos":"adj.","zh":"合法的（去掉否定前缀的正面形式）"},{"word":"legalise","pos":"v.","zh":"使合法化"}],"senses":[{"no":"01","title":"Forbidden by statute","titleCN":"被法律明文禁止的","definition":"forbidden by a statute, so that doing it can be punished by the state","definitionCN":"被法令明文禁止，实施者可能受到国家处罚","example":"The inspector sealed the warehouse because the goods inside were illegal to store.","exampleCN":"稽查员封上仓库，因为里面的货物在法律上不允许存放。","why":"Illegal is in- 'not' plus legalis 'of the law': it does not describe a moral fault but a rule that the state will enforce.","whyCN":"illegal 是「不」加 legalis「法律的」：它描述的不是道德过失，而是国家会强制执行的规则。"},{"no":"02","title":"Against a specific regulation","titleCN":"违反某项具体规章的（未必构成犯罪）","definition":"breaking a rule or by-law that carries a penalty but is not treated as a crime","definitionCN":"违反一条带有处罚、但不被当作犯罪处理的规则或细则","example":"Parking there is illegal between eight and ten in the morning.","exampleCN":"早上八点到十点之间在那里停车是违规的。","why":"English separates crimes from regulatory offences, and illegal covers both: the prefix says 'not allowed', not 'criminal'.","whyCN":"英语把犯罪与行政违规分开，而 illegal 两者都覆盖：前缀说的是「不被允许」，而不是「构成犯罪」。"},{"no":"03","title":"Without lawful status","titleCN":"身份或证件在法律上不合规的","definition":"describing a person's presence or papers as lacking the required legal permission","definitionCN":"描述某人的居留或证件缺少法律所要求的许可","example":"The charity provides advice to workers who are illegal after their visas lapse.","exampleCN":"这家慈善机构为签证过期后失去合法身份的工人提供咨询。","why":"Status, not conduct, is being judged here: a person can break no rule and still lack the permission that makes staying lawful.","whyCN":"这里被判断的是身份而非行为：一个人可以不违反任何规则，却仍缺少使居留合法的许可。"},{"no":"04","title":"Banned goods","titleCN":"法律禁止持有、买卖或运输的物品","definition":"describing goods that may not be held, sold or moved under the law","definitionCN":"描述在法律下不得持有、出售或搬运的货物","example":"Customs officers seized illegal ivory at the border.","exampleCN":"海关官员在边境查获了违禁的象牙。","why":"The adjective attaches to things as well as acts, because a statute can forbid an object outright, not only its handling.","whyCN":"这个形容词也附着于物品，因为法令可以直接禁止某件东西的存在，而不只是禁止处理它。"},{"no":"05","title":"Against the rules of a game","titleCN":"违反比赛规则的","definition":"describing a move or action that the rules of a sport or game do not allow","definitionCN":"描述某项运动或游戏规则所不允许的动作","example":"The referee stopped play for an illegal block.","exampleCN":"裁判因一次违规阻挡中止了比赛。","why":"Games have their own statutes, and players borrow the legal vocabulary to say that a move is outside them.","whyCN":"比赛有自己的章程，参与者便借法律词汇来说某一步在章程之外。"},{"no":"06","title":"Not allowed by a format or system","titleCN":"不符合格式或系统规范的","definition":"describing a character, input or operation that a technical system refuses to accept","definitionCN":"描述技术系统拒绝接受的字符、输入或操作","example":"The parser rejects the file because it contains an illegal character.","exampleCN":"解析器拒绝这个文件，因为它含有非法字符。","why":"Technical writing extends the word from laws to specifications: anything that a system's rules do not admit is illegal to that system.","whyCN":"技术写作把这个词从法律扩展到规范：系统的规则不接纳的东西，对该系统而言就是非法的。"},{"no":"07","title":"A person without legal status","titleCN":"新闻用语：无合法身份者（名词）","definition":"a noun used in news writing for people present or working without legal permission","definitionCN":"新闻写作中的名词，指无合法许可而居留或工作的人","example":"The report counted the number of illegals detained at the port.","exampleCN":"该报道统计了在港口被拘留的无合法身份者人数。","why":"Newspaper style turns adjectives into nouns for brevity, which is why the same word can label people as well as acts.","whyCN":"报纸文体为了简短把形容词直接作名词，因此同一个词既能标记行为，也能标记人。"},{"no":"08","title":"Against accepted practice, informally","titleCN":"非正式用法：被规矩或惯例禁止的","definition":"used loosely for something that is against accepted practice rather than against a statute","definitionCN":"宽泛地指违反公认做法、而非违反法令的事","example":"Taking the last biscuit without asking is illegal in this office.","exampleCN":"在这间办公室里，不问一声就拿走最后一块饼干是犯忌的。","why":"Everyday speech exaggerates rules into laws for comic effect, and the adjective's force comes precisely from that overstatement.","whyCN":"日常语言为求谐趣把规矩夸张成法律，这个形容词的力量正来自这种夸大。"}],"etymology":{"intro":{"en":"Illegal is the Latin negative prefix in-, assimilated to il- before l, plus legalis 'of the law', from lex 'law'. English borrowed it in the seventeenth century, probably through French.","cn":"illegal 是拉丁语否定前缀在 l 前同化后的形态加 legalis「法律的」（出自 lex「法律」）构成。英语在十七世纪借入，很可能经法语。"},"items":[{"era":"LATIN LEX","en":"Lex, genitive legis, meant an enacted statute. The wider notion of right was carried by ius, so legality and justice were separate words from the start.","cn":"lex（属格 legis）意为被制定的法令；更宽的权利观念由 ius 承担，因此「合法性」与「正义」从一开始就是两个词。"},{"era":"UNCERTAIN ROOT","en":"Source uncertain (root of lex): the common suggestion that lex derives from legere 'to read, gather' is unproven, and a root meaning 'to lay down' has also been argued.","cn":"来源不确定（lex 的词根）：常见的「出自 legere「读、收集」」一说未获证明，也有从表示「立下、放置」的词根派生之说。"},{"era":"NEGATIVE PREFIX IN-","en":"Latin in- meant 'not' before adjectives; before l it assimilates to il-, which is why English writes illegal rather than inlegal.","cn":"拉丁语的否定前缀在形容词前表示「不」；在 l 前发生同化，因此英语拼作 illegal，而不是未同化的形式。"},{"era":"SEVENTEENTH-CENTURY ENGLISH","en":"Illegal enters English in the early seventeenth century, most likely from French illégal, and at first applies to acts contrary to statute.","cn":"illegal 在十七世纪前期进入英语，最可能来自法语 illégal，最初用于违反法令的行为。"},{"era":"WIDENING TO RULES","en":"Later usage extends it to regulations, games and technical formats, where the penalty is administrative, sporting or mechanical rather than criminal.","cn":"后来的用法把它扩展到规章、比赛与技术格式，在这些领域处罚是行政性、竞技性或机械性的，而非刑事性的。"},{"era":"APPROXIMATE DATES","en":"The first English date is approximate: early seventeenth-century uses are recorded, but the exact first citation is not settled.","cn":"英语首见年代为约数：十七世纪前期已有用例记录，确切的最早书证尚无定论。"}]},"similar":{"note":{"en":"The first group shares the negative prefix but attaches it to different roots, which is the usual reading trap; the second group names kinds of prohibition.","cn":"第一组共享否定前缀，却接在不同词根上，这是最常见的读错陷阱；第二组是各种禁令类型。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"illegible","ipa":"/ɪˈledʒəbl/","tag":"il- plus legere","definition":"Built on legere 'to read': handwriting that cannot be read. It has nothing to do with law.","definitionCN":"由 legere「读」构成：指无法辨认的字迹，与法律无关。"},{"word":"illiterate","ipa":"/ɪˈlɪtərət/","tag":"il- plus littera","definition":"Built on littera 'letter': unable to read or write, again a different root.","definitionCN":"由 littera「字母」构成：指不识字，又是另一个词根。"},{"word":"illegitimate","ipa":"/ˌɪlɪˈdʒɪtɪmət/","tag":"different stem","definition":"From legitimus 'lawful' but with the sense of not authorised or not born within marriage; it judges standing, not the statute book alone.","definitionCN":"出自 legitimus「合法的」，却指未获授权或非婚生；它判断的是身份，而不只是法令文本。"},{"word":"illogical","ipa":"/ɪˈlɒdʒɪkl/","tag":"il- plus logos","definition":"Built on logos 'reason': contrary to reasoning, with no legal content at all.","definitionCN":"由 logos「理性」构成：指不合逻辑，完全不含法律内容。"},{"word":"illicit","ipa":"/ɪˈlɪsɪt/","tag":"different prefix","definition":"From in- plus licitus 'permitted': forbidden, often with a flavour of secrecy or smuggling.","definitionCN":"由「不」加 licitus「被允许的」构成：指被禁止，常带隐秘或走私的色彩。"}]},{"heading":"NEAR MEANING","entries":[{"word":"unlawful","ipa":"/ʌnˈlɔːfl/","tag":"formal legal register","definition":"The word used in statutes and contracts for what the law forbids; it is the formal twin of illegal.","definitionCN":"法令与合同中用来指法律所禁止之事的词，是 illegal 的正式对应词。"},{"word":"criminal","ipa":"/ˈkrɪmɪnl/","tag":"crime only","definition":"Reserved for conduct that is a crime and punishable by prosecution, a narrower band than illegal.","definitionCN":"专指构成犯罪、可被追诉的行为，范围比 illegal 窄。"},{"word":"prohibited","ipa":"/prəˈhɪbɪtɪd/","tag":"official ban","definition":"Forbidden by an explicit ban, often printed on a sign or a list.","definitionCN":"被明令禁止，常印在标牌或清单上。"},{"word":"banned","ipa":"/bænd/","tag":"total exclusion","definition":"Officially excluded from use or sale, usually after a decision by an authority.","definitionCN":"经主管机关决定后被排除在使用或销售之外。"},{"word":"void","ipa":"/vɔɪd/","tag":"no effect","definition":"Describing a contract or act with no legal force, which is a consequence of illegality rather than a synonym for it.","definitionCN":"描述合同或行为没有法律效力；这是违法的后果，而非其同义词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real negative prefix, the real root and real fixed phrases.","cn":"正常联想使用真实的否定前缀、真实词根与真实固定搭配。"},"normal":[{"en":"In- means not, and before l it turns into il-, so illegal is simply 'not legal'.","cn":"否定前缀表示「不」，在 l 前发生同化，所以 illegal 就是「不合法」。"},{"en":"The family runs legal, illegal, illegally, illegality and legalise.","cn":"同族词有 legal、illegal、illegally、illegality 与 legalise。"},{"en":"Fixed phrases mark the everyday sense: illegal activity, illegal goods, it is illegal to.","cn":"固定搭配标出日常义：违法活动、违禁货物、做……是违法的。"},{"en":"The same il- sits on legible, literate and logical with entirely different roots, so check what follows the prefix.","cn":"同一个否定前缀也出现在「可读」「识字」「合逻辑」这些词上，词根完全不同，因此要看前缀后面接的是什么。"},{"en":"Courts distinguish unlawful from criminal: illegal covers both, which is why the word appears in parking rules as well as in statutes.","cn":"法院区分「违法」与「犯罪」：illegal 两者都覆盖，因此它既出现在停车规定里，也出现在刑法里。"}],"abstract":[{"en":"Picture a strip of paper sealing a roller door, and a hand pulling back from the lever.","cn":"想象一条封条贴在卷帘门上，一只手从操纵杆上缩回。"},{"en":"Picture a chess piece lifted and put back because the square it wanted was not allowed.","cn":"想象一枚棋子被拿起又放回，因为它想去的那格不被允许。"},{"en":"Picture a keyboard where one key simply refuses to print, no matter how hard it is pressed.","cn":"想象一个键盘，有一个键无论怎么按都不肯打出字来。"}]},"examples":[{"en":"It is illegal to dump waste into the river.","cn":"向河里倾倒废弃物是违法的。"},{"en":"The court declared the seizure illegal and returned the cargo.","cn":"法院宣布扣押行为违法，并归还了货物。"},{"en":"The software throws an error when it meets an illegal value.","cn":"遇到非法值时，软件会报错。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「il（不）+ legal（合法的）」——不合法的 → 非法的","word":"illegal"},"root":"拉丁语的否定前缀（在 l 前发生同化）+ legalis「法律的」，后者出自 lex「法令」（更深词根存疑）；英语 illegal，十七世纪经法语借入。","sensesIntro":{"en":"Eight senses follow one seal: it shuts a warehouse, closes a parking bay, marks a person's papers, bans an object, stops a game, rejects a character, names a detainee, and finally exaggerates an office custom.","cn":"八个义项围绕一张封条：它封住仓库、封住车位、标记一个人的证件、禁掉一件物品、叫停一场比赛、拒绝一个字符、给被拘留者一个称呼，最后夸张地形容一条办公室惯例。"},"semanticMap":{"core":{"en":"CORE IMAGE: a paper seal on a door, and a hand withdrawing from what lies behind it.","cn":"核心意象：门上一张封条，一只手从门后的东西上缩回来。"},"chain":["NOT ALLOWED","NOT LAWFUL","NO STATUS","NO SALE","NO MOVE","THE PERSON AND THE JOKE"],"branches":[{"senses":"01 · 04","en":"THINGS AND ACTS: a statute can forbid an act and an object alike, so the seal sits on deeds and on crates.","cn":"行为与物品：法令既能禁止行为也能禁止物品，封条因此既贴在行为上，也贴在货箱上。"},{"senses":"02 · 05","en":"TWO RULE BOOKS: a by-law and a game's rules both use the word, though the penalty is a fine or a whistle.","cn":"两本规则书：行政细则与比赛规则都用这个词，只是处罚是罚款或哨声。"},{"senses":"03 · 07","en":"STATUS AND THE PERSON: papers can be missing, and a noun can then stand for the person holding them.","cn":"身份与人：证件可以缺失，名词于是可以指持证的那个人。"},{"senses":"06","en":"THE MACHINE'S RULE BOOK: a format refuses input the way a statute refuses an act.","cn":"机器的规则书：格式拒绝输入，正如法令拒绝行为。"},{"senses":"08","en":"THE EXAGGERATION: a household custom borrows the whole force of the statute for a biscuit.","cn":"夸张：一条家中惯例借来法令的全部力量，只为一块饼干。"}]},"affixes":{"intro":{"en":"Illegal is a negative prefix on a Latin law adjective, and the two pieces recur separately across English.","cn":"illegal 是加在拉丁法律形容词上的否定前缀，这两部分在英语里各自反复出现。"},"latinIntro":{"en":"The prefix in- negates adjectives throughout Latin and English; legalis and lex supply legal, legality and legislate.","cn":"否定前缀在拉丁语与英语中普遍用于否定形容词；legalis 与 lex 提供 legal、legality 与 legislate。"},"items":[{"word":"in-","structure":"Latin prefix, 'not'","meaning":"not","meaningCN":"不","example":"It reverses the adjective.","exampleCN":"它反转形容词。"},{"word":"il-","structure":"in- assimilated before l","meaning":"not","meaningCN":"不（在 l 前）","example":"The assimilation explains the spelling.","exampleCN":"同化解释了拼写。"},{"word":"leg-","structure":"lex, legis (Latin noun)","meaning":"law; statute","meaningCN":"法律；法令","example":"The root supplies the rule being negated.","exampleCN":"词根提供被否定的规则。"},{"word":"-al","structure":"Latin adjective ending -alis","meaning":"relating to","meaningCN":"与……相关的","example":"It forms the adjective of law.","exampleCN":"它构成法律形容词。"},{"word":"legal","structure":"leg- plus -al","meaning":"of the law","meaningCN":"法律的","example":"The positive base of the pair.","exampleCN":"这一对的正面基础词。"},{"word":"illegal","structure":"il- plus legal","meaning":"not permitted by law","meaningCN":"非法的","example":"The negative member of the pair.","exampleCN":"这一对的否定成员。"},{"word":"-ly","structure":"Old English -lice","meaning":"in the manner of","meaningCN":"以……方式","example":"It forms the adverb.","exampleCN":"它构成副词。"},{"word":"illegally","structure":"illegal plus -ly","meaning":"in an unlawful way","meaningCN":"非法地","example":"The adverb describes how the act was done.","exampleCN":"副词描述行为如何做出。"},{"word":"-ity","structure":"Latin -itas","meaning":"quality of","meaningCN":"……的性质","example":"It forms the noun of the state.","exampleCN":"它构成表状态的名词。"},{"word":"illegality","structure":"illegal plus -ity","meaning":"unlawfulness","meaningCN":"非法性","example":"The noun names the state, and also one unlawful act.","exampleCN":"名词命名状态，也可指一桩违法行为。"}],"latinEntries":[{"word":"lex","structure":"lex, legis (f., third declension)","meaning":"law, statute","meaningCN":"法律；法令"},{"word":"legalis","structure":"legalis, legale (adj., third declension)","meaning":"of the law","meaningCN":"法律的"},{"word":"legalitas","structure":"legalitas, legalitatis (f., third declension)","meaning":"lawfulness","meaningCN":"合法性"},{"word":"illicitus","structure":"illicitus, illicita, illicitum (adj.)","meaning":"not permitted","meaningCN":"不被允许的"}],"derivatives":[{"word":"illegality","pos":"n.","zh":"非法性；违法行为"},{"word":"illegally","pos":"adv.","zh":"非法地"},{"word":"legal","pos":"adj.","zh":"合法的"},{"word":"legalise","pos":"v.","zh":"使合法化"}]}},{"word":"illegality","ipa_uk":"/ˌɪləˈɡæləti/","ipa_us":"/ˌɪləˈɡæləti/","definition_zh":"非法性；违法状态；（具体的）违法行为；不合法之处","definition_en":"the quality or state of being forbidden by law, or a particular unlawful act or feature that makes something legally invalid","core_image":"一份被涂改过的搜查令摊在法庭桌上，纸上的改动痕迹让整袋证据都不能再用了","scene":"辩方律师举起搜查令，指出上面的改动，主张取证方式本身已经违法。Defence counsel argued that the illegality of the search made every seized letter unusable.","sceneCN":"这里 illegality 指「取证行为违反法律这一事实」（第 5 个义项：作为审查理由的违法性）；句意为辩方主张搜查的违法性使所有被查获的信件都不能使用。图中可辨识物件：搜查令、涂改痕迹、证据袋、庭审桌。","pos":[{"tag":"n.","zh":"非法性；违法状态；违法行为；不合法之处"}],"collocations":[{"phrase":"the illegality of the search","zh":"搜查的违法性"},{"phrase":"alleged illegality","zh":"被指控的违法行为"},{"phrase":"evidence of illegality","zh":"违法行为的证据"},{"phrase":"challenge the illegality of","zh":"对……的违法性提出异议"},{"phrase":"gross illegality","zh":"严重违法"},{"phrase":"a finding of illegality","zh":"关于违法的认定"}],"forms":[{"label":"复数","form":"illegalities"},{"label":"形容词","form":"illegal"},{"label":"副词","form":"illegally"},{"label":"反义名词","form":"legality"}],"derivatives":[{"word":"illegal","pos":"adj.","zh":"非法的"},{"word":"illegally","pos":"adv.","zh":"非法地"},{"word":"legal","pos":"adj.","zh":"合法的"},{"word":"legality","pos":"n.","zh":"合法性"}],"senses":[{"no":"01","title":"The abstract property of being illegal","titleCN":"「非法」这一抽象性质","definition":"the abstract quality of being forbidden or not permitted by law","definitionCN":"被法律禁止或不被允许的抽象性质","example":"The report examined the illegality of the scheme rather than its cost.","exampleCN":"这份报告考察的是该方案的非法性，而不是它的成本。","why":"The noun joins illegal to the quality suffix -ity, so it names the property itself, the way darkness names the property of being dark.","whyCN":"这个名词把 illegal 与表性质的后缀结合，命名的是性质本身，正如 darkness 命名「暗」这一性质。"},{"no":"02","title":"One unlawful act","titleCN":"一桩具体的违法行为（可数）","definition":"a countable use for a specific illegal act or practice, often in the plural","definitionCN":"可数用法，指具体的违法作为或做法，常用复数","example":"The inquiry listed a dozen illegalities in the handling of the contracts.","exampleCN":"调查列出了合同处理过程中的十几处违法行为。","why":"A property noun turns countable once it points at instances: the abstract fault becomes a list of things done.","whyCN":"表性质的名词一旦指向具体事例就可数：抽象过失变成一串做过的事。"},{"no":"03","title":"The state of having no lawful status","titleCN":"身份或证件缺乏合法依据的状态","definition":"the condition of a person or business operating without the permission the law requires","definitionCN":"个人或机构在缺少法律所需许可的情况下运作的处境","example":"The charity helps families prove the illegality of their detention.","exampleCN":"该机构帮助一些家庭证明他们被拘留本身不合法。","why":"Here the noun describes a legal condition rather than an act, which is why it is usually used with verbs such as prove or establish.","whyCN":"这里名词描述一种法律状态而非行为，因此常与「证明」「认定」这类动词连用。"},{"no":"04","title":"Invalidity of a rule or decision","titleCN":"某项规则或决定在法律上无效的事实","definition":"the fact that a rule, order or appointment has no legal force because it was made outside the law","definitionCN":"规则、命令或任命因在法律之外作出而不具法律效力的事实","example":"The tribunal declared the illegality of the appointment and ordered a new vote.","exampleCN":"法庭宣布这项任命不合法，并下令重新投票。","why":"When the flaw is in the making rather than the doing, the noun names the defect that cancels the whole instrument.","whyCN":"当瑕疵出在「制定」而非「实施」环节时，名词命名的是使整份文书失效的那个缺陷。"},{"no":"05","title":"A ground for legal challenge","titleCN":"作为诉讼或审查理由的违法性","definition":"the defect that a party argues in court when asking a decision to be quashed","definitionCN":"当事人请求撤销某项决定时在法庭上主张的瑕疵","example":"Defence counsel argued that the illegality of the search made every seized letter unusable.","exampleCN":"辩方主张搜查的违法性使所有被查获的信件都不能使用。","why":"A defect becomes a legal weapon: the same noun that describes a fault also names the argument used against it.","whyCN":"瑕疵变成了法律武器：描述缺陷的名词，同时命名用来攻击它的那条理由。"},{"no":"06","title":"A foul under the rules of a game","titleCN":"比赛规则下的犯规","definition":"a breach of the rules of a sport, judged by an official rather than by a court","definitionCN":"违反运动规则的行为，由裁判而非法院判定","example":"The coach counted three illegalities in the final minute alone.","exampleCN":"教练单单在最后一分钟就数出三次犯规。","why":"Games borrow courtroom words for their own rule books, so illegality can mean a foul with no statute anywhere in sight.","whyCN":"比赛为自家的规则书借用法庭用语，因此「违法性」可以指一次犯规，而其间并无任何法令。"},{"no":"07","title":"Unlawfulness under international law","titleCN":"国际法意义上的不法性","definition":"the character of a state's action that breaches treaties, custom or charter obligations","definitionCN":"国家行为违反条约、习惯或宪章义务的性质","example":"The court weighed the illegality of the blockade against the claimed right of patrol.","exampleCN":"法庭权衡封锁的不法性与所主张的巡逻权。","why":"At that level there is no single legislature, so the standard shifts from statute to treaty and custom, while the noun keeps its shape.","whyCN":"在这一层面没有单一立法者，标准从法令转为条约与惯例，而名词的形状不变。"},{"no":"08","title":"The taint that excludes evidence","titleCN":"使证据被排除的违法瑕疵","definition":"the defect in how evidence was obtained, which can make it inadmissible","definitionCN":"取得证据的方式存在瑕疵，从而使其不可被采纳","example":"The judge ruled on the illegality of the seizure before hearing any testimony.","exampleCN":"法官在听取任何证词之前，先就扣押的违法性作出裁定。","why":"Procedure leaves a mark on the thing obtained, and the noun names that mark rather than the act of obtaining.","whyCN":"程序会在所得之物上留下痕迹，名词命名的是那道痕迹，而非取得行为本身。"}],"etymology":{"intro":{"en":"Illegality is illegal plus the quality suffix -ity, modelled on the older Latin pair legalis and legalitas. The English noun is recorded from the seventeenth century.","cn":"illegality 由 illegal 加表性质的后缀构成，仿照更早的拉丁成对词 legalis 与 legalitas。这个英语名词自十七世纪有书证。"},"items":[{"era":"LATIN LEX","en":"Lex, genitive legis, meant a statute. Latin kept ius for right, so a word of legality never carried the sense of justice.","cn":"lex（属格 legis）意为法令。拉丁语另用 ius 表权利，因此表示合法性的词从不携带正义之义。"},{"era":"UNCERTAIN ROOT","en":"Source uncertain (root of lex): derivation from legere 'to read, gather' is suggested but unproven, and a root meaning 'to lay down' is also argued.","cn":"来源不确定（lex 的词根）：出自 legere「读、收集」的说法被提出但未获证明；也有从表示「立下」的词根派生之说。"},{"era":"NEGATED ADJECTIVE","en":"Latin in- 'not', assimilated to il- before l, produced the adjective illegalis in later usage and the English illegal in the seventeenth century.","cn":"拉丁语的否定成分「不」在 l 前发生同化，在后世用法中构成形容词，并在十七世纪形成英语 illegal。"},{"era":"LEGALITAS AS MODEL","en":"Medieval Latin legalitas named lawfulness as a property; English copied that pattern with -ity to make the negative noun.","cn":"中世纪拉丁 legalitas 命名作为性质的合法状态；英语仿此模式加表性质后缀，造出否定的名词。"},{"era":"SEVENTEENTH-CENTURY NOUN","en":"Illegality appears in English legal and political writing in the seventeenth century, first for the property and soon after for particular unlawful acts.","cn":"illegality 在十七世纪的英语法律与政治写作中出现，先指性质，随后很快指具体的违法行为。"},{"era":"APPROXIMATE DATES","en":"The earliest citation is approximate: the seventeenth-century date is a general period, and the plural use for listed acts is later still.","cn":"最早书证为约数：十七世纪只是一个大致时段，而用复数指列举的违法行为还要更晚。"}]},"similar":{"note":{"en":"The first group is the same family, where one letter changes the meaning; the second group names related defects and offences.","cn":"第一组是同一词族，只差一个前缀却意义相反；第二组是相关的瑕疵与违法行为。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"illegal","ipa":"/ɪˈliːɡl/","tag":"same family","definition":"The adjective describing an act, object or person as forbidden by law.","definitionCN":"形容词，描述行为、物品或人被法律禁止。"},{"word":"illegally","ipa":"/ɪˈliːɡəli/","tag":"same family","definition":"The adverb describing how something was done, not the fault itself.","definitionCN":"副词，描述某事如何被做，而非瑕疵本身。"},{"word":"legality","ipa":"/liˈɡæləti/","tag":"same family, opposite","definition":"The positive property: conformity to law, or the question of whether an act fits.","definitionCN":"正面性质：与法律相符，或某行为是否符合法律的问题。"},{"word":"legal","ipa":"/ˈliːɡl/","tag":"same family","definition":"The positive adjective from which the whole negative series is built.","definitionCN":"正面形容词，整个否定序列都由它构造。"},{"word":"legislative","ipa":"/ˈleɡɪslətɪv/","tag":"same root, other branch","definition":"Concerned with making statutes rather than with breaking them.","definitionCN":"与制定法令有关，而非与违反法令有关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"unlawfulness","ipa":"/ʌnˈlɔːflnəs/","tag":"plain doublet","definition":"The everyday synonym using the native noun law; it is commoner in statutes than illegality in speech.","definitionCN":"用本族词 law 构成的日常同义词，在法令中比非法性更常见。"},{"word":"criminality","ipa":"/ˌkrɪmɪˈnæləti/","tag":"crime only","definition":"The quality of being criminal, a narrower band than illegality because regulatory breaches are excluded.","definitionCN":"构成犯罪的性质，范围比非法性窄，因为行政违规不计入。"},{"word":"invalidity","ipa":"/ˌɪnvəˈlɪdəti/","tag":"effect, not rule-breaking","definition":"Lack of legal force in a document or act, which may follow from illegality or from a purely formal defect.","definitionCN":"文书或行为缺乏法律效力，可能源于违法，也可能只是形式瑕疵。"},{"word":"infraction","ipa":"/ɪnˈfrækʃn/","tag":"countable breach","definition":"A single breach of a rule or law, the countable counterpart of the abstract noun.","definitionCN":"对规则或法律的一次违反，是抽象名词的可数对应词。"},{"word":"violation","ipa":"/ˌvaɪəˈleɪʃn/","tag":"breach, wider","definition":"A breaking of a law, right or agreement, used far beyond the criminal sphere.","definitionCN":"对法律、权利或约定的违反，使用范围远超刑事领域。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real prefix, the real root and real fixed phrases.","cn":"正常联想使用真实的否定前缀、真实词根与真实固定搭配。"},"normal":[{"en":"The word is 'not legal' plus the quality ending, so it names the state of being outside the law.","cn":"这个词就是「不合法」加表性质的词尾，命名处于法律之外的状态。"},{"en":"The family runs legal, illegal, illegally, illegality and legalise.","cn":"同族词有 legal、illegal、illegally、illegality 与 legalise。"},{"en":"Fixed phrases mark the courtroom sense: alleged illegality, a finding of illegality, challenge the illegality of.","cn":"固定搭配标出法庭义：被指控的违法行为、关于违法的认定、对……的违法性提出异议。"},{"en":"The plural illegalities is used for a list of unlawful acts, a common pattern for property nouns.","cn":"复数形式用于列举多起违法行为，这是表性质名词的常见转用。"},{"en":"Latin kept ius for right, so this noun never means injustice; it means non-conformity to statute.","cn":"拉丁语另用 ius 表权利，因此这个名词从不表示不义，而表示与法令不符。"}],"abstract":[{"en":"Picture a forged seal that looks perfect until the paper beneath it is lifted.","cn":"想象一枚伪造的印章，看着完美，直到揭开下面的纸。"},{"en":"Picture a chain of custody with one link cut, so the whole chain is laid aside.","cn":"想象一条证据保管链断了一环，整条链便被搁置。"},{"en":"Picture a referee's whistle that ends a move already half completed.","cn":"想象一声哨响，叫停一个已经做了一半的动作。"}]},"examples":[{"en":"The auditor documented the illegality of the payments.","cn":"审计人员记录下了这些付款的违法之处。"},{"en":"A single illegality can void an entire procurement process.","cn":"一处违法就能使整个采购程序失效。"},{"en":"The appeal rested on the illegality of the detention, not on its length.","cn":"上诉依据的是拘留本身不合法，而非其时长。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「il（不）+ legal（合法）+ ity（性质）」——不合法的性质 → 非法性","word":"illegality"},"root":"拉丁语的否定成分（在 l 前同化）+ legalis「法律的」（出自 lex「法令」，更深词根存疑）；英语 illegal 加表示性质的后缀构成 illegality。","sensesIntro":{"en":"Eight senses follow one altered document: its flaw is described as a property, counted as an act, used to prove a status, used to cancel an appointment, raised as a ground, called a foul, weighed between states, and finally used to exclude evidence.","cn":"八个义项围绕一份被改动的文书：它的瑕疵先被描述为性质，再被数成行为，用来证明身份，用来取消任命，被当作理由提出，被叫作犯规，在国家之间被权衡，最后用来排除证据。"},"semanticMap":{"core":{"en":"CORE IMAGE: a document whose alteration taints everything it was used to obtain.","cn":"核心意象：一份被改动的文书，把用它取得的一切都染上了瑕疵。"},"chain":["THE TAINT","COUNTED ACTS","STATUS","VOID INSTRUMENT","GROUND OF CHALLENGE","EXCLUDED PROOF"],"branches":[{"senses":"01 · 02","en":"PROPERTY AND INSTANCES: one abstract taint and a list of concrete acts are the same noun at two counts.","cn":"性质与实例：一个抽象瑕疵与一串具体行为，是同一个名词的两种计数。"},{"senses":"03 · 04","en":"STATUS AND INSTRUMENT: a person without permission and a decision without force are two faces of the same defect.","cn":"身份与文书：无许可的人与无效力的决定，是同一缺陷的两副面孔。"},{"senses":"05 · 08","en":"THE ARGUMENT AND ITS EFFECT: the taint is raised in court and then decides what may be used.","cn":"理由与后果：瑕疵在法庭上被提出，随后决定什么可以使用。"},{"senses":"06","en":"ANOTHER RULE BOOK: a whistle replaces a judgment, but the noun stays.","cn":"另一本规则书：哨声取代判决，名词却不变。"},{"senses":"07","en":"THE WIDER STAGE: without a world statute book, the same noun is measured against treaties instead.","cn":"更大的舞台：没有世界法令全书，同一个名词改以条约为尺。"}]},"affixes":{"intro":{"en":"Illegality stacks a negative prefix, a law root and a quality suffix, and each layer is productive on its own.","cn":"illegality 叠了否定前缀、法律词根与表性质后缀，每一层都能独立构词。"},"latinIntro":{"en":"Latin lex and legalis give legal, legality and legislate; the prefix in-, assimilated to il-, negates them; -ity forms property nouns.","cn":"拉丁 lex 与 legalis 给出 legal、legality 与 legislate；否定前缀在 l 前同化后否定这些词；表示性质的后缀构成性质名词。"},"items":[{"word":"il-","structure":"in- assimilated before l (Latin prefix)","meaning":"not","meaningCN":"不","example":"It reverses the meaning.","exampleCN":"它反转词义。"},{"word":"leg-","structure":"lex, legis (Latin noun)","meaning":"law; statute","meaningCN":"法律；法令","example":"The root supplies the rule.","exampleCN":"词根提供规则。"},{"word":"-al","structure":"Latin -alis","meaning":"relating to","meaningCN":"与……相关的","example":"It builds the adjective.","exampleCN":"它构成形容词。"},{"word":"legal","structure":"leg- plus -al","meaning":"of the law","meaningCN":"法律的","example":"The positive base.","exampleCN":"正面基础词。"},{"word":"illegal","structure":"il- plus legal","meaning":"forbidden by law","meaningCN":"非法的","example":"The negated adjective.","exampleCN":"被否定的形容词。"},{"word":"-ly","structure":"Old English -lice","meaning":"in the manner of","meaningCN":"以……方式","example":"It builds the adverb.","exampleCN":"它构成副词。"},{"word":"-ity","structure":"Latin -itas","meaning":"quality of","meaningCN":"……的性质","example":"It builds the property noun.","exampleCN":"它构成性质名词。"},{"word":"illegality","structure":"illegal plus -ity","meaning":"unlawfulness","meaningCN":"非法性","example":"The noun names the state.","exampleCN":"名词命名状态。"},{"word":"legalitas","structure":"legalis plus -itas","meaning":"lawfulness (medieval)","meaningCN":"合法性（中世纪）","example":"The Latin model for the pair.","exampleCN":"这一对词的拉丁范本。"},{"word":"in-","structure":"Latin prefix","meaning":"not","meaningCN":"不","example":"It also negates adjectives such as valid.","exampleCN":"它也否定 valid 这类形容词。"}],"latinEntries":[{"word":"lex","structure":"lex, legis (f., third declension)","meaning":"law, statute","meaningCN":"法律；法令"},{"word":"legalis","structure":"legalis, legale (adj., third declension)","meaning":"of the law","meaningCN":"法律的"},{"word":"legalitas","structure":"legalitas, legalitatis (f., third declension)","meaning":"lawfulness","meaningCN":"合法性"},{"word":"illicitus","structure":"illicitus, illicita, illicitum (adj.)","meaning":"not permitted","meaningCN":"不被允许的"}],"derivatives":[{"word":"illegal","pos":"adj.","zh":"非法的"},{"word":"illegally","pos":"adv.","zh":"非法地"},{"word":"legal","pos":"adj.","zh":"合法的"},{"word":"legality","pos":"n.","zh":"合法性"}]}},{"word":"regulator","ipa_uk":"/ˈreɡjuleɪtə/","ipa_us":"/ˈreɡjuleɪtər/","definition_zh":"监管机构；监管人员；调节装置；调速器；（生物或生态中的）调节因子","definition_en":"an official body or person that supervises an activity according to rules, or a device that keeps flow, pressure, temperature or speed within limits","core_image":"一只铜制阀门被拧到某个刻度，指针停在红线上，下游的水流从此不多不少","scene":"能源监管机构把电力公司的费率申请退回，要求重新核算。The energy regulator sent the rate request back for a second review.","sceneCN":"这里 regulator 指「负责按规则监督某一行业的官方机构」（第 1 个义项：行业监管机构）；句意为能源监管机构把费率申请退回，要求重新核算。图中可辨识物件：退回的申请表、机构公章、费率表、办公桌。","pos":[{"tag":"n.","zh":"监管机构；监管者；调节器；调速装置"}],"collocations":[{"phrase":"the energy regulator","zh":"能源监管机构"},{"phrase":"an independent regulator","zh":"独立监管机构"},{"phrase":"financial regulator","zh":"金融监管机构"},{"phrase":"pressure regulator","zh":"压力调节器"},{"phrase":"voltage regulator","zh":"稳压器"},{"phrase":"the industry regulator","zh":"行业监管机构"}],"forms":[{"label":"复数","form":"regulators"},{"label":"动词","form":"regulate"},{"label":"名词（规则、管制）","form":"regulation"},{"label":"形容词","form":"regulatory"},{"label":"形容词（受管的）","form":"regulated"}],"derivatives":[{"word":"regulate","pos":"v.","zh":"管理；调节；控制"},{"word":"regulation","pos":"n.","zh":"规章；管制；调节"},{"word":"regulatory","pos":"adj.","zh":"监管的；规章性的"},{"word":"deregulation","pos":"n.","zh":"放松管制"},{"word":"regulative","pos":"adj.","zh":"起调节作用的"}],"senses":[{"no":"01","title":"An official supervisory body","titleCN":"负责按规则监督某一行业的官方机构","definition":"an official body with legal power to supervise an industry and enforce its rules","definitionCN":"拥有法定权力监督某一行业并执行规则的官方机构","example":"The energy regulator sent the rate request back for a second review.","exampleCN":"能源监管机构把费率申请退回，要求重新核算。","why":"The word is the doer of regulare 'to direct by rule', itself from regula 'a straight stick used as a rule', so the body is pictured holding the measuring rod over an industry.","whyCN":"这个词是 regulare「按规则引导」的施动者，而后者出自 regula「作尺用的直杆」，因此这个机构被想象成在行业上方握着量尺。"},{"no":"02","title":"A person who supervises","titleCN":"执行监督的个人","definition":"an individual official whose job is to check that rules are being followed","definitionCN":"职务上负责核查规则是否被遵守的官员","example":"A regulator visited the plant unannounced and asked for the maintenance log.","exampleCN":"一位监管人员突击到厂，要求出示维修记录。","why":"The doer suffix does not care whether the doer is a person or an office, so the same noun covers both scales.","whyCN":"施动后缀并不区分施动者是人还是机构，因此同一个名词覆盖两种尺度。"},{"no":"03","title":"A flow or pressure device","titleCN":"控制流量或压力的装置","definition":"a device that holds the flow of gas or liquid at a steady level","definitionCN":"把气体或液体的流量维持在稳定水平的装置","example":"A regulator on the main pipe keeps the pressure below the danger mark.","exampleCN":"主管上的调节器把压力控制在危险刻度之下。","why":"The mechanical sense is the same gesture made of brass: instead of a person checking a rule, a valve holds a quantity to a set point.","whyCN":"机械义是同一个动作换成黄铜来做：不再是人在核对规则，而是阀门把某个量守在设定点上。"},{"no":"04","title":"A temperature or voltage control","titleCN":"温度或电压的自动控制部件","definition":"a component that automatically adjusts heat or electric potential to a chosen value","definitionCN":"把热量或电压自动调整到选定值的部件","example":"The voltage regulator failed, and the whole rack went dark.","exampleCN":"稳压器失灵，整排机柜都黑了。","why":"Electricity and heat are invisible flows, so the device is named by what it does rather than by what it looks like.","whyCN":"电与热是看不见的流，因此这类装置按它做的事命名，而不是按它的形状命名。"},{"no":"05","title":"The timing part of a clock","titleCN":"钟表里的调速机构","definition":"the part of a watch or clock that governs the rate at which it runs","definitionCN":"钟表中控制走时快慢的部件","example":"A watchmaker cleaned the regulator and the drift stopped.","exampleCN":"钟表匠清洗了调速机构，走时偏移就停止了。","why":"A clock is regulated by making its beat even, so the part that sets the beat carries the name by direct transfer.","whyCN":"钟表靠让摆动均匀来校准，因此定住摆速的部件直接承接了这个名称。"},{"no":"06","title":"A controlling factor in biology","titleCN":"生物学中的调控因子","definition":"a gene, protein or molecule that controls the activity of another biological process","definitionCN":"控制另一生物过程活动的基因、蛋白或分子","example":"Researchers treated the protein as a regulator of cell division.","exampleCN":"研究者把这个蛋白看作细胞分裂的调节因子。","why":"Biology borrowed the mechanical image: something small holds a larger process at a steady rate, as a valve holds a flow.","whyCN":"生物学借用了机械的画面：某种小东西把更大的过程守在稳定速率上，正如阀门守着一股流。"},{"no":"07","title":"A marshal of traffic or a crowd","titleCN":"交通或现场的秩序指挥者","definition":"a person who directs the movement of traffic, vehicles or a crowd at a particular place","definitionCN":"在特定地点指挥车辆或人群移动的人","example":"A regulator waved the coaches into the second lane.","exampleCN":"一名交通指挥把大巴引到第二条车道。","why":"Where there is no automatic system, a person with a signal does the same work as the valve, and the older occupational sense survives.","whyCN":"在没有自动系统的地方，拿着信号旗的人做着与阀门相同的工作，这一较早的职业义因此留存。"},{"no":"08","title":"A balancing factor in an ecosystem","titleCN":"生态系统中起调节作用的因素","definition":"a species or process that keeps another population within bounds","definitionCN":"把另一种群数量控制在界限内的物种或过程","example":"The wolves acted as a regulator of the deer herd.","exampleCN":"狼群起了调节鹿群数量的作用。","why":"Ecology extends the metaphor to food webs, where a predator plays the part the brass valve plays in a pipe.","whyCN":"生态学把这个比喻扩展到食物网：捕食者扮演的角色，正如铜阀在管道中的角色。"}],"etymology":{"intro":{"en":"Regulator is the doer noun of Latin regulare 'to direct, control', from regula 'rule, measuring rod', from regere 'to guide straight'. The English word covers both officials and devices.","cn":"regulator 是拉丁 regulare「引导、控制」的施动名词，而 regulare 出自 regula「规则、量尺」，再上溯到 regere「使笔直地引导」。英语这个词既指官员，也指装置。"},"items":[{"era":"LATIN REGERE","en":"Regere meant to guide or keep straight, and the picture behind it is a line drawn without wavering; it is also the source of rex 'king' and regio 'region'.","cn":"regere 意为引导、使保持笔直，其背后的画面是一条不偏不倚画出的线；它也是 rex「王」与 regio「地区」的来源。"},{"era":"LATIN REGULA","en":"Regula was a straight stick used to check a line, hence a rule or standard; the physical rod and the abstract rule are one word.","cn":"regula 是检查直线用的直杆，因此兼指规则与标准；具体的杆与抽象的规，在拉丁语里是同一个词。"},{"era":"LATIN REGULARE","en":"Regulare meant to measure by the rod, then to direct or control; the doer form regulator named the one who does the directing.","cn":"regulare 意为用直杆量，进而指引导与控制；其施动形式命名做引导的那一方。"},{"era":"MEDIEVAL AND LEGAL USE","en":"Medieval and early modern usage applied the person noun to officers who enforced standards, which is the root of the modern supervisory sense.","cn":"中世纪与近代早期把这个人称名词用于执行标准的官员，这正是现代监管义的根源。"},{"era":"MECHANICAL SENSE","en":"From the eighteenth century the same noun was given to devices that hold a flow steady, as clockwork and steam engineering developed.","cn":"自十八世纪起，随着钟表机械与蒸汽工程的发展，同一个名词被赋予把流量守稳的装置。"},{"era":"APPROXIMATE DATES","en":"The first date for the device sense is approximate: it appears during the industrial period, but the exact earliest citation varies by machine type.","cn":"装置义的最早年代为约数：它出现在工业时期，但确切的最早书证因机器种类而异。"}]},"similar":{"note":{"en":"The first group is the same Latin family and differs only in grammatical job; the second group names other kinds of supervision and control.","cn":"第一组是同出拉丁词族，差别只在语法职能；第二组是其他监督与控制方式。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"regulate","ipa":"/ˈreɡjuleɪt/","tag":"same family","definition":"The verb: to control by rule or hold a quantity steady.","definitionCN":"动词：按规则控制，或把某个量守稳。"},{"word":"regulation","ipa":"/ˌreɡjuˈleɪʃn/","tag":"same family","definition":"The noun of the act or the rule itself, not the one who applies it.","definitionCN":"指行为或规则本身的名词，而非执行者。"},{"word":"regulatory","ipa":"/ˈreɡjulətəri/","tag":"same family","definition":"The adjective describing the body, framework or style of supervision.","definitionCN":"描述监管机构、框架或风格的形容词。"},{"word":"regular","ipa":"/ˈreɡjulə/","tag":"same root, other branch","definition":"From regula but meaning even, habitual or according to pattern, with no power to enforce.","definitionCN":"同出 regula，却指匀整、惯常或合乎式样，不含强制力。"},{"word":"rule","ipa":"/ruːl/","tag":"same root, native form","definition":"The Anglo-French descendant of regula; it names the standard or the act of governing, not the officer.","definitionCN":"regula 经英法语的本地形式；它命名标准或治理行为，而非官员。"}]},{"heading":"NEAR MEANING","entries":[{"word":"watchdog","ipa":"/ˈwɒtʃdɒɡ/","tag":"informal register","definition":"A colourful name for a body that guards the public interest, commoner in journalism than in statutes.","definitionCN":"对守护公共利益机构的形象化称呼，多见于新闻而非法令。"},{"word":"supervisor","ipa":"/suːpəˈvaɪzə/","tag":"hierarchical oversight","definition":"Someone who oversees staff inside an organisation, with authority over people rather than over a market.","definitionCN":"在组织内部监督员工的人，权限针对人，而非针对市场。"},{"word":"controller","ipa":"/kənˈtrəʊlə/","tag":"device or officer","definition":"A governor or a device that keeps a value fixed, or a senior finance officer; the sense depends on context.","definitionCN":"指把某个值固定的装置或主管，也可指高级财务官；词义随语境而定。"},{"word":"governor","ipa":"/ˈɡʌvənə/","tag":"mechanical doublet","definition":"In engineering, a device that limits speed, especially in an engine; also an institutional official.","definitionCN":"工程上指限制转速的装置，尤用于发动机；也指机构长官。"},{"word":"thermostat","ipa":"/ˈθɜːməstæt/","tag":"one specific device","definition":"A device that switches heating on and off at set temperatures, a narrower term than regulator.","definitionCN":"按设定温度开关供暖的装置，比调节器更具体。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin rod, the real family and real fixed phrases.","cn":"正常联想使用真实的拉丁「量尺」词、真实的同族词与真实固定搭配。"},"normal":[{"en":"Regula is a straight rod used to test a line, so a regulator is whoever or whatever holds things to the line.","cn":"regula 是检验直线用的直杆，因此 regulator 就是把事物守在那条线上的角色，人或物皆可。"},{"en":"The family runs regulate, regulation, regulatory, regulator and deregulation.","cn":"同族词有 regulate、regulation、regulatory、regulator 与 deregulation。"},{"en":"Fixed phrases mark the official sense: the energy regulator, an independent regulator, the industry regulator.","cn":"固定搭配标出官方义：能源监管机构、独立监管机构、行业监管机构。"},{"en":"The same root gives rule, regular and region, all from the idea of a straight line.","cn":"同一词根还给出 rule、regular 与 region，都出自「直线」这一观念。"},{"en":"A brass valve and a government office share the noun because both keep a quantity at a set point.","cn":"黄铜阀门与政府机关共用这个名词，因为两者都把某个量守在设定点上。"}],"abstract":[{"en":"Picture a hand turning a valve until the needle rests exactly on the red line.","cn":"想象一只手拧动阀门，直到指针正好停在红线上。"},{"en":"Picture a surveyor's rod laid along a wall to see whether the wall leans.","cn":"想象一根测量杆贴在墙边，用来查看墙是否倾斜。"},{"en":"Picture a referee with a whistle standing where two roads merge, deciding who goes first.","cn":"想象一名吹哨的裁判站在两条路汇合处，决定谁先走。"}]},"examples":[{"en":"The regulator fined the bank for mis-selling loans.","cn":"监管机构因不当销售贷款对该银行处以罚款。"},{"en":"Fit a regulator between the cylinder and the hose.","cn":"在气瓶与软管之间装一个调节器。"},{"en":"Independent regulators are meant to be insulated from politics.","cn":"独立监管机构本应不受政治干预。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「regul（规则）+ ator（做的人或物）」——按规则管住的那个 → 监管者、调节器","word":"regulator"},"root":"拉丁 regula「规则、量尺」→ regulare「按尺衡量、控制」→ 施动名词 regulator「执行者、调节装置」；regula 出自 regere「使笔直地引导」。","sensesIntro":{"en":"Eight senses follow one measuring rod: it is held by an agency, then by an inspector, then built into a pipe, into a circuit, into a watch, into a cell, into a traffic lane and finally into a food web.","cn":"八个义项围绕一根量尺：它先由机构握着，再由稽查员握着，然后被装进管道、电路、钟表、细胞、车道，最后装进食物网。"},"semanticMap":{"core":{"en":"CORE IMAGE: a rod held over a moving thing to see whether it stays on the line.","cn":"核心意象：一根杆子守在一件运动之物上方，看它是否留在线上。"},"chain":["THE ROD","THE OFFICE","FLOW AND PRESSURE","CURRENT AND HEAT","THE BEAT","THE CELL AND THE WEB"],"branches":[{"senses":"01 · 02","en":"BODY AND PERSON: an agency and its inspector hold the same rod at two sizes.","cn":"机构与人：一个机关与其稽查员，在同一根杆子的两种尺寸上。"},{"senses":"03 · 04","en":"PIPE AND CIRCUIT: gas and electricity are invisible flows, and both are held by a fitting.","cn":"管道与电路：气与电都是看不见的流，都由一个管件守住。"},{"senses":"05","en":"THE BEAT: a clock is regulated by making its swing even, so the part that sets the beat takes the name.","cn":"摆速：钟表靠让摆动均匀来校准，定住摆速的部件因此承接了这个名称。"},{"senses":"06","en":"THE CELL: a small molecule holds a large process steady, as a valve holds a flow.","cn":"细胞：一个分子把一个大过程守住，正如阀门守住一股流。"},{"senses":"07 · 08","en":"LANE AND WEB: a marshal and a predator each keep movement inside bounds.","cn":"车道与食物网：交通指挥与捕食者各自把运动守在界限内。"}]},"affixes":{"intro":{"en":"Regulator is a Latin rod, a verb ending and a doer suffix in a row, and all three recur in English.","cn":"regulator 依次是拉丁「杆」、动词词尾与施动后缀，三者都在英语里反复出现。"},"latinIntro":{"en":"Latin regula gives rule, regular and regulate; the doer suffix -or gives supervisor, inspector and regulator.","cn":"拉丁 regula 给出 rule、regular 与 regulate；施动后缀给出 supervisor、inspector 与 regulator。"},"items":[{"word":"reg-","structure":"regere (Latin verb, 'to guide straight')","meaning":"to rule, guide","meaningCN":"引导；统治","example":"The root supplies the straight line.","exampleCN":"词根提供那条直线。"},{"word":"-ula","structure":"Latin diminutive and instrument ending","meaning":"small thing used for","meaningCN":"作……用的小物","example":"It forms the measuring rod.","exampleCN":"它构成量尺。"},{"word":"regula","structure":"reg- plus -ula","meaning":"rule; measuring rod","meaningCN":"规则；量尺","example":"The rod and the rule are one word.","exampleCN":"杆与规是同一个词。"},{"word":"-are","structure":"Latin first conjugation ending","meaning":"to do","meaningCN":"做……","example":"It forms the verb from the noun.","exampleCN":"它由名词构成动词。"},{"word":"regulate","structure":"regula plus -are","meaning":"to measure, direct","meaningCN":"量、控制","example":"The verb covers both checking and steering.","exampleCN":"动词兼指核对与驾驭。"},{"word":"-or","structure":"Latin agent suffix","meaning":"one who does","meaningCN":"做……者","example":"It forms the doer noun.","exampleCN":"它构成施动名词。"},{"word":"regulator","structure":"regulate plus -or","meaning":"one who directs; a device","meaningCN":"执行者；调节装置","example":"The same suffix serves persons and things.","exampleCN":"同一后缀兼指人与物。"},{"word":"regulation","structure":"regulate plus -ion","meaning":"the act or the rule","meaningCN":"行为或规章","example":"The noun can mean the deed or the standard.","exampleCN":"名词可指行为，也可指标准。"},{"word":"regulatory","structure":"regulator plus -y","meaning":"relating to supervision","meaningCN":"监管的","example":"It describes the frame, not the body.","exampleCN":"它描述框架，而非机构。"},{"word":"de-","structure":"Latin de- 'away from'","meaning":"removal","meaningCN":"去除","example":"It forms deregulation.","exampleCN":"它构成「放松管制」。"}],"latinEntries":[{"word":"regula","structure":"regula, regulae (f., first declension)","meaning":"rule, measuring rod","meaningCN":"规则；量尺"},{"word":"regere","structure":"regere, rexi, rectum (verb, third conjugation)","meaning":"to guide straight, rule","meaningCN":"使笔直引导；统治"},{"word":"regulare","structure":"regulare, regulavi, regulatum (verb, first conjugation)","meaning":"to measure, control","meaningCN":"衡量；控制"},{"word":"regulator","structure":"regulator, regulatoris (m., third declension)","meaning":"one who directs","meaningCN":"引导者；管理者"}],"derivatives":[{"word":"regulate","pos":"v.","zh":"管理；调节"},{"word":"regulation","pos":"n.","zh":"规章；管制"},{"word":"regulatory","pos":"adj.","zh":"监管的"},{"word":"deregulation","pos":"n.","zh":"放松管制"},{"word":"regulative","pos":"adj.","zh":"起调节作用的"}]}},{"word":"rule","ipa_uk":"/ruːl/","ipa_us":"/ruːl/","definition_zh":"规则；规定；统治；裁定；尺子；用尺画线；统治、支配","definition_en":"a statement of what must or must not be done, the power to govern, an official decision, or a straight strip for measuring; as a verb, to govern, decide or draw a line","core_image":"一把木尺压住纸边，铅笔画出一条不抖的直线，随后这条线变成了所有人必须遵守的界线","scene":"裁判把哨子含在嘴里，指向罚球点，因为那名后卫违反了刚刚被重申的一条规则。The referee pointed to the penalty spot because the defender had broken a rule the teams had just been reminded of.","sceneCN":"这里 rule 指「比赛中必须遵守的条款」（第 1 个义项：行为规则）；句意为裁判指向罚球点，因为那名后卫违反了刚刚被重申的规则。图中可辨识物件：哨子、罚球点、边线、裁判旗。","pos":[{"tag":"n.","zh":"规则；规定；统治；裁定；尺子"},{"tag":"v.","zh":"统治；支配；裁定；用尺画线"}],"collocations":[{"phrase":"break a rule","zh":"违反规则"},{"phrase":"follow the rules","zh":"遵守规则"},{"phrase":"as a rule","zh":"通常；一般说来"},{"phrase":"the rule of law","zh":"法治"},{"phrase":"rule out","zh":"排除；不予考虑"},{"phrase":"work to rule","zh":"按章工作（消极怠工）"}],"forms":[{"label":"三单（he/she/it）","form":"rules"},{"label":"过去式","form":"ruled"},{"label":"过去分词","form":"ruled"},{"label":"现在分词","form":"ruling"},{"label":"复数（名词）","form":"rules"},{"label":"施动者名词","form":"ruler"}],"derivatives":[{"word":"ruler","pos":"n.","zh":"统治者；尺子"},{"word":"ruling","pos":"n./adj.","zh":"裁决 / 执政的"},{"word":"ruled","pos":"adj.","zh":"被划线的；受统治的"},{"word":"unruly","pos":"adj.","zh":"难以管束的"},{"word":"overrule","pos":"v.","zh":"驳回；否决"}],"senses":[{"no":"01","title":"A regulation that must be obeyed","titleCN":"必须遵守的规定","definition":"a statement or instruction that says what people must or must not do","definitionCN":"说明人们必须做或不得做什么的条款或指示","example":"The referee pointed to the penalty spot because the defender had broken a rule the teams had just been reminded of.","exampleCN":"裁判指向罚球点，因为那名后卫违反了刚刚被重申的规则。","why":"Rule comes from regula, a straight rod used to test a line: a rule is first a standard laid beside conduct to see whether conduct is straight.","whyCN":"rule 出自 regula，即用来检验直线的直杆：规则首先是一根贴到行为旁边、看行为是否笔直的标准。"},{"no":"02","title":"The usual way things happen","titleCN":"通常的情形，惯常做法","definition":"the ordinary or expected pattern, as in the fixed phrase as a rule","definitionCN":"通常或预期的模式，见于固定说法「一般说来」","example":"As a rule, the office empties by six on Fridays.","exampleCN":"一般说来，办公室在周五六点前就空了。","why":"What usually happens becomes a norm of expectation, and English uses the same noun for a stated regulation and for a statistical habit.","whyCN":"常发生的事会变成预期的常态，英语于是用同一个名词既指明文规定，也指统计意义上的习惯。"},{"no":"03","title":"The power to govern","titleCN":"统治权，执政","definition":"the exercise of authority over a country or people, often by one person or one party","definitionCN":"对一国或一群人行使权威，常由一人或一党行使","example":"The colony spent forty years under direct rule from the capital.","exampleCN":"这块殖民地有四十年直接受首都统治。","why":"The measuring rod becomes the sceptre: whoever holds the standard also holds the power to enforce it, and that power takes the same noun.","whyCN":"量尺变成了权杖：握着标准的人同时握着执行它的权力，而这份权力用了同一个名词。"},{"no":"04","title":"To govern a place","titleCN":"统治、治理（动词）","definition":"to govern a country or group, or to control how something develops","definitionCN":"统治一个国家或群体，或控制某事的发展","example":"The council ruled the valley for three generations.","exampleCN":"这个议事会治理山谷达三代之久。","why":"The verb is the noun turned into action: holding the rod over a place is what governing means in the older picture.","whyCN":"动词是把名词转成动作：在某个地方上方握着尺，就是较早画面里的「治理」。"},{"no":"05","title":"To decide as an authority","titleCN":"由权威作出裁定（动词）","definition":"to make an official decision, especially a judge or a court","definitionCN":"作出正式决定，尤指法官或法院","example":"The judge ruled that the contract had never been valid.","exampleCN":"法官裁定这份合同从未有效。","why":"A decision becomes final when an authority lays the standard down for the case, so ruling is the act of applying the rod to one dispute.","whyCN":"当权威为该案定下标准时，决定便成为最终；因此「裁定」就是把尺子落到一桩争议上的动作。"},{"no":"06","title":"A straight measuring strip","titleCN":"量直线用的尺","definition":"a flat strip with marks, used to measure or to guide a line","definitionCN":"带刻度的扁平条，用来量长度或引直线","example":"He kept a folding rule in the top pocket of his overalls.","exampleCN":"他在工装上衣口袋里放着一把折尺。","why":"This is the oldest physical sense: the Latin rod itself, still sold in hardware shops under the same name.","whyCN":"这是最古老的实物义：拉丁语那根杆本身，至今仍在五金店里以同一个名字出售。"},{"no":"07","title":"To draw a line with a ruler","titleCN":"用尺画线（动词）","definition":"to draw a straight line using a strip as a guide","definitionCN":"借助直条引出一条直线","example":"Rule a line under the total before you sign it.","exampleCN":"签字之前，在总额下面画一条线。","why":"The verb derives from the tool, not from the regulation: pressing a rod to paper and pulling the pencil along is the literal act.","whyCN":"这个动词出自工具而非规定：把杆压在纸上、拉着铅笔画过去，就是字面上的动作。"},{"no":"08","title":"A clause in a formal system","titleCN":"形式系统内部的规则（语法、棋类等）","definition":"one of the fixed clauses that define how a game, language or logic works","definitionCN":"界定游戏、语言或逻辑如何运作的固定条款","example":"The grammar rule looks simple until you meet an irregular verb.","exampleCN":"这条语法规则看着简单，直到你遇到不规则动词。","why":"Formal systems are written as sets of clauses, so the general noun is reused for games, grammar and mathematics without any change of shape.","whyCN":"形式系统被写成一组条款，于是这个一般名词被原封不动地用于游戏、语法与数学。"},{"no":"09","title":"To dominate someone's feeling","titleCN":"支配某人的情绪（动词，抽象）","definition":"to control or dominate a person's feeling or behaviour, as fear or habit does","definitionCN":"像恐惧或习惯那样控制、支配一个人的情绪或行为","example":"He let pride rule his judgment and lost the case.","exampleCN":"他让自尊支配了判断，输掉了这场案子。","why":"The abstract sense drops the territory and keeps the sway: what governs a person need not be a government, only something that holds the reins.","whyCN":"抽象义舍去领土而保留支配：支配一个人的不必是政府，只要握着缰绳即可。"}],"etymology":{"intro":{"en":"Rule comes through Old French from Latin regula 'straight rod, standard', from regere 'to guide straight'. The noun is older in English than the verb, and the measuring sense is the original one.","cn":"rule 经古法语来自拉丁 regula「直杆、标准」，后者出自 regere「使笔直地引导」。名词在英语中早于动词，量尺义是最初的义。"},"items":[{"era":"LATIN REGERE","en":"Regere meant to guide straight and to keep in line; rex 'king' and regio 'region' come from the same verb, so ruling and straightness were one idea.","cn":"regere 意为使笔直地引导、使成一线；rex「王」与 regio「地区」都出自同一动词，因此统治与笔直在当初是一个观念。"},{"era":"LATIN REGULA","en":"Regula was a rod used by masons and surveyors to test a line, and by extension any standard; the physical and the abstract senses were never separated.","cn":"regula 是泥瓦匠与测量员用来验直线的杆，引申为任何标准；实物义与抽象义从未分开。"},{"era":"OLD FRENCH RIULE","en":"Old French riule, later reule, carried both 'rod' and 'precept' into English, where rule first meant a standard of measurement and of conduct.","cn":"古法语 riule（后作 reule）把「杆」与「训令」两义一起带入英语，rule 最初兼指度量与行为的标准。"},{"era":"VERB FROM THE NOUN","en":"The verb appears later, first in the sense of marking a line with the rod, and only afterwards in the sense of governing.","cn":"动词出现较晚，先指用杆画线，之后才指治理。"},{"era":"LEGAL AND POLITICAL SENSE","en":"From the medieval period rule was used for dominion and for the decision of a court, the two senses that dominate modern usage.","cn":"自中世纪起，rule 被用于统治权与法院裁决，这两义主导了现代用法。"},{"era":"APPROXIMATE DATES","en":"The earliest English dates are approximate: the noun is recorded from the medieval period and the verb shortly after, but the first citations are not precisely fixed.","cn":"英语最早年代为约数：名词自中世纪有书证，动词稍后出现，但确切的最早书证并无定论。"}]},"similar":{"note":{"en":"The first group looks close to rule in spelling or sound but has a different job; the second group names standards and authority in other words.","cn":"第一组在拼写或读音上与 rule 接近，但职能不同；第二组用别的词来说标准与权威。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"ruler","ipa":"/ˈruːlə/","tag":"same family","definition":"Either the person who governs or the strip that measures; one form, two very different referents.","definitionCN":"既可指统治者，也可指量尺；一个词形，两个完全不同的所指。"},{"word":"ruling","ipa":"/ˈruːlɪŋ/","tag":"same family","definition":"A formal decision, or the adjective for a party in power; it is the product of ruling, not the standard itself.","definitionCN":"指正式裁决，或指执政的形容词；它是裁定的产物，而非标准本身。"},{"word":"regulate","ipa":"/ˈreɡjuleɪt/","tag":"same Latin root","definition":"The verb of controlling by standard, borrowed directly from Latin rather than through French.","definitionCN":"按标准控制的动词，直接借自拉丁而非经法语。"},{"word":"regular","ipa":"/ˈreɡjulə/","tag":"same Latin root","definition":"Even or habitual, from the same rod; it describes a pattern, not a power.","definitionCN":"匀整或惯常，同出那根杆；描述式样，而非权力。"},{"word":"rail","ipa":"/reɪl/","tag":"look-alike only","definition":"From regula as well, through the idea of a straight bar; it names the bar, not the standard.","definitionCN":"也出自 regula，经「直条」之义而来；它命名横杆，而非标准。"}]},{"heading":"NEAR MEANING","entries":[{"word":"regulation","ipa":"/ˌreɡjuˈleɪʃn/","tag":"formal register","definition":"A written rule issued by an authority, and the activity of enforcing standards; it is the official cousin of rule.","definitionCN":"由权威发布的书面规则，以及执行标准的活动；它是 rule 的正式对应词。"},{"word":"law","ipa":"/lɔː/","tag":"higher authority","definition":"A rule enacted by a legislature and enforced by the state, carrying penalties that a mere rule may lack.","definitionCN":"由立法机关制定、由国家执行、带有处罚的规则；单条 rule 未必有这种力量。"},{"word":"principle","ipa":"/ˈprɪnsəpl/","tag":"underlying standard","definition":"A broad standard from which particular rules are derived, rather than a clause written down.","definitionCN":"据以推出具体规则的一般标准，而非写下来的条款。"},{"word":"precept","ipa":"/prɪˈsept/","tag":"moral instruction","definition":"A rule of conduct given as guidance, often moral or religious in tone.","definitionCN":"作为指引给出的行为准则，常带道德或宗教色彩。"},{"word":"dominion","ipa":"/dəˈmɪnjən/","tag":"territory of rule","definition":"The territory or the sovereignty itself; it names what is ruled rather than the act of ruling.","definitionCN":"指领土或主权本身；命名被统治的对象，而非统治行为。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin rod, the real family and real fixed phrases.","cn":"正常联想使用真实的拉丁「直杆」词、真实的同族词与真实固定搭配。"},"normal":[{"en":"Regula is a straight rod, so a rule is a rod laid beside behaviour to check whether it is straight.","cn":"regula 是一根直杆，所以规则就是贴在行为旁边、用来检查它是否笔直的杆。"},{"en":"The family runs rule, ruler, ruling, ruled, overrule and unruly.","cn":"同族词有 rule、ruler、ruling、ruled、overrule 与 unruly。"},{"en":"Fixed phrases mark the everyday senses: break a rule, follow the rules, as a rule, rule out.","cn":"固定搭配标出日常义：违反规则、遵守规则、一般说来、排除。"},{"en":"A carpenter's rule and a king's rule are the same object in two materials, wood and power.","cn":"木匠的尺与国王的统治，是同一件东西的两种材料：木头与权力。"},{"en":"The verb rule meaning draw a line is the oldest verb sense, not a metaphor.","cn":"动词 rule 表示画线，是最早的动词义，而不是比喻。"}],"abstract":[{"en":"Picture a pencil pulled along a wooden edge, leaving a line that nothing later may cross.","cn":"想象一支铅笔沿木边拉过，留下一条此后谁都不能越过的线。"},{"en":"Picture a judge laying a rod on a map and saying that this side of it is settled.","cn":"想象一位法官把一根杆放在地图上，说这一边就此定案。"},{"en":"Picture a habit sitting quietly at the head of a table, deciding what everyone will say.","cn":"想象一个习惯安静地坐在长桌主位，决定每个人要说什么。"}]},"examples":[{"en":"The first rule of the laboratory is that nothing is tasted.","cn":"实验室的第一条规则是任何东西都不许尝。"},{"en":"She ruled the family firm for twenty years without ever raising her voice.","cn":"她掌管家族企业二十年，从未提高过嗓门。"},{"en":"Rule a margin down the left side of the page.","cn":"在页面左侧画出一条页边线。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「rule 既是尺子也是规矩」——用尺画一条线，这条线就成了规矩 → 规则、统治","word":"rule"},"root":"拉丁 regula「直杆、标准」→ 古法语 riule/reule → 英语 rule；regula 出自 regere「使笔直地引导」，同根还有 rex「王」与 regio「地区」。","sensesIntro":{"en":"Nine senses follow one rod: it is laid on conduct, becomes a habit, turns into a sceptre, acts as a verb of governing, falls as a judge's decision, stays a carpenter's tool, draws a line, writes a grammar, and finally holds a single heart.","cn":"九个义项围绕一根杆：它贴到行为上，变成习惯，化为权杖，转为治理的动词，落成法官的裁定，仍是木匠的工具，画出直线，写成语法，最后按住一颗心。"},"semanticMap":{"core":{"en":"CORE IMAGE: a rod laid on paper to draw a line, and that line then treated as uncrossable.","cn":"核心意象：一根杆压在纸上画出一条线，此后这条线被当成不可越过。"},"chain":["THE ROD","THE STANDARD","THE HABIT","THE SCEPTRE","THE VERDICT","THE LINE"],"branches":[{"senses":"01 · 08","en":"STANDARD AND SYSTEM: a stated regulation and a grammar clause are the same rod applied to conduct and to symbols.","cn":"标准与系统：明文规定与语法条款，是同一根杆用在行为与符号上。"},{"senses":"02","en":"THE HABIT: what usually happens becomes an expectation, and the noun stretches from statute to statistics.","cn":"习惯：常发生的事变成预期，名词从法令延伸到统计。"},{"senses":"03 · 04 · 09","en":"SWAY AT THREE SCALES: a country, a council and a single heart are all governed by something holding the rod.","cn":"三种尺度的支配：国家、议事会与一颗心，都由握着杆的东西支配。"},{"senses":"05","en":"THE VERDICT: a judge's decision lays the rod down for one dispute and ends it.","cn":"裁决：法官的决定为一场争议定下标准并了结它。"},{"senses":"06 · 07","en":"TOOL AND LINE: the carpenter's strip and the drawn line are the rod itself, before any rule was abstract.","cn":"工具与线：木匠的直条与画出的线，是抽象成规则之前的那根杆本身。"}]},"affixes":{"intro":{"en":"Rule is a short word hiding a Latin rod, and the same root has produced a large English family through two routes, French and direct borrowing.","cn":"rule 是个短词，背后是一根拉丁直杆；同一词根经法语与直接借入两条路线，产生了庞大的英语词族。"},"latinIntro":{"en":"Latin regula gives rule and rail through French; regere gives regulate, direct and region; the doer suffix -or gives ruler and regulator.","cn":"拉丁 regula 经法语给出 rule 与 rail；regere 给出 regulate、direct 与 region；施动后缀给出 ruler 与 regulator。"},"items":[{"word":"reg-","structure":"regere (Latin verb)","meaning":"to guide straight","meaningCN":"使笔直引导","example":"The root gives the straight line.","exampleCN":"词根给出直线。"},{"word":"-ula","structure":"Latin instrument ending","meaning":"thing used for","meaningCN":"作……用之物","example":"It makes the measuring rod.","exampleCN":"它构成量尺。"},{"word":"regula","structure":"reg- plus -ula","meaning":"rod; standard","meaningCN":"直杆；标准","example":"Physical and abstract senses at once.","exampleCN":"实物义与抽象义同时存在。"},{"word":"rule","structure":"regula through Old French","meaning":"standard; dominion; to govern","meaningCN":"规则；统治；治理","example":"The short English descendant.","exampleCN":"英语中的短形式后裔。"},{"word":"ruler","structure":"rule plus -er","meaning":"one who rules; a strip","meaningCN":"统治者；尺","example":"The doer suffix does double duty.","exampleCN":"施动后缀兼两职。"},{"word":"ruling","structure":"rule plus -ing","meaning":"a decision; governing","meaningCN":"裁决；执政的","example":"The suffix names the product or the role.","exampleCN":"后缀命名产物或角色。"},{"word":"-ate","structure":"Latin -are verb ending","meaning":"to do","meaningCN":"做……","example":"It forms regulate directly from Latin.","exampleCN":"它直接由拉丁构成 regulate。"},{"word":"regulate","structure":"regula plus -are","meaning":"to control by standard","meaningCN":"按标准控制","example":"The borrowed twin of rule.","exampleCN":"rule 的借入式对应词。"},{"word":"regulation","structure":"regulate plus -ion","meaning":"rule; the act of ruling","meaningCN":"规章；管制","example":"The formal noun of the standard.","exampleCN":"标准的正式名词。"},{"word":"over-","structure":"Old English ofer","meaning":"above, beyond","meaningCN":"在上、越过","example":"It forms overrule, to set a decision aside.","exampleCN":"它构成 overrule「驳回」。"}],"latinEntries":[{"word":"regula","structure":"regula, regulae (f., first declension)","meaning":"rule, measuring rod","meaningCN":"规则；直杆"},{"word":"regere","structure":"regere, rexi, rectum (verb, third conjugation)","meaning":"to guide straight, rule","meaningCN":"使笔直引导；统治"},{"word":"rectus","structure":"rectus, recta, rectum (adj.)","meaning":"straight, right","meaningCN":"直的；正确的"},{"word":"regio","structure":"regio, regionis (f., third declension)","meaning":"region, line boundary","meaningCN":"地区；界线"}],"derivatives":[{"word":"ruler","pos":"n.","zh":"统治者；尺子"},{"word":"ruling","pos":"n./adj.","zh":"裁决；执政的"},{"word":"unruly","pos":"adj.","zh":"难以管束的"},{"word":"overrule","pos":"v.","zh":"驳回；否决"},{"word":"regulate","pos":"v.","zh":"管理；调节"}]}},{"word":"ruling","ipa_uk":"/ˈruːlɪŋ/","ipa_us":"/ˈruːlɪŋ/","definition_zh":"裁决；裁定；（机构对规则的）解释性决定；执政的；统治","definition_en":"an official decision made by a court or authority, or the adjective for a group that currently holds power","core_image":"法庭窗口递出一页纸，纸上的几行结论把一场争论彻底定了下来","scene":"书记员在走廊里分发裁决书副本，双方律师还没走出门口就拿到了。The clerk handed out copies of the ruling before the parties had left the corridor.","sceneCN":"这里 ruling 指「法院作出的正式裁决」（第 1 个义项：法院裁决）；句意为书记员在走廊分发裁决书副本，双方律师还没走出门口就拿到了。图中可辨识物件：裁决书、复印纸、法庭窗口、律师文件包。","pos":[{"tag":"n.","zh":"裁决；裁定；解释性决定"},{"tag":"adj.","zh":"执政的；掌权的"}],"collocations":[{"phrase":"a court ruling","zh":"法院裁决"},{"phrase":"the ruling party","zh":"执政党"},{"phrase":"a final ruling","zh":"最终裁决"},{"phrase":"overturn a ruling","zh":"推翻裁决"},{"phrase":"a ruling on the case","zh":"就该案作出的裁定"},{"phrase":"the ruling class","zh":"统治阶级"}],"forms":[{"label":"复数（名词）","form":"rulings"},{"label":"动词原形","form":"rule"},{"label":"过去式","form":"ruled"},{"label":"现在分词","form":"ruling"},{"label":"施动者名词","form":"ruler"}],"derivatives":[{"word":"rule","pos":"n./v.","zh":"规则；统治；裁定"},{"word":"ruler","pos":"n.","zh":"统治者；尺子"},{"word":"overrule","pos":"v.","zh":"驳回；否决"},{"word":"unruly","pos":"adj.","zh":"难以管束的"}],"senses":[{"no":"01","title":"A court's formal decision","titleCN":"法院作出的正式裁决","definition":"the formal decision of a court on a point of law or on a case","definitionCN":"法院就某一法律争点或案件作出的正式决定","example":"The clerk handed out copies of the ruling before the parties had left the corridor.","exampleCN":"书记员在走廊分发裁决书副本，双方律师还没走出门口就拿到了。","why":"The noun of action from rule turns the act of laying down the standard into the paper that carries it, so ruling is the decision as an object.","whyCN":"由 rule 构成的动名词把「定下标准」这一动作变成承载它的那张纸，因此 ruling 是作为物件存在的决定。"},{"no":"02","title":"A decision by an authority","titleCN":"行政或专业机构作出的裁定","definition":"an authoritative decision by a regulator, tribunal or committee on a matter within its powers","definitionCN":"监管机构、裁判所或委员会在其权限内就某一事项作出的权威决定","example":"The regulator's ruling forced the airline to refund every cancelled ticket.","exampleCN":"监管机构的裁定迫使该航空公司为所有被取消的机票退款。","why":"Any body that holds a standard can lay it down, and English uses the same noun whether the bench is a court or a commission.","whyCN":"任何握有标准的机构都能定下标准，英语不论法庭还是委员会都用同一个名词。"},{"no":"03","title":"Currently in power","titleCN":"正在执政的（形容词）","definition":"describing a party, group or family that presently holds governing power","definitionCN":"描述当前掌握治理权力的政党、群体或家族","example":"The ruling coalition lost four seats in the recount.","exampleCN":"重新计票后，执政联盟失去了四个席位。","why":"The participle form marks the one doing the verb now, so the ruling party is literally the party that is ruling at this moment.","whyCN":"分词形式标记此刻正在做这个动作的一方，因此执政党字面上就是「此刻正在统治的党」。"},{"no":"04","title":"The exercise of authority","titleCN":"治理这一行为本身（名词）","definition":"the activity of governing, considered as a continuous practice rather than a single order","definitionCN":"把治理看作持续的做法，而非某一道命令","example":"Historians describe his ruling as a long pause rather than a reign.","exampleCN":"历史学者把他执政的那些年描述为一段长长的停顿，而非一个朝代。","why":"When the noun names an ongoing activity rather than a document, it shifts from the product to the process.","whyCN":"当名词命名持续的活动而非文件时，它就从产物转向过程。"},{"no":"05","title":"A referee's decision","titleCN":"体育裁判的判罚决定","definition":"a decision by an official on the field about what the rules require","definitionCN":"场上官员就规则要求作出的一项决定","example":"The umpire's ruling stood even after the replay.","exampleCN":"即便看过回放，裁判的判罚仍然维持。","why":"Sport borrows the courtroom noun for its own officials, because both announce what the rules say about one event.","whyCN":"体育为自家官员借用法庭名词，因为两者都在宣布规则对某一事件怎么说。"},{"no":"06","title":"An interpretation of a rule","titleCN":"对规则含义作出的解释性裁定","definition":"an authoritative statement about how an existing rule should be read in a particular situation","definitionCN":"就现有规则在特定情形下应如何理解作出的权威说明","example":"The committee issued a ruling that part-time staff also count as members.","exampleCN":"委员会作出裁定，兼职人员也算作成员。","why":"Rules need reading as well as writing, and the body that reads them aloud gains the power to say what they were always meant to mean.","whyCN":"规则除写出来之外还需要被读，而有权把规则读出声的机构，就获得了说明「它本来是什么意思」的权力。"},{"no":"07","title":"A decision of a church council","titleCN":"教会会议的决定","definition":"a formal decision by a synod or church body on doctrine or discipline","definitionCN":"主教会议或教会机构就教义或纪律作出的正式决定","example":"The council's ruling on fasting was read from every pulpit.","exampleCN":"会议关于斋戒的裁定在每个讲坛上都被宣读。","why":"Religious bodies also hold a standard and settle disputes by pronouncement, so the secular noun fits them without alteration.","whyCN":"宗教机构同样握有标准，并以宣告来定纷争，因此这个世俗名词无需改动就能适用。"},{"no":"08","title":"Dominating a person's life","titleCN":"支配一个人生活的主导力量（形容词）","definition":"describing a feeling, interest or idea that controls someone's behaviour","definitionCN":"描述控制某人行为的情绪、兴趣或观念","example":"A ruling ambition kept him at the desk long after the others had gone.","exampleCN":"一种主导性的野心让他在别人都走了很久之后仍留在桌旁。","why":"The participle can describe anything that governs, not only a government, which is how the word reaches private life.","whyCN":"分词可以描述任何起支配作用的东西，不必是一个政府；这个词正是这样走进私人生活的。"}],"etymology":{"intro":{"en":"Ruling is the present participle and verbal noun of rule, which comes through Old French from Latin regula 'rod, standard'. The judicial noun develops from the verb's sense of deciding.","cn":"ruling 是 rule 的现在分词与动名词，而 rule 经古法语来自拉丁 regula「杆、标准」。司法名词义由动词「裁定」一义发展而来。"},"items":[{"era":"LATIN REGULA","en":"Regula was the straight rod used to test a line, and by extension the standard itself; the physical tool and the abstract norm were one word.","cn":"regula 是检验直线用的直杆，引申为标准本身；实物工具与抽象规范在拉丁语里是一个词。"},{"era":"LATIN REGERE","en":"Regere 'to guide straight' stands behind regula and also gives rex 'king', so straightness and authority share an origin.","cn":"regere「使笔直引导」在 regula 背后，同时也是 rex「王」的来源，因此笔直与权威同源。"},{"era":"OLD FRENCH RULE","en":"Old French reule carried the noun into English, where the verb rule then produced the participle ruling.","cn":"古法语 reule 把这个名词带入英语，随后动词 rule 产生了分词 ruling。"},{"era":"DECISION SENSE","en":"From the medieval period the verb meant to settle a matter by authority, and the participle became a noun for the settlement itself.","cn":"自中世纪起，动词指以权威定夺事项，分词则成为指该定夺本身的名词。"},{"era":"MODERN LEGAL USE","en":"Modern legal writing fixed ruling to the reasoned decision of a court or tribunal, distinct from the verdict of a jury.","cn":"现代法律写作把 ruling 固定为法院或裁判所给出理由的决定，与陪审团的评断相区别。"},{"era":"APPROXIMATE DATES","en":"The date at which the noun settled into its legal sense is approximate; earlier uses overlap with the general sense of governing.","cn":"这个名词固定为法律义的年代为约数；更早的用例与「治理」的一般义重叠。"}]},"similar":{"note":{"en":"The first group is the same family, where one ending changes the job of the word; the second group names decisions of various kinds.","cn":"第一组是同一词族，词尾一变职能就变；第二组是各类决定。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"rule","ipa":"/ruːl/","tag":"same family","definition":"The standard itself, or the act of governing; it is the source of the whole group.","definitionCN":"指标准本身或治理行为，是整个词组的源头。"},{"word":"ruler","ipa":"/ˈruːlə/","tag":"same family","definition":"The person who governs, or the measuring strip; the doer form has two referents.","definitionCN":"指统治者或量尺；施动形式有两个所指。"},{"word":"ruled","ipa":"/ruːld/","tag":"same family","definition":"The past participle: governed, or marked with lines.","definitionCN":"过去分词：被统治的，或画了线的。"},{"word":"regulate","ipa":"/ˈreɡjuleɪt/","tag":"same Latin root","definition":"The verb of controlling by standard, borrowed straight from Latin rather than through French.","definitionCN":"按标准控制的动词，直接借自拉丁而非经法语。"},{"word":"regulator","ipa":"/ˈreɡjuleɪtə/","tag":"same Latin root","definition":"The body or device that holds a quantity to a standard.","definitionCN":"把某个量守在标准上的机构或装置。"}]},{"heading":"NEAR MEANING","entries":[{"word":"verdict","ipa":"/ˈvɜːdɪkt/","tag":"jury, not judge","definition":"The finding of a jury on the facts; a ruling decides the law or the procedure, and the two are kept apart.","definitionCN":"陪审团对事实的评断；ruling 判定法律或程序，两者被明确分开。"},{"word":"judgment","ipa":"/ˈdʒʌdʒmənt/","tag":"wider decision","definition":"Any judicial decision, including the reasons and the order; broader than a ruling on one point.","definitionCN":"任何司法决定，含理由与命令；比就某一点作出的裁定更宽。"},{"word":"decree","ipa":"/dɪˈkriː/","tag":"executive order","definition":"An order issued by a sovereign or a government, carrying force without litigation.","definitionCN":"由君主或政府发布的命令，不经诉讼即具效力。"},{"word":"order","ipa":"/ˈɔːdə/","tag":"procedural command","definition":"An instruction by a court about what a party must do, such as pay or disclose.","definitionCN":"法院就当事人必须做什么（如付款、披露）作出的指令。"},{"word":"holding","ipa":"/ˈhəʊldɪŋ/","tag":"the legal principle","definition":"The legal principle a decision establishes, as distinct from the outcome for the parties.","definitionCN":"判决所确立的法律原则，与当事人的结果相区别。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real root, the real family and real fixed phrases.","cn":"正常联想使用真实词根、真实同族词与真实固定搭配。"},"normal":[{"en":"The word is the act of ruling made into a thing, so a ruling is a decision you can hold in your hand.","cn":"这个词是「统治、裁定」这一动作变成物件，因此裁决是一份能拿在手里的决定。"},{"en":"The family runs rule, ruler, ruling, ruled, overrule and unruly.","cn":"同族词有 rule、ruler、ruling、ruled、overrule 与 unruly。"},{"en":"Fixed phrases mark the two senses: a court ruling, and the ruling party.","cn":"固定搭配标出两义：法院裁决，以及执政党。"},{"en":"The same ending appears in wedding and warning: an act turned into an event or a document.","cn":"同一词尾也出现在「婚礼」与「警告」中：动作变成事件或文书。"},{"en":"A ruling party is not a party full of rules; it is the party doing the ruling right now.","cn":"执政党不是「充满规则的党」，而是此刻正在治理的党。"}],"abstract":[{"en":"Picture a sheet of paper handed through a hatch before either side has stood up.","cn":"想象一张纸在双方还没起身时就从窗口递了出来。"},{"en":"Picture a line already drawn on a map, and everyone else arranging themselves behind it.","cn":"想象地图上已经画好一条线，其余的人都在线的这一侧站好。"},{"en":"Picture a single interest sitting at the head of a life, deciding what the day is for.","cn":"想象一种兴趣坐在一生的主位，决定这一天要用来做什么。"}]},"examples":[{"en":"The ruling settles the question for every school in the province.","cn":"这项裁决为全省每一所学校解决了这个问题。"},{"en":"The ruling party promised to cut the tariff within a year.","cn":"执政党承诺一年内削减关税。"},{"en":"Players waited for the umpire's ruling before serving again.","cn":"球员等着裁判的判罚，才重新发球。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「rule（裁定/统治）+ ing（正在）」——正在统治的，或已经定下的那一条 → 裁决、执政的","word":"ruling"},"root":"拉丁 regula「直杆、标准」（出自 regere「使笔直引导」）→ 古法语 reule → 英语 rule；加现在分词词尾构成 ruling「裁定、执政的」。","sensesIntro":{"en":"Eight senses follow one sheet of paper: it leaves a court, then a regulator, then labels a party in power, then names governing as a practice, then a referee's call, then a reading of a rule, then a church decision, and finally the ambition that rules a life.","cn":"八个义项围绕一张纸：它先出自法庭，再出自监管机构，然后标记执政的一方，再命名治理这件事，接着是裁判的判罚、对规则的解释、教会的决定，最后是支配一生的那种野心。"},"semanticMap":{"core":{"en":"CORE IMAGE: a decision on paper, handed out while the argument is still warm.","cn":"核心意象：一份写在纸上的决定，争论还热着就被分发出去。"},"chain":["THE DECISION","THE AUTHORITY","THE PARTY IN POWER","THE PRACTICE","THE FIELD","THE PRIVATE SWAY"],"branches":[{"senses":"01 · 02","en":"BENCH AND BOARD: a court and a regulator both lay the standard down, and the paper looks the same.","cn":"法庭与委员会：法院与监管机构都在定下标准，纸面看起来一样。"},{"senses":"03 · 04","en":"POWER AS ROLE AND AS PROCESS: who is ruling now, and what ruling is as a continuous practice.","cn":"权力作角色与作过程：此刻谁在执政，以及执政作为持续的做法。"},{"senses":"05 · 06","en":"TWO KINDS OF READING: a referee reads the rules for one match, a committee reads them for everyone.","cn":"两种宣读：裁判为一场比赛读规则，委员会为所有人读规则。"},{"senses":"07","en":"THE OTHER PULPIT: a council pronounces, and the secular noun needs no change.","cn":"另一个讲坛：会议作出宣告，这个世俗名词无需改动。"},{"senses":"08","en":"THE PRIVATE RULER: an ambition holds the reins, and the participle follows it home.","cn":"私人的统治者：一种野心握着缰绳，分词跟着它走进家门。"}]},"affixes":{"intro":{"en":"Ruling is a short Latin-derived root plus a participle ending that turns the act into a document or a role.","cn":"ruling 是一个简短的拉丁来源词根加一个分词词尾，把动作变成文书或角色。"},"latinIntro":{"en":"Latin regula and regere supply rule, ruler and regulate; the ending -ing marks an ongoing act or its product.","cn":"拉丁 regula 与 regere 提供 rule、ruler 与 regulate；分词词尾标记进行中的动作或其产物。"},"items":[{"word":"reg-","structure":"regere (Latin verb)","meaning":"to guide straight","meaningCN":"使笔直引导","example":"The root supplies the straight line.","exampleCN":"词根提供直线。"},{"word":"-ula","structure":"Latin instrument ending","meaning":"thing used for","meaningCN":"作……用之物","example":"It forms the measuring rod.","exampleCN":"它构成量尺。"},{"word":"regula","structure":"reg- plus -ula","meaning":"rod; standard","meaningCN":"直杆；标准","example":"Tool and norm in one word.","exampleCN":"工具与规范合一。"},{"word":"rule","structure":"regula through French","meaning":"standard; to govern","meaningCN":"规则；统治","example":"The English base.","exampleCN":"英语基础词。"},{"word":"-ing","structure":"Old English -ende/-ung","meaning":"act in progress; product","meaningCN":"进行中的动作；产物","example":"It makes the participle and the verbal noun.","exampleCN":"它构成分词与动名词。"},{"word":"ruling","structure":"rule plus -ing","meaning":"a decision; governing","meaningCN":"裁决；执政的","example":"The same ending yields both senses.","exampleCN":"同一词尾产出两义。"},{"word":"ruler","structure":"rule plus -er","meaning":"one who rules; a strip","meaningCN":"统治者；尺","example":"The doer form of the base verb.","exampleCN":"基础动词的施动形式。"},{"word":"over-","structure":"Old English ofer","meaning":"above, beyond","meaningCN":"在上、越过","example":"It forms overrule, to set aside.","exampleCN":"它构成「驳回」。"},{"word":"un-","structure":"Old English un-","meaning":"not","meaningCN":"不","example":"It forms unruly, hard to govern.","exampleCN":"它构成 unruly「难管束」。"},{"word":"-ed","structure":"Old English -ed","meaning":"having the quality","meaningCN":"具有……的","example":"It forms ruled, governed or lined.","exampleCN":"它构成 ruled「受治的、划线的」。"}],"latinEntries":[{"word":"regula","structure":"regula, regulae (f., first declension)","meaning":"rule, measuring rod","meaningCN":"规则；直杆"},{"word":"regere","structure":"regere, rexi, rectum (verb, third conjugation)","meaning":"to guide straight, rule","meaningCN":"使笔直引导；统治"},{"word":"rectus","structure":"rectus, recta, rectum (adj.)","meaning":"straight, right","meaningCN":"直的；正确的"},{"word":"regio","structure":"regio, regionis (f., third declension)","meaning":"region, boundary line","meaningCN":"地区；界线"}],"derivatives":[{"word":"rule","pos":"n./v.","zh":"规则；统治；裁定"},{"word":"ruler","pos":"n.","zh":"统治者；尺子"},{"word":"overrule","pos":"v.","zh":"驳回；否决"},{"word":"unruly","pos":"adj.","zh":"难以管束的"}]}},{"word":"jurisdiction","ipa_uk":"/ˌdʒʊərɪsˈdɪkʃn/","ipa_us":"/ˌdʒɜːrɪsˈdɪkʃn/","definition_zh":"管辖权；管辖范围；（法院或机关的）受理权限；司法管辖","definition_en":"the official power of a court or authority to hear cases, make decisions or regulate a field, and the area or matters over which that power applies","core_image":"河岸上立着一块界碑，两名警官各自站在自己这一侧，谁都不肯把脚跨过去","scene":"两名警官在河边争执，却谁也不肯跨过界碑，因为那段水面不在自己的辖区之内。Neither officer would cross the boundary stone, because the stretch of water lay outside his jurisdiction.","sceneCN":"这里 jurisdiction 指「某一机关有权处理的地域范围」（第 2 个义项：管辖区域）；句意为两名警官都不肯跨过界碑，因为那段水面不在自己的辖区之内。图中可辨识物件：界碑、河水、警徽、两岸的标记。","pos":[{"tag":"n.","zh":"管辖权；管辖范围；受理权限"}],"collocations":[{"phrase":"within the jurisdiction of","zh":"在……的管辖范围之内"},{"phrase":"outside the court's jurisdiction","zh":"超出法院的管辖范围"},{"phrase":"exercise jurisdiction over","zh":"对……行使管辖权"},{"phrase":"exclusive jurisdiction","zh":"专属管辖权"},{"phrase":"universal jurisdiction","zh":"普遍管辖权"},{"phrase":"a change of jurisdiction","zh":"管辖权的变更"}],"forms":[{"label":"复数","form":"jurisdictions"},{"label":"形容词","form":"jurisdictional"},{"label":"副词","form":"jurisdictionally"}],"derivatives":[{"word":"jurisdictional","pos":"adj.","zh":"管辖权的；管辖上的"},{"word":"jurisdictionally","pos":"adv.","zh":"在管辖权意义上"},{"word":"jurist","pos":"n.","zh":"法学家（同出 ius，但不指权限）"},{"word":"jurisprudence","pos":"n.","zh":"法学；法理（同出 ius）"}],"senses":[{"no":"01","title":"A court's power to hear a case","titleCN":"法院受理与审判案件的权限","definition":"the power of a court to hear a particular kind of case and give a binding decision","definitionCN":"法院受理某一类案件并作出有约束力决定的权力","example":"The appeal failed because the tribunal had no jurisdiction over criminal matters.","exampleCN":"上诉失败，因为该裁判所对刑事事项没有管辖权。","why":"The word joins ius 'law' to dictio 'a saying': jurisdiction is literally the speaking of law, and only certain courts are granted the right to speak it over certain cases.","whyCN":"这个词把 ius「法」与 dictio「宣告」结合起来：管辖权字面上就是「宣告法律」，而只有特定法院被授予就特定案件宣告法律的资格。"},{"no":"02","title":"The area covered","titleCN":"管辖区域","definition":"the geographical area within which an authority may act","definitionCN":"某一机关可以行动的地理范围","example":"Neither officer would cross the boundary stone, because the stretch of water lay outside his jurisdiction.","exampleCN":"两名警官都不肯跨过界碑，因为那段水面不在自己的辖区之内。","why":"Power needs a where as well as a what, so the abstract right is measured onto land, and the boundary becomes the visible form of the noun.","whyCN":"权力既需要「对什么」，也需要「在哪里」，于是抽象权限被丈量到土地上，界线成了这个名词可见的形态。"},{"no":"03","title":"Regulatory power over a field","titleCN":"对某一领域的监管权限","definition":"the authority of a public body to set and enforce rules in a particular sector","definitionCN":"公共机构在某一行业设定并执行规则的权力","example":"Energy pricing fell within the jurisdiction of the provincial board.","exampleCN":"能源定价属于省委员会的管辖范围。","why":"Modern regulators hold powers that were once judicial, and they describe their remit with the same noun because both mean the right to decide authoritatively.","whyCN":"现代监管机构握有曾经属于司法的权力，它们用同一个名词来描述职权范围，因为两者都指权威地作出决定的资格。"},{"no":"04","title":"A state's legal power","titleCN":"国家对人与地的法律权力","definition":"the legal competence of a state over persons, property and events connected with its territory","definitionCN":"国家对与其领土相关的人、财产与事件的法律权限","example":"The ship was seized in waters under national jurisdiction.","exampleCN":"该船在受国家管辖的水域被扣押。","why":"Sovereignty and jurisdiction are not the same: a state may own nothing in a place and still hold the right to try crimes committed there.","whyCN":"主权与管辖权并不相同：一个国家可以在某地没有任何产业，却仍拥有审判在那里发生的罪行的权力。"},{"no":"05","title":"The limits of any authority","titleCN":"任何权限的边界（在权限内/越权）","definition":"the scope within which a person or body may properly act, often invoked when someone has gone beyond it","definitionCN":"某人或某机构可以正当行动的界限，常在有人越界时被援引","example":"The inspector was told that the question lay outside her jurisdiction.","exampleCN":"有人告知这位稽查员，该问题超出她的权限。","why":"The noun is used negatively as much as positively: saying that something is outside a jurisdiction is the standard way to refuse to act.","whyCN":"这个名词的否定用法与肯定用法一样多：说某事「不在管辖之内」，是拒绝行动的惯常说法。"},{"no":"06","title":"Competence between states","titleCN":"国际法上国家之间的管辖权限","definition":"the competence of one state to exercise authority, especially criminal jurisdiction, over acts with a foreign element","definitionCN":"一国对有外国因素的行为行使权威（尤其是刑事管辖）的权限","example":"Under universal jurisdiction, any state may try the case.","exampleCN":"依普遍管辖权，任何国家都可以审理该案。","why":"Where there is no world court, the noun is used to divide competence between sovereigns, and the dividing line is negotiated rather than drawn by a single legislator.","whyCN":"在没有世界法院的地方，这个名词用来在主权国家之间划分权限，而那条分界线是协商出来的，并非由单一立法者画出。"},{"no":"07","title":"The authority of a church court","titleCN":"教会法庭的管辖权","definition":"the power of an ecclesiastical court or bishop to decide matters of doctrine and discipline","definitionCN":"教会法庭或主教就教义与纪律事项作出决定的权力","example":"The marriage case was returned to the church's own jurisdiction.","exampleCN":"这桩婚姻案件被交回教会自己的管辖范围。","why":"Church courts held this power long before royal ones, so the noun entered legal language with an ecclesiastical owner already in place.","whyCN":"教会法庭掌握这项权力远早于王室法庭，因此这个名词进入法律语言时，早已有一个教会的所有者。"},{"no":"08","title":"Exercising or declining it","titleCN":"行使或拒绝行使管辖权","definition":"the act by which a court takes up a matter, or formally refuses to","definitionCN":"法院接手某一事项、或正式拒绝接手的动作","example":"The court declined jurisdiction and left the parties to arbitrate.","exampleCN":"法院拒绝行使管辖权，让当事人自行仲裁。","why":"Rights are exercised by acts, so the noun also names the moment of taking or refusing a case, which is why lawyers speak of assuming and declining jurisdiction.","whyCN":"权利通过行为行使，因此这个名词也命名接手或拒绝案件的时刻，律师所谓「取得管辖」与「拒绝管辖」即由此而来。"}],"etymology":{"intro":{"en":"Jurisdiction comes from Latin iurisdictio, from ius 'law, right' plus dictio 'a saying', from dicere 'to speak'. It entered English through French in the medieval period.","cn":"jurisdiction 来自拉丁 iurisdictio，由 ius「法、权利」加 dictio「宣告」（出自 dicere「说」）构成。它在中世纪经法语进入英语。"},"items":[{"era":"LATIN IUS","en":"Ius meant law in the sense of right and binding custom, as distinct from lex, an enacted statute; the distinction matters for this word's relatives.","cn":"ius 指作为权利与有约束力习俗的法，与 lex「被制定的法令」相区别；这一区别对这个词的同族词很重要。"},{"era":"LATIN DICERE","en":"Dicere meant to say or to declare publicly; dictio is the act of saying, so the compound names the public declaration of what is right.","cn":"dicere 意为说、公开宣告；dictio 是「说」这一行为，因此这个复合词命名对何者为正当的公开宣告。"},{"era":"IURISDICTIO","en":"Iurisdictio in Roman law meant the magistrate's function of stating the law for a case, not the whole power of a modern court.","cn":"iurisdictio 在罗马法中指长官为一案宣告法律这一职能，而非现代法院的全部权力。"},{"era":"MEDIEVAL CHURCH AND CROWN","en":"Medieval church and royal courts both claimed the right to declare the law in their own spheres, and the noun was fixed to that division of competence.","cn":"中世纪教会法庭与王室法庭都主张在各自领域宣告法律的资格，这个名词被固定到这种权限划分上。"},{"era":"MODERN EXTENSION","en":"Modern states extended the noun to regulators and to international competence, so the word now covers any bounded right to decide.","cn":"现代国家把这个名词扩展到监管机构与国际权限，如今它覆盖任何有边界的决定权。"},{"era":"APPROXIMATE DATES","en":"The English first date is approximate: the borrowing is medieval, but the earliest citation in legal French and English is not precisely fixed.","cn":"英语首见年代为约数：借入发生在中世纪，但法律法语与英语中的最早书证没有精确年代。"}]},"similar":{"note":{"en":"The first group shares the Latin ius but differs in what it names; the second group names neighbouring kinds of authority.","cn":"第一组共享拉丁 ius，但命名的对象不同；第二组是相邻的权限种类。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"jurisdictional","ipa":"/ˌdʒʊərɪsˈdɪkʃənl/","tag":"same family","definition":"The adjective for anything concerning jurisdiction, especially in procedural objections.","definitionCN":"形容词，指与管辖权有关的事项，尤用于程序异议。"},{"word":"jurist","ipa":"/ˈdʒʊərɪst/","tag":"same root","definition":"A scholar of law, from ius; it names a person who studies law, not a power.","definitionCN":"法学家，出自 ius；它指研究法律的人，而非一种权力。"},{"word":"jurisprudence","ipa":"/ˌdʒʊərɪsˈpruːdns/","tag":"same root, different second half","definition":"The theory or study of law, from ius plus prudentia 'knowledge'; it names learning, not the right to decide.","definitionCN":"关于法的理论或研究，由 ius 加 prudentia「知识」构成；命名学问，而非决定权。"},{"word":"jury","ipa":"/ˈdʒʊəri/","tag":"look-alike, different root","definition":"From iurare 'to swear', not ius: a sworn body of citizens, so its resemblance to jurisdiction is deceptive.","definitionCN":"出自 iurare「宣誓」而非 ius：指宣誓的公民团体，因此与 jurisdiction 的相似是假象。"},{"word":"judge","ipa":"/dʒʌdʒ/","tag":"look-alike, different root","definition":"From iudex, built on ius plus dicere, a cousin of the same stock but naming the person.","definitionCN":"出自 iudex，由 ius 与 dicere 构成，同源但命名的是那个人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"authority","ipa":"/ɔːˈθɒrəti/","tag":"general power","definition":"Any recognised power to act or decide, with no territorial or subject limit built in.","definitionCN":"任何被承认的行动或决定权，不含地域或事项的固有界限。"},{"word":"competence","ipa":"/ˈkɒmpɪtəns/","tag":"technical doublet","definition":"In law and diplomacy, the capacity of a body to act; it overlaps with jurisdiction but stresses capacity rather than territory.","definitionCN":"在法律与外交中，指机构行事的能力；与 jurisdiction 重叠，但强调能力而非地域。"},{"word":"venue","ipa":"/ˈviːnjuː/","tag":"place of trial","definition":"The locality where a case is tried, a question of convenience rather than of power.","definitionCN":"审判案件的地点，属便利问题，而非权力问题。"},{"word":"mandate","ipa":"/ˈmændeɪt/","tag":"granted remit","definition":"The commission given to a body by a superior authority, which defines what it may do.","definitionCN":"上级授予某机构的任务与权限，界定它可以做什么。"},{"word":"purview","ipa":"/ˈpɜːvjuː/","tag":"scope of a document","definition":"The scope of a statute or document, a matter of coverage rather than of power.","definitionCN":"法令或文书的覆盖范围，属涵盖问题而非权力问题。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin law and saying, the real family and real fixed phrases.","cn":"正常联想使用真实的拉丁「法」与「宣告」、真实同族词与真实固定搭配。"},"normal":[{"en":"Ius is law and dictio is a saying, so jurisdiction is the saying of law, the right to declare it in a given case.","cn":"ius 是法，dictio 是宣告，因此管辖就是「宣告法律」，即就某一案件宣告法律的资格。"},{"en":"The family runs jurisdiction, jurisdictional, jurisdictionally, jurist and jurisprudence.","cn":"同族词有 jurisdiction、jurisdictional、jurisdictionally、jurist 与 jurisprudence。"},{"en":"Fixed phrases mark the limits: within the jurisdiction of, outside the court's jurisdiction, exercise jurisdiction over.","cn":"固定搭配标出界限：在……管辖之内、超出法院管辖、对……行使管辖。"},{"en":"Ius and lex were different words in Latin: the first is right, the second is statute, which is why jurisdiction and legal do not share a root.","cn":"拉丁语中 ius 与 lex 是两个词：前者是权利，后者是法令，因此 jurisdiction 与 legal 并不同根。"},{"en":"A boundary stone is the noun made visible, since every power needs a where.","cn":"界碑是这个名词的可见形态，因为每一种权力都需要一个「在哪里」。"}],"abstract":[{"en":"Picture two officers standing on either side of a stone, each unwilling to lift a foot.","cn":"想象两名警官站在界碑两侧，谁都不肯抬脚。"},{"en":"Picture a microphone that only works inside one room, however loud the speaker.","cn":"想象一支只在某个房间内起作用的麦克风，无论说话多大声。"},{"en":"Picture a key cut for one door in a street of identical doors.","cn":"想象一把钥匙，只配得上同一条街上众多相同门中的一扇。"}]},"examples":[{"en":"The case was moved to a court with proper jurisdiction.","cn":"该案被移送到有适当管辖权的法院。"},{"en":"Local police have no jurisdiction beyond the county line.","cn":"地方警察在县界之外没有管辖权。"},{"en":"The treaty allows jurisdiction to be shared in cross-border cases.","cn":"该条约允许在跨境案件中共享管辖权。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「juris（法）+ diction（宣告）」——有权宣告法律的范围 → 管辖权","word":"jurisdiction"},"root":"拉丁 ius「法、权利」+ dictio「宣告」（出自 dicere「说」）→ iurisdictio「宣告法律、司法职能」→ 法语 → 英语 jurisdiction。","sensesIntro":{"en":"Eight senses follow one boundary stone: it marks a court's cases, a district's ground, a regulator's sector, a state's reach, any authority's limit, the line between nations, a church's sphere, and the moment of taking or refusing a case.","cn":"八个义项围绕一块界碑：它标出法院能审的案件、地区的土地、监管者的行业、国家的触及范围、任何权限的界限、国家之间的线、教会的领域，以及接手或拒绝案件的时刻。"},"semanticMap":{"core":{"en":"CORE IMAGE: a stone in the ground with an officer on either side, neither crossing.","cn":"核心意象：地上立着一块石头，两侧各有一名警官，谁都不越过去。"},"chain":["THE RIGHT TO DECLARE","A COURT'S CASES","A DISTRICT'S GROUND","A SECTOR'S RULES","A STATE'S REACH","THE ACT OF TAKING"],"branches":[{"senses":"01 · 08","en":"POWER AND ITS EXERCISE: the right to hear and the act of taking a case are the same power asleep and awake.","cn":"权力与行使：受理资格与接手案件的动作，是同一权力的睡与醒。"},{"senses":"02 · 03 · 04","en":"THREE MAPS: a district, an industry and a state all draw the same boundary at different scales.","cn":"三张地图：地区、行业与国家在不同尺度上画出同一条界线。"},{"senses":"05","en":"THE LIMIT AS A REFUSAL: the noun is most often used to say that something is not mine to decide.","cn":"界限即拒绝：这个名词最常用来表示「此事不归我决定」。"},{"senses":"06","en":"BETWEEN SOVEREIGNS: without a world legislature, competence is negotiated rather than granted.","cn":"主权之间：没有世界立法者，权限靠协商而非授予。"},{"senses":"07","en":"THE OLDER COURT: a church court holds the same right to declare, and the noun needs no change.","cn":"更早的法庭：教会法庭握有同样的宣告权，名词无需改动。"}]},"affixes":{"intro":{"en":"Jurisdiction is a Latin compound of 'law' and 'saying', and both halves remain visible in English relatives.","cn":"jurisdiction 是拉丁语「法」与「宣告」的复合，两半在英语同族词里仍然可见。"},"latinIntro":{"en":"Latin ius gives jurist, jurisprudence and justice; dicere gives dictate, diction and verdict; the compound iurisdictio gives jurisdiction.","cn":"拉丁 ius 提供 jurist、jurisprudence 与 justice；dicere 提供 dictate、diction 与 verdict；复合词 iurisdictio 给出 jurisdiction。"},"items":[{"word":"ius","structure":"ius, iuris (n., third declension)","meaning":"law, right","meaningCN":"法；权利","example":"The first half supplies law as right.","exampleCN":"前半提供作为权利的法。"},{"word":"iuris-","structure":"genitive stem of ius","meaning":"of law","meaningCN":"法的","example":"It links the two halves.","exampleCN":"它连接两半。"},{"word":"dictio","structure":"dictio, dictionis (f., third declension)","meaning":"a saying, declaration","meaningCN":"宣告；陈述","example":"The second half supplies the public saying.","exampleCN":"后半提供公开宣告。"},{"word":"dicere","structure":"dicere, dixi, dictum (verb, third conjugation)","meaning":"to say, declare","meaningCN":"说；宣告","example":"The verb behind dictio.","exampleCN":"dictio 背后的动词。"},{"word":"iurisdictio","structure":"iuris plus dictio","meaning":"administration of law","meaningCN":"司法职能；宣告法律","example":"The Latin compound itself.","exampleCN":"拉丁复合词本身。"},{"word":"jurisdiction","structure":"iurisdictio through French","meaning":"the power to hear and decide","meaningCN":"管辖权","example":"The English descendant.","exampleCN":"英语后裔。"},{"word":"-al","structure":"Latin -alis","meaning":"relating to","meaningCN":"与……相关的","example":"It forms the adjective.","exampleCN":"它构成形容词。"},{"word":"jurisdictional","structure":"jurisdiction plus -al","meaning":"of jurisdiction","meaningCN":"管辖上的","example":"The adjective of the noun.","exampleCN":"名词的形容词。"},{"word":"-ance","structure":"Latin -antia through French","meaning":"state of","meaningCN":"……的状态","example":"It appears in cognate nouns of similar shape.","exampleCN":"它出现在形状相近的同源名词中。"},{"word":"-prudence","structure":"prudentia 'knowledge'","meaning":"knowledge of","meaningCN":"关于……的学问","example":"It builds jurisprudence, the study rather than the power.","exampleCN":"它构成 jurisprudence，指学问而非权力。"}],"latinEntries":[{"word":"ius","structure":"ius, iuris (n., third declension)","meaning":"law, right","meaningCN":"法；权利"},{"word":"dicere","structure":"dicere, dixi, dictum (verb, third conjugation)","meaning":"to say, declare","meaningCN":"说；宣告"},{"word":"iurisdictio","structure":"iurisdictio, iurisdictionis (f., third declension)","meaning":"administration of justice","meaningCN":"司法；宣告法律"},{"word":"iudex","structure":"iudex, iudicis (m., third declension)","meaning":"judge","meaningCN":"法官"}],"derivatives":[{"word":"jurisdictional","pos":"adj.","zh":"管辖权的；管辖上的"},{"word":"jurisdictionally","pos":"adv.","zh":"在管辖权意义上"},{"word":"jurist","pos":"n.","zh":"法学家"},{"word":"jurisprudence","pos":"n.","zh":"法学；法理"}]}},{"word":"jurisdictional","ipa_uk":"/ˌdʒʊərɪsˈdɪkʃənl/","ipa_us":"/ˌdʒɜːrɪsˈdɪkʃənl/","definition_zh":"管辖权的；管辖上的；与管辖范围有关的","definition_en":"relating to the power of a court or authority to hear cases or regulate matters, or to the limits of that power","core_image":"两张地图叠在同一张桌上，界线彼此错开，桌边的人用指尖反复敲那条谁也不认的线","scene":"两个机构整个下午都在争论同一段海岸的归属。The two agencies spent the afternoon on a jurisdictional dispute over the same stretch of coast.","sceneCN":"这里 jurisdictional 指「与管辖权归属有关的」（第 4 个义项：涉及管辖争议的）；句意为两个机构整个下午都在争论同一段海岸归谁管辖。图中可辨识物件：两张叠放的地图、错开的界线、会议桌、指向海岸的指尖。","pos":[{"tag":"adj.","zh":"管辖权的；管辖上的；涉及管辖范围的"}],"collocations":[{"phrase":"a jurisdictional dispute","zh":"管辖争议"},{"phrase":"jurisdictional limits","zh":"管辖界限"},{"phrase":"a jurisdictional question","zh":"管辖权问题"},{"phrase":"jurisdictional boundaries","zh":"管辖边界"},{"phrase":"jurisdictional objection","zh":"管辖权异议"},{"phrase":"jurisdictional authority","zh":"管辖权"}],"forms":[{"label":"名词","form":"jurisdiction"},{"label":"副词","form":"jurisdictionally"},{"label":"比较级","form":"more jurisdictional"},{"label":"最高级","form":"most jurisdictional"}],"derivatives":[{"word":"jurisdiction","pos":"n.","zh":"管辖权；管辖范围"},{"word":"jurisdictionally","pos":"adv.","zh":"在管辖权意义上"},{"word":"jurist","pos":"n.","zh":"法学家"},{"word":"jurisprudence","pos":"n.","zh":"法学；法理"}],"senses":[{"no":"01","title":"Relating to jurisdiction in general","titleCN":"与管辖权这一概念有关的","definition":"relating to the power to hear and decide, considered in general terms","definitionCN":"一般性地与受理与决定的权力相关","example":"The report separates jurisdictional issues from questions of policy.","exampleCN":"这份报告把管辖问题与政策问题分开。","why":"The adjective is the noun plus -al, the ordinary Latin ending for 'relating to', so it does no more than attach the concept to whatever follows.","whyCN":"这个形容词是名词加上拉丁语中表示「与……相关」的常规形容词词尾，因此它只把那个概念附着到后面的词上。"},{"no":"02","title":"Within a court's power","titleCN":"属于某一法院权限之内的","definition":"describing a matter that a particular court has the power to decide","definitionCN":"描述某一具体法院有权决定的事项","example":"Whether the claim is jurisdictional or substantive decides which hearing comes first.","exampleCN":"请求属于管辖问题还是实体问题，决定哪一场听证先开。","why":"Courts sort their work into power and merits, and the adjective is the label on the first pile.","whyCN":"法院把自己的工作分成权限与实体两类，这个形容词就是第一堆上的标签。"},{"no":"03","title":"About territorial limits","titleCN":"与地域界限有关的","definition":"concerning the geographical area in which an authority may act","definitionCN":"与某一机关可以行动的地域范围相关","example":"A jurisdictional boundary runs down the middle of the river.","exampleCN":"一条管辖边界沿着河的中线延伸。","why":"Since power is bounded in space, descriptions of space become descriptions of power, and the adjective serves both.","whyCN":"既然权力在空间上有界，对空间的描述就成了对权力的描述，这个形容词两者兼用。"},{"no":"04","title":"Involving a dispute over who decides","titleCN":"涉及「谁有权决定」之争的","definition":"describing a disagreement about which body, not which outcome, is the right one","definitionCN":"描述关于「哪个机构而非哪个结果才正确」的分歧","example":"The two agencies spent the afternoon on a jurisdictional dispute over the same stretch of coast.","exampleCN":"两个机构整个下午都在争论同一段海岸归谁管辖。","why":"Two authorities can agree on the merits and still fight over the file, and the adjective names that fight precisely.","whyCN":"两个机关可以在实体问题上意见一致，却仍为卷宗归谁而争；这个形容词精确命名那场争执。"},{"no":"05","title":"Challenging a court's power","titleCN":"对法院权限提出异议的","definition":"describing an objection that the court lacks the power to hear the case at all","definitionCN":"描述「法院根本无权审理此案」的异议","example":"The defendant raised a jurisdictional objection before any evidence was read.","exampleCN":"被告在宣读任何证据之前先提出了管辖权异议。","why":"A challenge to power must come first, because a court without power cannot do anything else, and procedure reflects that order.","whyCN":"对权限的质疑必须先提出，因为无权的法院做不了任何别的事，程序正反映了这一顺序。"},{"no":"06","title":"About a regulator's remit","titleCN":"与监管机构职权范围有关的","definition":"relating to the sector or matters a public body is empowered to regulate","definitionCN":"与某一公共机构获权监管的行业或事项相关","example":"The bank argued that consumer credit was outside the agency's jurisdictional reach.","exampleCN":"该银行主张消费信贷不在这个机构的管辖触及范围之内。","why":"Regulators inherited judicial vocabulary along with judicial-style powers, and the adjective marks the edge of their remit.","whyCN":"监管机构连同类司法的权力一并继承了司法词汇，这个形容词标出其职权的边缘。"},{"no":"07","title":"About competence between states","titleCN":"与国家间权限有关的（国际法）","definition":"relating to the allocation of competence between states in international law","definitionCN":"与国际法中各国权限的分配相关","example":"Jurisdictional rules decide which country may prosecute a ship's crew.","exampleCN":"管辖规则决定哪个国家可以起诉船上的船员。","why":"At that level the adjective marks a negotiated line between equals, which is why it appears so often in treaties rather than in statutes.","whyCN":"在这一层面，这个形容词标记平等者之间协商出的界线，因此它多见于条约而非法令。"},{"no":"08","title":"About church authority","titleCN":"与教会权威有关的","definition":"relating to the authority of an ecclesiastical court or bishop","definitionCN":"与教会法庭或主教的权威相关","example":"The jurisdictional claim of the bishop was heard by the royal court itself.","exampleCN":"主教提出的管辖权主张由王室法庭亲自审理。","why":"Two courts claiming the same case is the purest form of the quarrel this adjective describes, and it predates the modern state.","whyCN":"两个法庭主张同一案件，是这个形容词所描述之争的最纯粹形态，而这种争执早于现代国家。"}],"etymology":{"intro":{"en":"Jurisdictional is jurisdiction plus the Latin-derived adjective ending -al. Jurisdiction comes from iurisdictio, built on ius 'law, right' and dictio 'a saying'.","cn":"jurisdictional 是 jurisdiction 加拉丁来源的形容词词尾构成。jurisdiction 出自 iurisdictio，由 ius「法、权利」与 dictio「宣告」构成。"},"items":[{"era":"LATIN IUS","en":"Ius meant law as right and binding custom, not an enacted statute; the enacted kind was lex, which is why jurisdiction and legal are not relatives.","cn":"ius 指作为权利与有约束力习俗的法，而非被制定的法令；被制定的那类叫 lex，因此 jurisdiction 与 legal 并非同族。"},{"era":"LATIN DICERE","en":"Dictio is the act of saying, from dicere; the compound iurisdictio names the public declaration of what is right in a case.","cn":"dictio 是「说」这一行为，出自 dicere；复合词 iurisdictio 命名就一案公开宣告何者为正当。"},{"era":"MEDIEVAL BORROWING","en":"English took jurisdiction through French in the medieval period, and the adjective followed once the noun was established in legal writing.","cn":"英语在中世纪经法语借入 jurisdiction，名词在法律文书中立稳之后，形容词随之出现。"},{"era":"SUFFIX -AL","en":"The ending -al, from Latin -alis, means 'relating to' and is the standard way to turn a legal noun into a classifying adjective.","cn":"这个形容词词尾来自拉丁语中表示关系的形式，意为「与……相关」，是把法律名词变成分类形容词的常规方式。"},{"era":"MODERN SPREAD","en":"As regulators and international bodies multiplied, the adjective spread from courts to any bounded competence.","cn":"随着监管机构与国际机构增多，这个形容词从法院扩散到任何有边界的权限。"},{"era":"APPROXIMATE DATES","en":"The first date of the adjective is approximate: it appears after the noun is settled, but the earliest citation is not precisely recorded.","cn":"这个形容词的最早年代为约数：它出现在名词定型之后，确切的最早书证没有精确记录。"}]},"similar":{"note":{"en":"The first group shares the ius stem and is easily confused with it; the second group names other kinds of legal description.","cn":"第一组共享 ius 词干，极易与它混淆；第二组是其他类型的法律描述。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"jurisdiction","ipa":"/ˌdʒʊərɪsˈdɪkʃn/","tag":"same family","definition":"The noun itself, naming the power or the area rather than describing it.","definitionCN":"名词本身，命名权力或区域，而非描述它。"},{"word":"jurisdictionally","ipa":"/ˌdʒʊərɪsˈdɪkʃənəli/","tag":"same family","definition":"The adverb, used for statements about competence rather than about merits.","definitionCN":"副词，用于关于权限而非实体的陈述。"},{"word":"jurist","ipa":"/ˈdʒʊərɪst/","tag":"same root","definition":"A legal scholar, from ius; the word names a person, not a power.","definitionCN":"法学家，出自 ius；命名人，而非权力。"},{"word":"jurisprudence","ipa":"/ˌdʒʊərɪsˈpruːdns/","tag":"same root","definition":"The study or theory of law, from ius plus prudentia; it names learning.","definitionCN":"关于法的研究或理论，由 ius 加 prudentia 构成；命名学问。"},{"word":"judicial","ipa":"/dʒuːˈdɪʃl/","tag":"look-alike, different stem","definition":"From iudicium 'judgment', about judges and courts as institutions, not about their territorial reach.","definitionCN":"出自 iudicium「判断」，指法官与法院作为机构，而非其地域触及范围。"}]},{"heading":"NEAR MEANING","entries":[{"word":"territorial","ipa":"/ˌterəˈtɔːriəl/","tag":"space only","definition":"About land and its extent; a territorial claim need not involve any power to decide cases.","definitionCN":"关于土地及其范围；领土主张未必涉及审理案件的权力。"},{"word":"administrative","ipa":"/ədˈmɪnɪstrətɪv/","tag":"procedure","definition":"About the running of an institution or the execution of rules, rather than about competence.","definitionCN":"关于机构运转或规则执行，而非权限。"},{"word":"procedural","ipa":"/prəˈsiːdərəl/","tag":"the rules of the forum","definition":"About how a case is conducted, which is a separate question from whether the forum may hear it.","definitionCN":"关于案件如何进行，与审理机构是否有权受理是另一个问题。"},{"word":"competent","ipa":"/ˈkɒmpɪtənt/","tag":"capacity","definition":"In legal usage, having the power to act; close to jurisdictional but used of persons and bodies alike.","definitionCN":"在法律用法中指有权行事；与 jurisdictional 接近，但人与机构皆可用。"},{"word":"statutory","ipa":"/ˈstætjʊtəri/","tag":"source of the rule","definition":"About what a statute provides, which may create or limit a jurisdiction without being about it.","definitionCN":"关于法令所规定的内容，可能创设或限制管辖权，但本身并非关于管辖权。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin law and saying, the real family and real fixed phrases.","cn":"正常联想使用真实的拉丁「法」与「宣告」、真实同族词与真实固定搭配。"},"normal":[{"en":"The word is the noun plus the ending 'relating to', so it simply tags something as belonging to the question of who may decide.","cn":"这个词是名词加「与……相关」的词尾，只是把某事物标记为属于「谁有权决定」这一问题。"},{"en":"The family runs jurisdiction, jurisdictional, jurisdictionally, jurist and jurisprudence.","cn":"同族词有 jurisdiction、jurisdictional、jurisdictionally、jurist 与 jurisprudence。"},{"en":"Fixed phrases mark the courtroom sense: a jurisdictional dispute, jurisdictional limits, a jurisdictional objection.","cn":"固定搭配标出法庭义：管辖争议、管辖界限、管辖权异议。"},{"en":"Ius means right and lex means statute, so this adjective never means 'according to a statute'.","cn":"ius 指权利，lex 指法令，因此这个形容词从不表示「依照某条法令」。"},{"en":"Two maps on one table is the everyday picture of a jurisdictional quarrel.","cn":"两张地图摊在一张桌上，就是管辖之争的日常画面。"}],"abstract":[{"en":"Picture two overlapping maps whose borders refuse to line up.","cn":"想象两张重叠的地图，边界怎么也对不齐。"},{"en":"Picture a door with two nameplates, each office certain the other's is wrong.","cn":"想象一扇门挂着两块名牌，两个办公室都确信对方那块是错的。"},{"en":"Picture a referee and a judge standing at the same touchline, each waiting for the other to yield.","cn":"想象裁判与法官站在同一条边线旁，各自等着对方让步。"}]},"examples":[{"en":"The jurisdictional question delayed the trial by a year.","cn":"管辖问题使审判推迟了一年。"},{"en":"Cross-border cases raise jurisdictional problems that treaties try to settle.","cn":"跨境案件会引发管辖难题，条约正试图解决这些难题。"},{"en":"The agency's jurisdictional reach stops at the provincial border.","cn":"该机构的管辖范围止于省界。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「jurisdiction（管辖权）+ al（的）」——关于管辖权的 → 管辖的","word":"jurisdictional"},"root":"拉丁 ius「法、权利」+ dictio「宣告」→ iurisdictio → 英语 jurisdiction；加形容词词尾构成 jurisdictional「管辖的」。","sensesIntro":{"en":"Eight senses follow two misaligned maps: the adjective labels the concept, then a court's pile, then a boundary, then a quarrel, then an objection, then a regulator's remit, then a state's competence, then a bishop's claim.","cn":"八个义项围绕两张错位的地图：这个形容词先标记概念，再标记法院的那一堆案件、一条边界、一场争执、一项异议、监管者的职权、国家的权限，最后是主教的主张。"},"semanticMap":{"core":{"en":"CORE IMAGE: two maps stacked on one table with borders that will not line up.","cn":"核心意象：两张地图叠在一张桌上，边界怎么也对不齐。"},"chain":["THE LABEL","THE COURT'S PILE","THE BOUNDARY","THE QUARREL","THE OBJECTION","THE REGULATOR"],"branches":[{"senses":"01 · 02","en":"CONCEPT AND DOCKET: naming the power in general and sorting one court's cases are the same label at two distances.","cn":"概念与案卷：泛指权力与给某一法院的案件分类，是同一标签的两个距离。"},{"senses":"03 · 04","en":"SPACE AND STRIFE: a line on the ground becomes a quarrel when two bodies claim the same strip.","cn":"空间与争执：地上的线在两家都主张同一段时就成了争执。"},{"senses":"05","en":"THE FIRST WORD: an objection to power must precede everything, since a court without power can decide nothing.","cn":"第一句话：对权限的异议必须先说，因为无权的法院什么也决定不了。"},{"senses":"06 · 07","en":"TWO MODERN SCALES: a regulator's sector and a state's competence are the old adjective on new maps.","cn":"两种现代尺度：监管者的行业与国家的权限，是旧形容词画在新地图上。"},{"senses":"08","en":"THE OLD CLAIM: a bishop's court asserted the same kind of right long before the modern state did.","cn":"古老的主张：教会法庭主张同类权利远早于现代国家。"}]},"affixes":{"intro":{"en":"Jurisdictional is a Latin compound noun plus the common relational ending, all three layers still readable.","cn":"jurisdictional 是拉丁复合名词加常见关系词尾，三层结构至今可读。"},"latinIntro":{"en":"Latin ius gives jurist and justice; dicere gives dictate and verdict; -alis gives the adjective ending used across legal English.","cn":"拉丁 ius 提供 jurist 与 justice；dicere 提供 dictate 与 verdict；拉丁语的形容词词尾在法律英语中通用。"},"items":[{"word":"ius","structure":"ius, iuris (Latin noun)","meaning":"law, right","meaningCN":"法；权利","example":"The first half names the law as right.","exampleCN":"前半命名作为权利的法。"},{"word":"iuris-","structure":"genitive stem","meaning":"of law","meaningCN":"法的","example":"It joins the two halves.","exampleCN":"它连接两半。"},{"word":"dictio","structure":"dictio, dictionis (Latin noun)","meaning":"a saying","meaningCN":"宣告","example":"The second half names the saying.","exampleCN":"后半命名宣告。"},{"word":"iurisdictio","structure":"iuris plus dictio","meaning":"declaration of law","meaningCN":"宣告法律；司法","example":"The Latin compound.","exampleCN":"拉丁复合词。"},{"word":"jurisdiction","structure":"iurisdictio through French","meaning":"power to decide","meaningCN":"管辖权","example":"The English noun.","exampleCN":"英语名词。"},{"word":"-al","structure":"Latin -alis","meaning":"relating to","meaningCN":"与……相关的","example":"It forms the adjective.","exampleCN":"它构成形容词。"},{"word":"jurisdictional","structure":"jurisdiction plus -al","meaning":"of jurisdiction","meaningCN":"管辖的","example":"The adjective under study.","exampleCN":"所研究的形容词。"},{"word":"-ly","structure":"Old English -lice","meaning":"in the manner of","meaningCN":"以……方式","example":"It forms the adverb.","exampleCN":"它构成副词。"},{"word":"jurisdictionally","structure":"jurisdictional plus -ly","meaning":"as regards jurisdiction","meaningCN":"在管辖意义上","example":"The adverb limits the claim.","exampleCN":"副词限定陈述范围。"},{"word":"-prudence","structure":"prudentia 'knowledge'","meaning":"knowledge of","meaningCN":"关于……的学问","example":"It builds jurisprudence, the study of law.","exampleCN":"它构成法学。"}],"latinEntries":[{"word":"ius","structure":"ius, iuris (n., third declension)","meaning":"law, right","meaningCN":"法；权利"},{"word":"dicere","structure":"dicere, dixi, dictum (verb, third conjugation)","meaning":"to say, declare","meaningCN":"说；宣告"},{"word":"iurisdictio","structure":"iurisdictio, iurisdictionis (f., third declension)","meaning":"declaration of law","meaningCN":"宣告法律；司法"},{"word":"iudicium","structure":"iudicium, iudicii (n., second declension)","meaning":"judgment","meaningCN":"判断；审判"}],"derivatives":[{"word":"jurisdiction","pos":"n.","zh":"管辖权；管辖范围"},{"word":"jurisdictionally","pos":"adv.","zh":"在管辖权意义上"},{"word":"jurist","pos":"n.","zh":"法学家"},{"word":"jurisprudence","pos":"n.","zh":"法学；法理"}]}},{"word":"judge","ipa_uk":"/dʒʌdʒ/","ipa_us":"/dʒʌdʒ/","definition_zh":"法官；评判者；评委；判断；审判；评价；估算","definition_en":"a person with authority to decide cases or competitions, or to form a considered opinion about something","core_image":"一柄木槌落在垫木上，声音不大，却让整间屋子里所有的争论同时停下","scene":"法槌敲下，旁听席上还在低声争论的两个人立刻安静了。The judge tapped the gavel and the room fell silent.","sceneCN":"这里 judge 指「在法庭上主持审理并作出裁决的官员」（第 1 个义项：法官）；句意为法官敲下法槌，屋子里立刻安静下来。图中可辨识物件：法槌、垫木、法官席、旁听长椅。","pos":[{"tag":"n.","zh":"法官；评判者；评委；士师"},{"tag":"v.","zh":"判断；审判；评价；估算；指责"}],"collocations":[{"phrase":"a panel of judges","zh":"评审团"},{"phrase":"judge by appearances","zh":"以貌取人"},{"phrase":"judge a competition","zh":"担任比赛评委"},{"phrase":"as far as I can judge","zh":"据我判断"},{"phrase":"judge someone guilty","zh":"判定某人有罪"},{"phrase":"don't judge a book by its cover","zh":"不要只看外表"}],"forms":[{"label":"三单（he/she/it）","form":"judges"},{"label":"过去式","form":"judged"},{"label":"过去分词","form":"judged"},{"label":"现在分词","form":"judging"},{"label":"复数（名词）","form":"judges"},{"label":"名词（判断）","form":"judgment"}],"derivatives":[{"word":"judgment","pos":"n.","zh":"判断；判决"},{"word":"judicial","pos":"adj.","zh":"司法的；法官的"},{"word":"judiciary","pos":"n.","zh":"司法系统；法官群体"},{"word":"judgemental","pos":"adj.","zh":"爱评判他人的"},{"word":"prejudge","pos":"v.","zh":"预先判断；未审先断"}],"senses":[{"no":"01","title":"The officer of a court","titleCN":"法庭上主持审理的官员（名词）","definition":"the official who presides over a court and decides questions of law and procedure","definitionCN":"主持法庭、裁定法律与程序问题的官员","example":"The judge tapped the gavel and the room fell silent.","exampleCN":"法官敲下法槌，屋子里立刻安静下来。","why":"Latin iudex joins ius 'law' and dicere 'to say', so a judge is literally one who says the law; the robe and the gavel are later additions to that sentence.","whyCN":"拉丁 iudex 把 ius「法」与 dicere「说」结合起来，法官字面上就是「说出法律的人」；法袍与法槌是后来加到这个句子上的。"},{"no":"02","title":"The one who decides a contest","titleCN":"比赛或展览的评委（名词）","definition":"a person appointed to compare entries and award a result in a competition","definitionCN":"被指定比较参赛作品并在比赛中给出结果的人","example":"A former champion sat on the judge's panel at the fencing final.","exampleCN":"一位前冠军坐在击剑决赛的评委席上。","why":"A contest also needs someone whose word settles it, and the ordinary word for that is the same one used in court.","whyCN":"比赛同样需要一个以一言定局的人，而指这个人的常用词与法庭里用的是同一个。"},{"no":"03","title":"To form an opinion","titleCN":"形成看法，认为（动词）","definition":"to conclude that something is the case, often after weighing evidence","definitionCN":"经权衡证据后断定某事如此","example":"I judge the delay to be a fault in the design rather than in the crew.","exampleCN":"我判断这次延误是设计上的问题，而不是船员的过失。","why":"The verb is the noun's act: saying what the law is becomes, outside court, saying what one takes a thing to be.","whyCN":"动词是名词所代表的行为：在法庭之外，「说出法律是什么」变成「说出自己认为某事物是什么」。"},{"no":"04","title":"To try and decide a case","titleCN":"审理并裁决案件（动词）","definition":"to hear a case as a court and give a decision on it","definitionCN":"作为法庭审理案件并作出决定","example":"The same bench will judge the appeal in October.","exampleCN":"同一个法庭将在十月审理这起上诉。","why":"The institutional sense stays technical: only a court judges a case, and the verb keeps the authority of the office behind it.","whyCN":"这一制度义仍是技术性的：只有法庭审理案件，动词背后仍带着职位的权威。"},{"no":"05","title":"To assess a performance","titleCN":"评价表现或作品（动词）","definition":"to compare a performance or work against a standard and say how good it is","definitionCN":"按标准比较某一表现或作品并评判其优劣","example":"Critics judge the film by its silence as much as by its dialogue.","exampleCN":"评论者评判这部影片，既看对白，也看它的沉默。","why":"Assessment replaces verdict: the standard remains, but the consequence is a score or an opinion rather than a penalty.","whyCN":"评判取代了判决：标准仍在，但后果是分数或意见，而不是处罚。"},{"no":"06","title":"To estimate a quantity","titleCN":"估算距离或数量（动词）","definition":"to estimate a distance, size or time by careful looking rather than by measuring","definitionCN":"靠仔细观察而非测量来估计距离、大小或时间","example":"Drivers must judge the gap before overtaking on this narrow road.","exampleCN":"在这条窄路上超车前，司机必须估算间距。","why":"Estimating is judging without a rule book: the eye takes the place of the rod, and the verb keeps the sense of a decision made on the spot.","whyCN":"估算是没有规则书的判断：眼睛代替了量尺，动词保留了当场作决定的意味。"},{"no":"07","title":"To decide what is true","titleCN":"判断真伪或性质（动词）","definition":"to decide whether a statement, claim or situation is true or sound","definitionCN":"判定某一说法、主张或情形是否真实可靠","example":"It is hard to judge whether the letter is genuine without the envelope.","exampleCN":"没有信封，很难判断这封信是否真迹。","why":"The element of saying what is so remains, even when no court and no competition is involved.","whyCN":"「说出事情究竟如何」这一成分始终存在，即使不涉及法庭与比赛。"},{"no":"08","title":"To criticise, informally","titleCN":"口语中带指责意味的评判（动词）","definition":"in informal speech, to form and express a disapproving opinion about someone","definitionCN":"口语中形成并表达对某人的不赞同看法","example":"She asked her brother not to judge her for leaving early.","exampleCN":"她请弟弟不要因为她提前离场就评判她。","why":"Since a judge's word carried consequences, the everyday verb acquired a sting; to judge someone now often means to pass sentence on their character.","whyCN":"既然法官的话带有后果，日常动词也就带上了刺；如今「评判某人」常指对其人品下判词。"},{"no":"09","title":"A leader in the biblical book","titleCN":"《士师记》中的士师（名词，专名用法）","definition":"one of the leaders in the biblical book of Judges who delivered the tribes from enemies","definitionCN":"《士师记》中拯救诸支派脱离敌人的领袖之一","example":"The story of a woman judge who led an army is read every spring.","exampleCN":"一位率领军队的女士师的故事每年春天都会被诵读。","why":"The Hebrew title of that book was rendered by the same English word because these leaders settled disputes as well as wars.","whyCN":"那卷书的标题被译成同一个英语词，因为这些领袖既定争讼，也领征战。"}],"etymology":{"intro":{"en":"Judge comes through Old French juge from Latin iudex, a compound of ius 'law, right' and dicere 'to say'; the judge is the one who speaks the law. The verb followed the noun into English.","cn":"judge 经古法语 juge 来自拉丁 iudex，由 ius「法、权利」与 dicere「说」复合而成；法官就是说出法律的人。动词随后跟进英语。"},"items":[{"era":"LATIN IUS","en":"Ius meant law as right and binding custom, distinct from lex, an enacted statute; this is why judge and legal are not related at the root.","cn":"ius 指作为权利与有约束力习俗的法，与 lex「被制定的法令」不同；因此 judge 与 legal 在词根上并不同源。"},{"era":"LATIN DICERE","en":"Dicere meant to say and to declare publicly; compounds with it name officials who speak in the community's name.","cn":"dicere 意为说、公开宣告；与它复合的词命名以共同体之名发言的官员。"},{"era":"IUDEX","en":"Iudex, genitive iudicis, named the man who stated the law for a dispute; Roman judges were lay deciders rather than career professionals.","cn":"iudex（属格 iudicis）指为一桩争议宣告法律的人；罗马的法官是业余裁断者，而非职业专家。"},{"era":"OLD FRENCH JUGE","en":"Old French juge carried the word into English in the medieval period, where judge first named the officer and then the act.","cn":"古法语 juge 在中世纪把这个词带入英语，judge 先指官员，随后指行为。"},{"era":"WIDENING IN ENGLISH","en":"English extended the verb to any decision of what is true or good, so judging a distance and judging a film use the same word as judging a case.","cn":"英语把动词扩展到任何关于真伪或优劣的决定，因此估算距离、评判影片与审理案件用的是同一个词。"},{"era":"APPROXIMATE DATES","en":"The first English date is approximate: the noun is recorded from the medieval period and the verb soon after, but exact citations vary by source.","cn":"英语最早年代为约数：名词自中世纪有书证，动词紧随其后，但确切书证因来源而异。"}]},"similar":{"note":{"en":"The first group looks alike and shares the iudex stem; the second group names other ways of forming an opinion.","cn":"第一组形近且共享 iudex 词干；第二组是形成意见的其他方式。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"judgment","ipa":"/ˈdʒʌdʒmənt/","tag":"same family","definition":"The decision or the capacity to decide well; American spelling drops the middle e.","definitionCN":"指决定或良好判断力；美式拼写省略中间的 e。"},{"word":"judicial","ipa":"/dʒuːˈdɪʃl/","tag":"same stem","definition":"About courts and judges as institutions, from iudicium.","definitionCN":"关于法院与法官作为机构，出自 iudicium。"},{"word":"judiciary","ipa":"/dʒuːˈdɪʃəri/","tag":"same stem","definition":"The branch or body of judges collectively, not one officer.","definitionCN":"指司法部门或法官群体，而非单个官员。"},{"word":"jurist","ipa":"/ˈdʒʊərɪst/","tag":"same root, other trade","definition":"A scholar of law, from ius alone; a jurist writes about law, a judge applies it.","definitionCN":"法学家，仅由 ius 构成；法学家写法律，法官用法律。"},{"word":"adjudicate","ipa":"/əˈdʒuːdɪkeɪt/","tag":"same stem, formal verb","definition":"To decide a dispute officially, the formal counterpart of judging a case.","definitionCN":"正式裁断争议，是「审理案件」的正式对应词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"assess","ipa":"/əˈses/","tag":"measure against a standard","definition":"To fix a value, tax or quality after weighing evidence, often with figures.","definitionCN":"权衡证据后确定价值、税额或品质，常带数字。"},{"word":"evaluate","ipa":"/ɪˈvæljueɪt/","tag":"systematic appraisal","definition":"To appraise by criteria, commoner in research and administration than in court.","definitionCN":"按标准评估，多见于研究与行政，少见于法庭。"},{"word":"deem","ipa":"/diːm/","tag":"formal opinion","definition":"A formal verb for holding something to be true, frequent in legal and official prose.","definitionCN":"正式表示「认为某事如此」，多用于法律与公文。"},{"word":"referee","ipa":"/ˌrefəˈriː/","tag":"sporting official","definition":"The official who applies the rules during play, closer to a judge of a match than of a court.","definitionCN":"比赛中执行规则的官员，更接近赛事裁判而非法庭法官。"},{"word":"arbiter","ipa":"/ˈɑːbɪtə/","tag":"chosen decider","definition":"A person chosen by the parties to settle a dispute, whose authority comes from consent rather than office.","definitionCN":"由当事人选定来定纷争的人，权威来自同意而非职位。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin law and saying, the real family and real fixed phrases.","cn":"正常联想使用真实的拉丁「法」与「宣告」、真实同族词与真实固定搭配。"},"normal":[{"en":"Ius is law and dicere is to say, so a judge is the one who says what the law is.","cn":"ius 是法，dicere 是说，法官就是说出现行法律是什么的那个人。"},{"en":"The family runs judge, judgment, judicial, judiciary, adjudicate and prejudge.","cn":"同族词有 judge、judgment、judicial、judiciary、adjudicate 与 prejudge。"},{"en":"Fixed phrases mark the everyday senses: a panel of judges, judge by appearances, as far as I can judge.","cn":"固定搭配标出日常义：评审团、以貌取人、据我判断。"},{"en":"The same root gives the biblical Judges, who settled disputes as well as wars.","cn":"同一词根也给出圣经中的士师，他们既定争讼，也领征战。"},{"en":"Judging a distance and judging a film are the same verb at two temperatures of authority.","cn":"估算距离与评判影片，是同一个动词在两种权威温度下。"}],"abstract":[{"en":"Picture a wooden hammer coming down, and every conversation in the room stopping at once.","cn":"想象一柄木槌落下，屋里所有谈话同时停住。"},{"en":"Picture three people at a long table holding up numbered cards at the same moment.","cn":"想象长桌后的三个人在同一刻举起号码牌。"},{"en":"Picture an eye measuring a gap in the traffic without any ruler at all.","cn":"想象一只眼睛完全不用尺，去量车流中的一段间隙。"}]},"examples":[{"en":"The judge ordered the evidence to be set aside.","cn":"法官裁定该证据不予采用。"},{"en":"Try not to judge the plan before you have read it.","cn":"还没读这份方案之前，尽量不要先下判断。"},{"en":"A good driver judges the width of a gap by habit, not by arithmetic.","cn":"好司机靠习惯估算间隙宽度，而不是靠算术。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「judge 一敲槌，就有定论」——说出法律、给出结论的人 → 法官、判断","word":"judge"},"root":"拉丁 ius「法、权利」+ dicere「说」→ iudex「宣告法律者」→ 古法语 juge → 英语 judge；动词由名词引申。","sensesIntro":{"en":"Nine senses follow one gavel: it settles a case, awards a contest, forms an opinion, tries an appeal, scores a film, measures a gap, tests a letter, criticises a person, and finally governs a tribe in an old book.","cn":"九个义项围绕一柄法槌：它定下一桩案件、给出比赛结果、形成看法、审理上诉、给影片打分、量出间隙、检验信件真伪、指责一个人，最后在古书里治理一个支派。"},"semanticMap":{"core":{"en":"CORE IMAGE: a gavel coming down, and every argument in the room stopping at the same moment.","cn":"核心意象：一柄法槌落下，屋里所有争论在同一刻停住。"},"chain":["THE WORD THAT SETTLES","THE COURT","THE CONTEST","THE OPINION","THE GAP","THE OLD LEADER"],"branches":[{"senses":"01 · 04","en":"OFFICE AND ACT: the officer and the act of trying a case are the same authority, one asleep and one awake.","cn":"职位与行为：官员与审理行为，是同一权威的睡与醒。"},{"senses":"02 · 05","en":"TWO SCORES: a contest and a performance both need a standard and a verdict, though the penalty is only a number.","cn":"两种打分：比赛与表演都需要标准与判定，只是处罚仅为一个数字。"},{"senses":"03 · 07","en":"WHAT IS TRUE: forming an opinion and testing a claim are the same sentence about reality.","cn":"何者为真：形成看法与检验说法，是关于现实的同一句话。"},{"senses":"06","en":"THE EYEBALL RULER: estimating a gap is judging with no rule book at all.","cn":"目测之尺：估算间隙就是完全没有规则书的判断。"},{"senses":"08 · 09","en":"TWO OLD DEPTHS: everyday blame borrows the judge's weight, and an ancient book lends the same word to tribal leaders.","cn":"两种古老纵深：日常指责借用法官的重量，古书则把同一个词借给支派领袖。"}]},"affixes":{"intro":{"en":"Judge is a Latin compound of 'law' and 'saying' that survives in several English words, though the compound is often hidden by spelling.","cn":"judge 是拉丁语「法」与「说」的复合词，在若干英语词中留存，但复合结构常被拼写遮住。"},"latinIntro":{"en":"Latin iudex and iudicium give judge, judgment and judicial; ius alone gives jurist and justice; dicere alone gives dictate and verdict.","cn":"拉丁 iudex 与 iudicium 给出 judge、judgment 与 judicial；单独的 ius 给出 jurist 与 justice；单独的 dicere 给出 dictate 与 verdict。"},"items":[{"word":"ius","structure":"ius, iuris (Latin noun)","meaning":"law, right","meaningCN":"法；权利","example":"The first element of the compound.","exampleCN":"复合词的第一成分。"},{"word":"dic-","structure":"dicere (Latin verb)","meaning":"to say","meaningCN":"说","example":"The second element, often hidden in spelling.","exampleCN":"第二成分，常在拼写中隐去。"},{"word":"iudex","structure":"ius plus dicere","meaning":"one who says the law","meaningCN":"宣告法律者","example":"The Latin compound noun.","exampleCN":"拉丁复合名词。"},{"word":"judge","structure":"iudex through Old French","meaning":"officer; to decide","meaningCN":"法官；判断","example":"The English descendant, noun and verb.","exampleCN":"英语后裔，名词与动词。"},{"word":"-ment","structure":"Latin -mentum","meaning":"result or act","meaningCN":"结果或行为","example":"It forms judgment.","exampleCN":"它构成 judgment。"},{"word":"judgment","structure":"judge plus -ment","meaning":"a decision; discernment","meaningCN":"判决；判断力","example":"The product of judging.","exampleCN":"judging 的产物。"},{"word":"-ial","structure":"Latin -ialis","meaning":"relating to","meaningCN":"与……相关的","example":"It forms judicial from iudicium.","exampleCN":"它由 iudicium 构成 judicial。"},{"word":"-ary","structure":"Latin -arius","meaning":"belonging to","meaningCN":"属于……的","example":"It forms judiciary, the body of judges.","exampleCN":"它构成 judiciary「法官群体」。"},{"word":"ad-","structure":"Latin ad- 'to'","meaning":"toward","meaningCN":"朝向","example":"It forms adjudicate, to decide toward a party.","exampleCN":"它构成 adjudicate「裁断」。"},{"word":"pre-","structure":"Latin prae- 'before'","meaning":"before","meaningCN":"在前","example":"It forms prejudge, to decide too early.","exampleCN":"它构成 prejudge「预先判断」。"}],"latinEntries":[{"word":"iudex","structure":"iudex, iudicis (m., third declension)","meaning":"judge","meaningCN":"法官"},{"word":"iudicium","structure":"iudicium, iudicii (n., second declension)","meaning":"judgment, trial","meaningCN":"判断；审判"},{"word":"iudicare","structure":"iudicare, iudicavi, iudicatum (verb, first conjugation)","meaning":"to judge, decide","meaningCN":"判断；裁决"},{"word":"ius","structure":"ius, iuris (n., third declension)","meaning":"law, right","meaningCN":"法；权利"}],"derivatives":[{"word":"judgment","pos":"n.","zh":"判断；判决"},{"word":"judicial","pos":"adj.","zh":"司法的"},{"word":"judiciary","pos":"n.","zh":"司法系统"},{"word":"judgemental","pos":"adj.","zh":"爱评判他人的"},{"word":"prejudge","pos":"v.","zh":"预先判断"}]}},{"word":"verdict","ipa_uk":"/ˈvɜːdɪkt/","ipa_us":"/ˈvɜːrdɪkt/","definition_zh":"裁决；评断；结论；（陪审团或验尸官的）裁定","definition_en":"the formal decision of a jury or an official inquiry, or any opinion reached after weighing the evidence","core_image":"十二个人从一间小屋里走出来，领头的人把一张折好的纸条递到书记员手里","scene":"十二个人在小屋里商议了四个小时，领头的人把写有结论的纸条交给书记员。The foreman handed the verdict to the clerk after four hours of deliberation.","sceneCN":"这里 verdict 指「陪审团经商议后作出的正式结论」（第 1 个义项：陪审团裁决）；句意为商议四小时后，领头的人把裁决结果交给书记员。图中可辨识物件：折好的纸条、陪审席、书记员的登记册、法庭围栏。","pos":[{"tag":"n.","zh":"裁决；评断；结论；裁定"}],"collocations":[{"phrase":"reach a verdict","zh":"作出裁决"},{"phrase":"a guilty verdict","zh":"有罪裁决"},{"phrase":"return a verdict","zh":"宣布裁决"},{"phrase":"the verdict of the jury","zh":"陪审团的裁决"},{"phrase":"await the verdict","zh":"等待裁决"},{"phrase":"the general verdict","zh":"总体评断"}],"forms":[{"label":"复数","form":"verdicts"},{"label":"相关动词","form":"verify"},{"label":"相关名词（说）","form":"dictum"}],"derivatives":[{"word":"verdicts","pos":"n.","zh":"裁决（复数）"},{"word":"veracious","pos":"adj.","zh":"诚实的；真实的（同出「真」的词根）"},{"word":"verity","pos":"n.","zh":"真实；真理（同出「真」的词根）"},{"word":"dictum","pos":"n.","zh":"格言；正式陈述（同出「说」的词根）"},{"word":"predict","pos":"v.","zh":"预言（同出「说」的词根）"}],"senses":[{"no":"01","title":"A jury's decision","titleCN":"陪审团作出的裁决","definition":"the formal finding of a jury on whether the accused is guilty or not guilty","definitionCN":"陪审团就被指控者有罪与否作出的正式结论","example":"The foreman handed the verdict to the clerk after four hours of deliberation.","exampleCN":"商议四小时后，领头的人把裁决结果交给书记员。","why":"Verdict is vere 'truly' plus dictum 'saying': the word originally meant a true statement, and the jury's function is to say what it holds to be true about the facts.","whyCN":"verdict 是 vere「真实地」加 dictum「陈述」：这个词原意是一句真话，而陪审团的职能正是说出它对事实所认定的真相。"},{"no":"02","title":"A finding of an inquiry","titleCN":"调查或验尸得出的结论","definition":"the conclusion recorded by an official inquiry, such as a coroner's finding on a death","definitionCN":"官方调查所记录的结论，如验尸官对死因的认定","example":"The coroner returned a verdict of accidental death.","exampleCN":"验尸官作出意外死亡的裁定。","why":"An inquiry speaks in the same voice as a jury: it states what it finds to be true, so the noun serves both without strain.","whyCN":"调查与陪审团以同一种口吻发言：它陈述自己认定的事实，因此这个名词无需费力就能适用于两者。"},{"no":"03","title":"A considered opinion","titleCN":"权衡证据后的评断","definition":"any judgement reached after weighing evidence, even where no court is involved","definitionCN":"经权衡证据后作出判断，即使不涉及法院","example":"Our verdict, after three months of testing, is that the material is sound.","exampleCN":"经过三个月测试，我们的结论是这种材料可靠。","why":"Once a verdict is simply a true saying, it can be pronounced by anyone who has done the weighing, not only by twelve sworn citizens.","whyCN":"既然裁决不过是一句真实的话，任何做过权衡的人都可以作出，而不必是十二名宣誓的公民。"},{"no":"04","title":"The public's judgement","titleCN":"公众或媒体对人的评价","definition":"the opinion formed about a person, product or event by the public at large","definitionCN":"公众对某人、某产品或某事件形成的看法","example":"The verdict on the new bridge was favourable long before it opened.","exampleCN":"这座新桥远在通车之前就已获得好评。","why":"The metaphor puts the public in the jury box: collective opinion borrows the finality of a court's word.","whyCN":"这个比喻把公众放进陪审席：集体意见借用了法庭话语的终局性。"},{"no":"05","title":"An official review decision in sport","titleCN":"体育复核后的官方判定","definition":"a final decision by a reviewing official or video panel on what happened in play","definitionCN":"复核官员或视频裁判组对场上事实作出的最终判定","example":"The video panel's verdict overturned the goal within thirty seconds.","exampleCN":"视频裁判组在三十秒内推翻了进球判定。","why":"Sport has added review panels that pronounce on facts, and they borrow the word because their finding must end the argument.","whyCN":"体育增设了对事实作出宣告的复核小组，它们借用了这个词，因为其结论必须终结争论。"},{"no":"06","title":"A decision on a submitted work","titleCN":"对提交作品的最终评定","definition":"the final decision of a panel on an entry or application","definitionCN":"评审团对参赛作品或申请作出的最终决定","example":"The jury's verdict placed the design second in its category.","exampleCN":"评审团的评定把该设计排在其类别第二。","why":"A competition needs a pronouncement that ends the comparison, and the courtroom noun supplies the finality.","whyCN":"比赛需要一个终结比较的宣告，而法庭名词正好提供这种终局性。"},{"no":"07","title":"The outcome of a test or comparison","titleCN":"测试或比较得出的结局性结论","definition":"the conclusion produced by a test, comparison or long observation","definitionCN":"测试、比较或长期观察所得出的结论","example":"Field trials gave a clear verdict: the treated plots held water longer.","exampleCN":"田间试验给出明确结论：处理过的地块保水更久。","why":"The noun is used for anything that finally settles a question, because settling is what the original word meant.","whyCN":"凡能最终了结一个问题的事物都用这个名词，因为「了结」正是原词之义。"},{"no":"08","title":"A verdict read as a sentence","titleCN":"裁决作为判词/量刑依据","definition":"the formal answer of guilty or not guilty, on which sentence then follows","definitionCN":"有罪或无罪的形式回答，随后据以量刑","example":"The verdict was not guilty, and the court had nothing left to impose.","exampleCN":"裁决为无罪，法院也就无从量刑。","why":"English keeps verdict for the answer and sentence for the consequence, a division that legal usage has held for centuries.","whyCN":"英语用 verdict 指回答，用 sentence 指后果，这一区分法律用法已维持数百年。"}],"etymology":{"intro":{"en":"Verdict comes through Anglo-French verdit from Latin veredictum, built on vere 'truly' plus dictum 'saying'. The word meant a true statement before it meant a jury's answer.","cn":"verdict 经英属法语 verdit 来自拉丁 veredictum，由 vere「真实地」加 dictum「陈述」构成。这个词先指真实的陈述，后指陪审团的回答。"},"items":[{"era":"LATIN VERUS","en":"Verus meant true, and its adverb vere meant truly; the same root gives veritas and the English verity.","cn":"verus 意为真的，其副词 vere 意为真实地；同一词根还给 veritas 与英语 verity。"},{"era":"LATIN DICTUM","en":"Dictum was a thing said, from dicere 'to say'; in legal Latin it named a formal statement rather than casual speech.","cn":"dictum 是所说的话，出自 dicere「说」；在法律拉丁中它指正式陈述，而非随意言谈。"},{"era":"VEREDICTUM","en":"Veredictum meant a true declaration; the compound is usually read as 'truly said', though the exact force of the first element is a matter of interpretation.","cn":"veredictum 意为真实的宣告；这个复合词通常被理解为「真实地说出」，不过第一个成分的确切作用属解释问题。"},{"era":"ANGLO-FRENCH VERDIT","en":"Anglo-French verdit narrowed the word to the answer a jury gives, which is how English received it in the medieval period.","cn":"英属法语 verdit 把这个词收窄为陪审团给出的回答，英语在中世纪正是这样接收它的。"},{"era":"FIXING TO THE JURY","en":"By the early modern period verdict was fixed to the jury's finding, with ruling and judgment covering the court's own decisions.","cn":"到近代早期，verdict 已固定为陪审团的认定，而法院自己的决定由 ruling 与 judgment 承担。"},{"era":"APPROXIMATE DATES","en":"The first English date is approximate: medieval use is recorded, but the earliest citation in English texts is not precisely fixed.","cn":"英语首见年代为约数：中世纪用例已有记录，但英语文本中的最早书证没有精确年代。"}]},"similar":{"note":{"en":"The first group shares the 'saying' stem or looks close to it; the second group names decisions that are often mistaken for a verdict.","cn":"第一组共享「说」这一词干或形近；第二组是常被误当作裁决的其他决定。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"dictum","ipa":"/ˈdɪktəm/","tag":"same second half","definition":"A formal saying or pronouncement, from the same dictum; it carries no decision and binds nobody.","definitionCN":"正式的说法或宣告，同出 dictum；它不含决定，也不约束任何人。"},{"word":"predict","ipa":"/prɪˈdɪkt/","tag":"same second half","definition":"To say beforehand, from dicere; it is about the future and needs no evidence.","definitionCN":"预先说出，出自 dicere；它关于未来，不需要证据。"},{"word":"verify","ipa":"/ˈverɪfaɪ/","tag":"same first half","definition":"To check that something is true, from verus; it tests a claim rather than settling it.","definitionCN":"核查某事是否真实，出自 verus；它检验说法，而非了结它。"},{"word":"verity","ipa":"/ˈverəti/","tag":"same first half","definition":"Truth or a true statement, from verus; an abstract noun with no courtroom role.","definitionCN":"真理或真实的陈述，出自 verus；抽象名词，无法庭职能。"},{"word":"justice","ipa":"/ˈdʒʌstɪs/","tag":"look-alike, different root","definition":"From ius 'right', not verus; it names fairness, not a finding.","definitionCN":"出自 ius「权利」而非 verus；命名公平，而非认定。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ruling","ipa":"/ˈruːlɪŋ/","tag":"judge, not jury","definition":"The court's decision on law or procedure; it answers the judge's question, while verdict answers the jury's.","definitionCN":"法院就法律或程序作出的决定；它回答法官的问题，而 verdict 回答陪审团的问题。"},{"word":"judgment","ipa":"/ˈdʒʌdʒmənt/","tag":"the whole decision","definition":"The full decision including reasons and order; verdict is only the answer to the charge.","definitionCN":"包含理由与命令的完整决定；verdict 只是对被控罪名的回答。"},{"word":"sentence","ipa":"/ˈsentəns/","tag":"what follows","definition":"The penalty imposed after a verdict; it is the consequence, never the finding.","definitionCN":"裁决之后所施加的处罚；它是后果，绝不是认定。"},{"word":"finding","ipa":"/ˈfaɪndɪŋ/","tag":"inquiry output","definition":"The conclusion of an investigation or tribunal, which may or may not be phrased as a verdict.","definitionCN":"调查或裁判所的结论，可能以裁决的措辞表达，也可能不。"},{"word":"decision","ipa":"/dɪˈsɪʒn/","tag":"general word","definition":"Any settled choice, from a court or from a committee; it lacks the jury flavour of verdict.","definitionCN":"任何已定的选择，可出自法院或委员会；它不带陪审团色彩。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations use the real Latin true and saying, the real family and real fixed phrases.","cn":"正常联想使用真实的拉丁「真」与「陈述」、真实同族词与真实固定搭配。"},"normal":[{"en":"Vere is 'truly' and dictum is 'saying', so a verdict is a true saying, the sentence that settles what the facts are.","cn":"vere 是「真实地」，dictum 是「陈述」，所以裁决就是一句真话，一句了结事实的话。"},{"en":"The family runs verdict, dictum, predict, verify, verity and veracious.","cn":"同族词有 verdict、dictum、predict、verify、verity 与 veracious。"},{"en":"Fixed phrases mark the courtroom sense: reach a verdict, a guilty verdict, return a verdict.","cn":"固定搭配标出法庭义：作出裁决、有罪裁决、宣布裁决。"},{"en":"A verdict is the answer, a sentence is the consequence; English has kept them apart for centuries.","cn":"裁决是回答，量刑是后果；英语数百年来把两者分开。"},{"en":"Anyone who has weighed the evidence can issue a verdict, which is why the word escaped the courtroom.","cn":"任何权衡过证据的人都能作出裁决，这个词正是因此走出了法庭。"}],"abstract":[{"en":"Picture a folded slip of paper passed through a hatch before anyone speaks.","cn":"想象一张折好的纸条在所有人开口之前从窗口递出。"},{"en":"Picture twelve chairs pushed back at once, and the corridor filling with waiting people.","cn":"想象十二把椅子同时被推开，走廊里立刻挤满等候的人。"},{"en":"Picture a set of scales coming to rest, and the room deciding to believe the pointer.","cn":"想象一架天平静止下来，屋子里的人都决定相信那根指针。"}]},"examples":[{"en":"The jury reached its verdict after two days.","cn":"陪审团在两天后作出了裁决。"},{"en":"Historians have not yet delivered a verdict on that treaty.","cn":"历史学者尚未对那项条约给出定论。"},{"en":"The inquest recorded an open verdict because the cause was unclear.","cn":"因死因不明，验尸庭记录了存疑裁决。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「ver（真）+ dict（说）」——一句被认定为真的话 → 裁决","word":"verdict"},"root":"拉丁 verus「真」的副词 vere「真实地」+ dictum「陈述」（出自 dicere「说」）→ veredictum「真实宣告」→ 英属法语 verdit → 英语 verdict。","sensesIntro":{"en":"Eight senses follow one slip of paper: a jury writes it, an inquiry copies it, anyone who has weighed evidence can pronounce it, the public adopts it, a video panel borrows it, a competition uses it, a field trial produces it, and a court then decides what follows.","cn":"八个义项围绕一张纸条：陪审团写下它，调查照抄它，任何权衡过证据的人都能说出它，公众采纳它，视频裁判组借用它，比赛使用它，田间试验产出它，最后由法院决定接下来怎么办。"},"semanticMap":{"core":{"en":"CORE IMAGE: a folded slip handed through a hatch before anyone in the room speaks.","cn":"核心意象：一张折好的纸条在屋里所有人开口之前从窗口递出。"},"chain":["THE TRUE SAYING","THE JURY'S ANSWER","THE INQUIRY'S FINDING","THE WEIGHED OPINION","THE PANEL AND THE TEST","WHAT FOLLOWS"],"branches":[{"senses":"01 · 02","en":"TWO OFFICIAL VOICES: a jury and an inquiry both state what they find to be true.","cn":"两种官方声音：陪审团与调查都在陈述它们认定的真相。"},{"senses":"03 · 04","en":"FROM COURT TO PUBLIC: once it is simply a true saying, the public can speak it too.","cn":"从法庭到公众：既然它只是一句真话，公众也能说。"},{"senses":"05 · 06","en":"PANELS OF TWO KINDS: sport and competitions borrow the word because their finding must end the argument.","cn":"两种评审团：体育与比赛借用这个词，因为其结论必须终结争论。"},{"senses":"07","en":"THE TEST SPEAKS: a field trial can deliver a verdict, since settling a question is the original sense.","cn":"试验发言：田间试验也能给出裁决，因为「了结问题」正是原义。"},{"senses":"08","en":"THE ANSWER AND THE PRICE: the verdict answers the charge, and sentence pays for it.","cn":"回答与代价：裁决回答指控，量刑为其付出代价。"}]},"affixes":{"intro":{"en":"Verdict is two Latin words fused: an adverb of truth and a noun of saying. Both halves are productive elsewhere in English.","cn":"verdict 是两个拉丁词融合而成：一个表真的副词与一个表陈述的名词，两半在英语别处都有构词力。"},"latinIntro":{"en":"Latin verus gives verify, verity and veracious; dicere gives dictum, predict and contradict; the fusion gives verdict alone.","cn":"拉丁 verus 给出 verify、verity 与 veracious；dicere 给出 dictum、predict 与 contradict；融合形式只给出 verdict。"},"items":[{"word":"ver-","structure":"verus (Latin adjective)","meaning":"true","meaningCN":"真","example":"The first half supplies truth.","exampleCN":"前半提供「真」。"},{"word":"vere","structure":"adverb of verus","meaning":"truly","meaningCN":"真实地","example":"The form used inside the compound.","exampleCN":"复合词中使用的形式。"},{"word":"dict-","structure":"dicere (Latin verb)","meaning":"to say","meaningCN":"说","example":"The second half supplies saying.","exampleCN":"后半提供「说」。"},{"word":"dictum","structure":"dict- plus -tum","meaning":"a thing said","meaningCN":"所说的话","example":"The noun of the saying.","exampleCN":"表示陈述的名词。"},{"word":"veredictum","structure":"vere plus dictum","meaning":"a true declaration","meaningCN":"真实的宣告","example":"The Latin compound.","exampleCN":"拉丁复合词。"},{"word":"verdict","structure":"veredictum through French","meaning":"a jury's answer","meaningCN":"陪审团的回答","example":"The English descendant.","exampleCN":"英语后裔。"},{"word":"-ify","structure":"Latin -ificare","meaning":"to make","meaningCN":"使成为","example":"It builds verify, to make true or check.","exampleCN":"它构成 verify「核查」。"},{"word":"verify","structure":"verus plus -ify","meaning":"to check truth","meaningCN":"核查真伪","example":"The truth half on its own.","exampleCN":"「真」这一半的独立构词。"},{"word":"dictum","structure":"dict- plus -um","meaning":"saying; maxim","meaningCN":"格言；陈述","example":"The saying half on its own.","exampleCN":"「说」这一半的独立构词。"},{"word":"pre-","structure":"Latin prae- 'before'","meaning":"before","meaningCN":"在前","example":"It builds predict, to say beforehand.","exampleCN":"它构成 predict「预言」。"}],"latinEntries":[{"word":"verus","structure":"verus, vera, verum (adj.)","meaning":"true","meaningCN":"真的"},{"word":"dictum","structure":"dictum, dicti (n., second declension)","meaning":"saying, statement","meaningCN":"陈述；话语"},{"word":"veredictum","structure":"veredictum, veredicti (n., second declension)","meaning":"true declaration","meaningCN":"真实的宣告"},{"word":"veritas","structure":"veritas, veritatis (f., third declension)","meaning":"truth","meaningCN":"真理；真实"}],"derivatives":[{"word":"veracious","pos":"adj.","zh":"诚实的；真实的"},{"word":"verity","pos":"n.","zh":"真实；真理"},{"word":"dictum","pos":"n.","zh":"格言；正式陈述"},{"word":"predict","pos":"v.","zh":"预言"}]}}]);
